-- 제주로 관광지 목록 (poi_final_v4.csv, 536곳) — check_poi.py 자동 생성
-- 새 DB 적재 순서: jeju_schema.sql → 이 파일 → POI_SOURCE_MAP + POI.ai_recommend.sql
-- 현재 POI의 10개 입력 컬럼을 사용한다. hidden_at, deleted_at, ai_recommend는 기본값을 사용한다.
-- 이미 적재된 DB에 다시 실행하면 poi_id 기본키가 중복된다.
SET NAMES utf8mb4;
START TRANSACTION;

INSERT INTO `POI` (`poi_id`, `poi_name`, `address`, `latitude`, `longitude`, `category_code`, `region_id`, `description`, `detail_description`, `image_url`) VALUES
(1, '신비원', '제주특별자치도 제주시 노형동 291-25 전', 33.4494816, 126.4872233, 'EXPERIENCE', 4, '제주 돌에 식물을 심어 가꾼 석부작 작품을 전시한 테마공원이다.', '제주 돌에 식물을 심어 가꾼 석부작 작품을 전시한 테마공원이다.
크고 작은 작품을 실내와 야외에서 둘러보며 제주의 돌과 식물이 어우러진 모습을 볼 수 있다.', 'https://lh3.googleusercontent.com/gps-cs-s/ANWiy9Sru7oPvIIvqc_cpncKpzbLJDUzPDw0ltRCNZQjdl8JB5CvB3rwD6yaBPXMUQKz3cbhqfFFPYQcZYNrxv-nkr-xZQ2ZE7zAsgDMW98RLaoXWNSf5nF7farG-2N_mv5PqMScPqGhlg=s1360-w1360-h1020-rw'),
(2, '정방폭포', '제주특별자치도 서귀포시 송산동', 33.2446821, 126.5727732, 'NATURE', 3, '높은 해안 절벽에서 바다로 떨어지는 시원한 물줄기와 주상절리 절경을 만날 수 있는 명승 제43호이자 제주올레 6코스의 대표 명소', '높은 해안 절벽에서 바다로 떨어지는 시원한 물줄기와 주상절리 절경을 만날 수 있는 명승 제43호이자 제주올레 6코스의 대표 명소', 'https://api.cdn.visitjeju.net/photomng/imgpath/202409/25/2d76eeb2-7ffc-49d1-b087-4859ac38bdf3.webp'),
(3, '제주4.3평화공원', '제주특별자치도 제주시 조천읍 남조로 2023', 33.4462782, 126.6606466, 'NATURE', 1, '제주4.3평화공원은 제주4.3 희생자를 추모하고 사건의 역사적 의미를 되새기기 위해 조성된 공간이다.', '제주4.3평화공원은 제주4.3 희생자를 추모하고 사건의 역사적 의미를 되새기기 위해 조성된 공간이다. 공원에는 제주4.3평화기념관을 비롯해 위령제단, 위령탑, 봉안관 등 추모와 기록을 위한 다양한 시설이 자리한다.

제주4.3평화기념관에서는 사건의 배경과 전개 과정, 희생자들의 이야기와 이후 진상 규명 과정 등을 전시를 통해 살펴볼 수 있다. 공원 곳곳에는 희생자들의 이름과 기록을 남긴 추모 공간이 마련되어 있어 제주 현대사의 아픔을 기억하고 평화의 의미를 생각해볼 수 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202408/21/e5f84397-91c4-4a31-91b2-4bfd618b9259.webp'),
(4, '제주시민속오일시장', '제주특별자치도 제주시 오일장서길 26', 33.4958738, 126.4752888, 'COMMERCIAL', 4, '제주시에서 날짜 끝자리가 2일과 7일인 날에 열리는 전통시장이다.', '제주시에서 날짜 끝자리가 2일과 7일인 날에 열리는 전통시장이다.
농수산물부터 옹기, 의류, 생활용품까지 다양한 물건을 파는 장터가 펼쳐진다.
방문 후기에는 제주 먹거리를 맛보고 시장 골목을 둘러보는 재미가 소개된다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/80b158d5-eb73-40aa-af17-efb399d6bde5.webp'),
(5, '성산일출봉', '제주특별자치도 서귀포시 성산읍 일출로 284-12', 33.4619589, 126.9362444, 'NATURE', 1, '성산일출봉은 얕은 바다에서 화산이 분출하며 만들어진 응회구다.', '성산일출봉은 얕은 바다에서 화산이 분출하며 만들어진 응회구다. 정상에는 큰 분화구가 있고, 가장자리에 솟은 암봉들이 성곽처럼 둘러서 있어 지금의 이름이 붙었다. 정상에 오르면 분화구와 성산 마을, 우도와 바다가 한눈에 들어오며 일출 경관으로도 유명하다. 제주 화산섬과 용암 동굴의 일부로 유네스코 세계자연유산에 등재되어 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202409/20/b2087c57-7cb6-420d-a840-c6e7e581072e.webp'),
(6, '섭지코지', '제주특별자치도 서귀포시 성산읍 섭지코지로 107', 33.4239381, 126.9306092, 'NATURE', 1, '섭지코지는 제주 동부 해안에서 바다 쪽으로 뻗은 곶이다.', '섭지코지는 제주 동부 해안에서 바다 쪽으로 뻗은 곶이다. 초원과 해안 절벽을 따라 걸으며 신양해변과 성산일출봉을 조망할 수 있고, 봄에는 유채꽃이 해안 풍경에 색을 더한다. 붉은 화산쇄설물이 드러난 붉은오름과 선돌바위에서는 이 일대의 다양한 화산 지형을 볼 수 있다. 초원에는 조선시대에 위급한 소식을 전하던 협자연대도 남아 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202408/16/6efa0dd8-7e17-47b9-8265-caf514b7ccef.webp'),
(7, '충혼묘지', '제주특별자치도 제주시 노형동 산 17-3도', 33.4181558, 126.4899132, 'TRAIL', 4, '제주시 노형동에 있는 충혼묘지는 희생자를 기리는 묘역이다.', '제주시 노형동에 있는 충혼묘지는 희생자를 기리는 묘역이다.
제주 4·3과 한국전쟁 전후의 역사를 돌아보고 참배하는 장소다.
현재 국립제주호국원의 제1묘역에 해당한다. 4·3, 시작을 묻다', 'https://lh3.googleusercontent.com/gps-cs-s/ANWiy9TWyUaZ-uxrMeWx7HRAeWJjxilDfXkqjJpBppzMfO3QyH2ScWuk9QVJK9Ob6pWdFbNDrsmz0KmENT2jW9N61sjFHguPmLRPv5eHLzt51nZue-t1_ZtbPgD88o-OeEWlWkMPW6nlfy_qcgoS=s1360-w1360-h1020-rw'),
(8, '포도뮤지엄', '제주특별자치도 서귀포시 안덕면 산록남로 788', 33.3192708, 126.3858093, 'CULTURE', 2, '포도뮤지엄은 서귀포시 안덕면에 있는 실내 전시 공간이다.', '포도뮤지엄은 서귀포시 안덕면에 있는 실내 전시 공간이다.
다양한 생각을 나누는 문화 공간으로 전시를 둘러볼 수 있다.
방문 후기에는 찾아가는 길의 풍경과 전시가 모두 인상적이었다는 경험이 담겨 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202512/12/7a566c51-9dd5-40ea-bdc6-8810e344045c.webp'),
(9, '제주코코몽에코파크', '제주특별자치도 서귀포시 남원읍 태위로 536', 33.2749095, 126.7050669, 'THEME', 3, '코코몽에코파크는 아이와 함께 방문하기 좋은 캐릭터 테마공원이다.', '코코몽에코파크는 아이와 함께 방문하기 좋은 캐릭터 테마공원이다.
코코몽 조형물 앞에서 사진을 찍고 놀이시설과 열차를 즐길 수 있다.
방문 경험에는 비눗방울 놀이와 가족사진이 즐거운 추억으로 소개된다.', 'https://lh3.googleusercontent.com/grass-cs/AABkmLdGuQYYrAtSbdAtuh73j21jkaCznZXV2VY55KxATCxt7gU-ArsNOF7ChOG7BAQN4BnImM6n7xsNfFPgdlKaia7rTz2znJEefAnCdjXWgudA_IVJ2fkflOTqT8RHbIxDbbq7HtFKLw=s1360-w1360-h1020-rw'),
(10, '카멜리아힐', '제주특별자치도 서귀포시 안덕면 병악로 166', 33.2890116, 126.3713192, 'EXPERIENCE', 2, '카멜리아힐은 서귀포시 안덕면에 있는 동백 수목원으로 여러 지역에서 온 다양한 품종의 동백나무를 만날 수 있다.', '카멜리아힐은 서귀포시 안덕면에 있는 동백 수목원으로 여러 지역에서 온 다양한 품종의 동백나무를 만날 수 있다. 동백이 피는 계절에는 꽃길과 정원을 둘러보기 좋고, 여름에는 수국, 가을에는 억새와 핑크뮬리가 계절마다 다른 풍경을 만든다. 수목원 곳곳에는 숲길과 돌담길, 사진을 남길 수 있는 정원 공간이 조성되어 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202410/15/dbcf908a-9c8c-4fc0-947c-e71554472c23.webp'),
(11, '대정교회', '제주특별자치도 서귀포시 대정읍 추사로36번길 11', 33.2510928, 126.2797822, 'HISTORY', 2, '대정교회는 제주 기독교 순례길 4코스인 ‘화해의 길’에 자리한다.', '대정교회는 제주 기독교 순례길 4코스인 ‘화해의 길’에 자리한다.
제주 출신 첫 목사인 이도종 목사의 유해와 순교 기념비가 봉안되어 있다.
제주의 종교사와 4·3의 흔적을 돌아볼 수 있는 순례 장소다.', 'https://lh3.googleusercontent.com/gps-cs-s/ANWiy9RqlvqQLGqvO1EowlAftVSpmj5m-opFQJVRdju_SPCDRj4xOGTYqGAqA8ETLmrCIDptUqk59AdCk3ldGe5vyCVAiovPnFdGq_O6r15onvWiVYej6IXAO3MniUP3biwaUN7_kxs=s1360-w1360-h1020-rw'),
(12, 'ICC제주국제컨벤션센터', '제주특별자치도 서귀포시 중문관광로 224', 33.2412815, 126.4244569, 'NATURE', 3, '중문관광단지에 있는 제주국제컨벤션센터는 회의와 전시가 열리는 공간이다.', '중문관광단지에 있는 제주국제컨벤션센터는 회의와 전시가 열리는 공간이다.
건물 안에는 행사장과 회의실, 제주관광공사 중문면세점이 있다.
방문할 행사가 있다면 중문 관광 일정과 함께 둘러볼 수 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201908/08/0d898924-dd55-4563-936a-f5c4a87cd2f1.webp'),
(13, '협재해수욕장', '제주특별자치도 제주시 한림읍 한림로 329-10', 33.3938661, 126.2391575, 'NATURE', 2, '협재해수욕장은 제주시 한림읍의 서쪽 해안에 있으며 금능해수욕장과 이어진다.', '협재해수욕장은 제주시 한림읍의 서쪽 해안에 있으며 금능해수욕장과 이어진다. 조개껍질 가루가 섞인 밝은 모래사장과 맑은 바닷물이 어우러지고, 해변 앞에는 비양도가 보인다. 바닥 경사가 완만하고 물이 얕은 편이어서 가족 단위 방문객이 찾으며, 해 질 무렵에는 비양도 너머로 지는 해를 감상할 수 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202408/27/e8a13893-251e-4acc-9657-34ba532426ad.webp'),
(14, '표선해수욕장', '제주특별자치도 서귀포시 표선면 민속해안로 594', 33.3254563, 126.8424280, 'NATURE', 1, '표선해비치해변의 넓은 백사장 가까이에 기록된 야영 지점이다.', '표선해비치해변의 넓은 백사장 가까이에 기록된 야영 지점이다.
주변에서는 물때에 따라 달라지는 해변 풍경과 제주올레 4코스의 해안길을 만날 수 있다.
현재 야영 가능 여부와 이용 조건은 확인되지 않아 방문 전 확인이 필요하다.', 'https://tong.visitkorea.or.kr/cms/resource/07/3031507_image2_1.jpg'),
(15, '붉은오름자연휴양림', '제주특별자치도 서귀포시 표선면 가시리 산 158임', 33.4011901, 126.6759229, 'NATURE', 1, '붉은오름자연휴양림은 울창한 숲길을 걷고 야영하며 쉬어 갈 수 있는 곳이다.', '붉은오름자연휴양림은 울창한 숲길을 걷고 야영하며 쉬어 갈 수 있는 곳이다.
방문 후기에는 새소리와 빗소리를 가까이에서 들으며 캠핑한 경험이 담겨 있다.
밤하늘의 별과 조용한 숲의 분위기가 기억에 남았다는 이야기도 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/11/e91e2593-82f1-40e4-9d4c-321aa393be20.webp'),
(16, '중앙목장', '제주특별자치도 제주시 조천읍 비자림로 1065', 33.4346739, 126.7189598, 'LEISURE', 1, '중앙목장은 제주시 조천읍 비자림로에 기록된 목장이다.', '중앙목장은 제주시 조천읍 비자림로에 기록된 목장이다.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTnwXAY6ESfCxy-jKeDHvWBuPvguvBhWzTwocIQyw1Ltw&s'),
(17, '제주랜드ATV승마', '제주특별자치도 서귀포시 성산읍 난산리 2826목', 33.4135184, 126.8325232, 'LEISURE', 1, '서귀포시 성산읍에서 승마와 ATV 체험 장소로 소개된 곳이다.', '서귀포시 성산읍에서 승마와 ATV 체험 장소로 소개된 곳이다.
제주관광공사의 과거 소개에는 말을 타고 오름에 올라 주변 풍경을 바라보는 코스가 나온다.
체험 코스와 운영 여부는 달라졌을 수 있으므로 예약 전에 확인하는 것이 좋다.', 'https://lh3.googleusercontent.com/gps-cs-s/ANWiy9SyOY-sGCMSD7AjqnSj40xw5-irfMrFHLninercMjt0XAcKrg_kUHJi7bhqpNAlb3DvL0R3lLS6U_E1eEUfU_YE2x78FwJIhPLEjdzlmzRdT4XegvlwAVvULZVThaI-yKlEgTbn1Q=s1360-w1360-h1020-rw'),
(18, '헬로키티아일랜드', '제주특별자치도 서귀포시 안덕면 한창로 340', 33.2899533, 126.3520703, 'THEME', 2, '헬로키티아일랜드는 캐릭터 전시와 조형물을 둘러보는 실내 테마공간이다.', '헬로키티아일랜드는 캐릭터 전시와 조형물을 둘러보는 실내 테마공간이다.
분홍빛 공간 곳곳에서 헬로키티를 배경으로 사진을 남길 수 있다.
방문 후기에는 아이가 제주 여행 중 특히 가고 싶어 했던 곳으로 소개된다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/03/492de2bd-6669-4bbf-a879-0da3e6524c2f.webp'),
(19, '고성오일시장', '제주특별자치도 서귀포시 성산읍 고성오조로 93', 33.4519350, 126.9132441, 'COMMERCIAL', 1, '고성장은 제주도 동부 관광명소인 성산일출봉이 있는 성산읍사무소 소재지 마을인 고성리에 위치하고 있으며 국도 12번 도로에 접하고 있다.', '고성장은 제주도 동부 관광명소인 성산일출봉이 있는 성산읍사무소 소재지 마을인 고성리에 위치하고 있으며 국도 12번 도로에 접하고 있다. 1984년 현재 위치로 이설 한 후, 성산읍 주민은 물론 인근 우도면과 구좌읍 주민들도 이용하는 비교적 큰 5일장이다. 도심의 오일시장과는 사뭇 다른 시골장터 분위기를 느낄 수 있다. 특별한 상품보다는 청과물, 수산물, 정육, 생활용품, 의류, 농기구, 잡화 등 생활에 필요한 모든 물품이 갖추어져 있어 없는 것이 없다는 표현이 어울린다. 그리고 근처에는 제주 명소들이 인접해 있어 부담없이 둘러볼 수 있다. 성산읍의 정취와 정겨움을 느끼고 싶다면 고성오일시장을 방문해 보는 것을 추천한다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/d6c39d22-223c-4368-8599-e2277f1188e8.webp'),
(20, '오설록티뮤지엄', '제주특별자치도 서귀포시 안덕면 서광리 1235-1대', 33.3064391, 126.2908480, 'CULTURE', 2, '제주의 차 문화와 역사를 살펴볼 수 있는 박물관이다.', '제주의 차 문화와 역사를 살펴볼 수 있는 박물관이다.
전시를 둘러본 뒤 주변 녹차밭을 걸으며 풍경을 즐길 수 있다.
방문 후기에는 차 문화 행사와 차밭 산책이 기억에 남는다는 이야기가 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202408/21/2aa92c1e-5dec-48f0-a3f5-ef5bb271bb51.webp'),
(21, '조랑말타운승마장', '제주특별자치도 서귀포시 표선면 번영로 2486', 33.4079372, 126.7721465, 'COMMERCIAL', 1, '서귀포시 표선면에서 말을 가까이 만나고 승마를 체험할 수 있는 곳이다.', '서귀포시 표선면에서 말을 가까이 만나고 승마를 체험할 수 있는 곳이다.
방문 후기에는 말 먹이주기와 야외 놀이를 함께 즐긴 경험이 소개된다.
아이와 함께 말과 교감하며 시간을 보낸 이야기도 찾아볼 수 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202407/11/b9b9c4e2-1f97-495f-98fe-ff2bdf44992c.webp'),
(22, '신화테마파크', '제주특별자치도 서귀포시 안덕면 신화역사로304번길 98', 33.3055711, 126.3153838, 'THEME', 2, '여러 놀이기구와 게임, 공연을 한곳에서 즐길 수 있다.', '여러 놀이기구와 게임, 공연을 한곳에서 즐길 수 있다.
구역마다 다른 볼거리가 있어 가족 단위로 둘러보기 좋다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202301/02/e9f4ba08-53a6-4768-89bb-ee21835224ac.webp'),
(23, '1965올레시장54번가', '제주특별자치도 서귀포시 중정로61번길 20', 33.2496683, 126.5629641, 'COMMERCIAL', 3, '서귀포매일올레시장 안에 청년 점포가 들어선 공간이다.', '서귀포매일올레시장 안에 청년 점포가 들어선 공간이다. 시장 골목을 걸으며 먹거리와 상점들을 함께 둘러볼 수 있다. 같은 주소의 올레야시장 후기에는 여러 음식을 골라 먹은 경험이 소개된다.', 'https://cdn.newsjeju.net/news/photo/201905/329368_416339_220.jpg'),
(24, '수목원테마파크', '제주특별자치도 제주시 연동 1320 대', 33.4706504, 126.4884346, 'THEME', 4, '수목원테마파크(아이스뮤지엄)는 날씨에 상관없이 즐길 수 있는 실내 공간으로 1년 내내 다양한 얼음조각과 시원하고 스릴 넘치는 얼음 썰매를 즐길…', '수목원테마파크(아이스뮤지엄)는 날씨에 상관없이 즐길 수 있는 실내 공간으로 1년 내내 다양한 얼음조각과 시원하고 스릴 넘치는 얼음 썰매를 즐길 수 있다. 이색적인 공간과 더불어 세상에 없던 재미를 선사하는 짜릿한 가상 현실 VR 체험 등 다양한 즐길 거리가 있다. 테마파크 주변으로는 대한민국 최초의 소나무 숲 안에 조성된 자연 그대로의 형태를 갖춘 야시장과 LED 공원 주변으로 다양한 먹거리와 여행 중 피로를 풀어 줄 족욕 체험도 있어 제주 자연을 느낄 수 있는 ‘도심 속 작은 휴식처’로 관광객들에게 다양한 콘텐츠를 제공하는 제주 최대 규모 복합 관광지이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/9bf34a74-0bd5-4394-95be-c088b44805c6.webp'),
(25, '항파두리 항몽유적지', '제주특별자치도 제주시 애월읍 항파두리로 50', 33.4527479, 126.4079226, 'HISTORY', 2, '고려시대 몽골의 침략에 끝까지 저항했던 삼별초가 최후까지 항전하여 호국충정의 혼을 일깨울수 있는 역사유적지', '고려시대 몽골의 침략에 끝까지 저항했던 삼별초가 최후까지 항전하여 호국충정의 혼을 일깨울수 있는 역사유적지', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/c38b3538-8ab8-49b6-b15f-903fff647b80.webp'),
(26, '천지연폭포', '제주특별자치도 서귀포시 서홍동 2565천', 33.2470217, 126.5545580, 'NATURE', 3, '천지연폭포는 서귀포의 물길이 절벽 아래 깊은 연못으로 떨어지는 폭포다.', '천지연폭포는 서귀포의 물길이 절벽 아래 깊은 연못으로 떨어지는 폭포다. 천지연이라는 이름은 하늘과 땅이 만나 이룬 연못이라는 뜻을 담고 있다. 폭포 주변에는 구실잣밤나무와 동백나무 등이 자라는 난대림이 펼쳐지고, 숲을 따라 산책로가 이어진다. 계곡의 담팔수 자생지와 난대림, 연못의 무태장어 서식지는 천연기념물로 보호되고 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/9533606a-132c-430d-990b-f7ff12d37725.webp'),
(27, '남송악', '제주특별자치도 서귀포시 안덕면 서광리 산 31임', 33.3122139, 126.3068194, 'TRAIL', 2, '남송이오름,남소로기오름은 서귀포시 안덕면 서광리에 있는 표고 339m오름이다.', '남송이오름,남소로기오름은 서귀포시 안덕면 서광리에 있는 표고 339m오름이다. 남송이는 남생이가 변화된 어원이라고한다. 즉,오름의 형태가 얼굴을 내민 남생이와 같은 모습이라하여 붙인이름이라고한다. 지도상에는 남송악으로 표기되어 있으며,서광목장 에코힐링마로 코스로 사색하며 천천히 걷고있으면 나도모르게 힐링이 되는 오름이다.', 'https://www.jejunews.com/news/photo/201705/2013063_132433_336.jpg'),
(28, '아르떼뮤지엄', '제주특별자치도 제주시 애월읍 어림비로 478', 33.3966970, 126.3449783, 'CULTURE', 2, '국내 최대의 몰입형 미디어아트 뮤지엄', '국내 최대의 몰입형 미디어아트 뮤지엄', 'https://api.cdn.visitjeju.net/photomng/imgpath/202608/24/7c3d6556-a3a8-4611-9b3c-2b67ed8b7526.jpg'),
(29, '에코랜드테마파크', '제주특별자치도 제주시 조천읍 교래리 385-1 임', 33.4448176, 126.6793360, 'THEME', 1, '기차를 타고 감상하는 곶자왈 숲속 테마공원', '기차를 타고 감상하는 곶자왈 숲속 테마공원', 'https://api.cdn.visitjeju.net/photomng/imgpath/202506/10/ce1a35b1-fb88-498b-8b74-3318ebd56c0f.webp'),
(30, '곽지해수욕장', '제주특별자치도 제주시 애월읍 곽지리 1565임', 33.4509085, 126.3051464, 'NATURE', 2, '시원한 용천수를 뿜어내는 노천탕이 있는 곳', '시원한 용천수를 뿜어내는 노천탕이 있는 곳', 'https://api.cdn.visitjeju.net/photomng/imgpath/202110/25/4e19a935-3794-4891-94a2-7e89759e14b3.webp'),
(31, '중문색달해수욕장', '제주특별자치도 서귀포시 예래동', 33.2450870, 126.4103336, 'NATURE', 3, '중문색달해수욕장은 아름다운 해안 풍경과 야자수의 이국적인 모습을 가진 해변으로 중문관광단지에서 시작해 천제연폭포와 대포주상절리와 이어지는 곳에…', '중문색달해수욕장은 아름다운 해안 풍경과 야자수의 이국적인 모습을 가진 해변으로 중문관광단지에서 시작해 천제연폭포와 대포주상절리와 이어지는 곳에 있다. 해변의 길이가 약 560미터에 달하는 활처럼 굽은 백사장으로 해마다 100만 명이 넘는 사람들이 다양한 해양 스포츠를 즐기기 위해 몰려든다. 본래는 진모살이라고 불렸는데 긴 모래 해변이라는 뜻이다. 이곳의 모래는 흑색, 회색, 적색, 백색 4가지가 섞여 있어 해가 비추는 방향에 따라 해변의 색깔이 달라 보이며 제주도 특유의 검은 돌인 화산석과 아름다운 조화를 이루고 있다. 다른 해수욕장보다 파도가 잦고, 높은 편이라 서퍼들에게 인기가 많고, 국내의 가장 큰 규모의 국제 서핑 대회가 매년 6월에 개최된다.
이 밖에도 수상스키, 윈드서핑, 스쿠버다이빙, 제트보트 등 함께 즐길 수 있는 수상 레저 활동이 많아 수상 레저 마니아들이 좋아하는 해변으로 알려져 있다. 1999년 환경운동연합이 실시한 수질환경성 조사 결과 전국 44개 해수욕장 가운데 최고의 청정 해수욕장으로 꼽히기도 했다. 색달해변이 한눈에 보이는 쉬리의 언덕은 이곳의 또 다른 명소로 영화 쉬리의 마지막 장면의 촬영지이기도 하며 제주에서 가장 아름다운 일출과 일몰을 볼 수 있는 장소이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202407/24/9562c8bf-e728-4cfc-8eea-f23f576918d4.webp'),
(32, '바이나흐튼 크리스마스박물관', '제주특별자치도 서귀포시 안덕면 평화로 654', 33.2913123, 126.3278107, 'HISTORY', 2, '서귀포시 안덕면에 위치한 바이나흐튼 크리스마스 박물관은 주인 부부가 여행하며 모은 크리스마스 장식과 관련 물품이 전시되어 있다.', '서귀포시 안덕면에 위치한 바이나흐튼 크리스마스 박물관은 주인 부부가 여행하며 모은 크리스마스 장식과 관련 물품이 전시되어 있다. 독일어로 크리스마스를 뜻하는 ‘바이나흐튼’과 독일의 건축물을 참고해 만들어 유럽의 크리스마스 느낌이 물씬 나는 공간이다. 개인 박물관치곤 전시물의 종류도 다양하고 소장 가치가 뛰어난 것도 많은 편이다. 일 년 내내 크리스마스 분위기를 느낄 수 있는 곳이지만 이곳의 12월은 조금 더 특별하다. 크리스마스를 맞기 전, 한 달간 크리스마스 마켓 때문이다. 매년 수많은 셀러들이 참여, 크리스마스와 관련된 다양한 라이프스타일 제품들을 판매하며, 유명 셰프들이 만드는 다채로운 요리와 관람객 누구나 참여할 수 있는 다양한 체험 프로그램들이 마련된다.', 'https://tong.visitkorea.or.kr/cms/resource/82/3548182_image2_1.jpg'),
(33, '애월초교더럭분교장', '제주특별자치도 제주시 애월읍 하가로 195', 33.4534513, 126.3455047, 'TRAIL', 2, ': 세계적인 색채 디자이너 장 필립 랑클로(Jean-Philippe Lenclos)가 디자인한 알록달록한 파스텔톤 색채 외관으로 유명하며, 제…', ': 세계적인 색채 디자이너 장 필립 랑클로(Jean-Philippe Lenclos)가 디자인한 알록달록한 파스텔톤 색채 외관으로 유명하며, 제주 서쪽의 대표적인 사진 명소입니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/5d2edb2b-8370-4d2e-9e23-f9c83f58d109.webp'),
(34, '제주동문시장', '제주특별자치도 제주시 동문로 16', 33.5127895, 126.5283174, 'COMMERCIAL', 4, '각종 갈옷, 한복, 옷감 등 포목점을 주로 이루는 상가건물형 상설시장', '각종 갈옷, 한복, 옷감 등 포목점을 주로 이루는 상가건물형 상설시장', 'https://api.cdn.visitjeju.net/photomng/imgpath/202110/27/6c75266f-f1d0-413b-9ebb-a2cc6e916389.webp'),
(35, '더마파크', '제주특별자치도 제주시 한림읍', 33.3541303, 126.2443250, 'THEME', 2, '세계 최초의 말 전문 테마공원입니다.', '세계 최초의 말 전문 테마공원입니다. 직접 말을 타고 체험 할 수 있는 승마 와 기마공연등 말의 고장 제주도에서 말에 관. 모든 것을 즐길 수 있습니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/cbb7d8aa-35c3-426d-bb72-ccfb4c9dd973.webp'),
(36, '도들봉공원', '제주특별자치도 제주시 도두일동 산 1임', 33.5081204, 126.4684454, 'NATURE', 4, '도두봉은 제주 국제공항 바로 옆에 위치한 오름으로, 완만한 경사로 오르기 쉬운 코스입니다.', '도두봉은 제주 국제공항 바로 옆에 위치한 오름으로, 완만한 경사로 오르기 쉬운 코스입니다. 남쪽 사면은 풀밭과 소나무가 드문드문 자라 있고, 북쪽 사면은 삼나무와 활엽수림으로 이루어져 있습니다. 봉우리는 두 개인데, 동쪽 봉우리가 더 높습니다.', 'https://minio.nculture.org/amsweb-opt/multimedia_assets/187/72571/65874/c/%EB%8F%84%EB%91%90%EB%B4%89%EC%95%88%EB%82%B4%EB%8F%84-medium-size.jpg'),
(37, '상효원수목원', '제주특별자치도 서귀포시 상효동 산 28임', 33.3065159, 126.5839968, 'NATURE', 3, '제주의 자생식물을 볼 수 있는 수목원', '제주의 자생식물을 볼 수 있는 수목원', 'https://api.cdn.visitjeju.net/photomng/imgpath/201908/19/18c96cef-e38e-4403-8e8c-892c0dde6b91.webp'),
(38, '이호테우해수욕장', '제주특별자치도 제주시 이호동', 33.4970579, 126.4505033, 'NATURE', 4, '붉은 조랑말과 흰 조랑말의 극명하게 대조되는 색감이 이국적인 풍경을 선사하는 해변', '붉은 조랑말과 흰 조랑말의 극명하게 대조되는 색감이 이국적인 풍경을 선사하는 해변', 'https://api.cdn.visitjeju.net/photomng/imgpath/201808/08/41382152-d67e-46e1-9167-b5ea4ef84068.webp'),
(39, '세화해변', '제주특별자치도 제주시 구좌읍 세화리', 33.5252000, 126.8603000, 'NATURE', 1, '제주 동쪽 구좌읍 세화리 바닷가에 있는 해변이다.', '제주 동쪽 구좌읍 세화리 바닷가에 있는 해변이다.', ''),
(40, '만장굴', '제주특별자치도 제주시 구좌읍 만장굴길 182', 33.5283816, 126.7716147, 'NATURE', 1, '만장굴은 거문오름의 화산 활동으로 만들어진 용암동굴계에 속한다.', '만장굴은 거문오름의 화산 활동으로 만들어진 용암동굴계에 속한다. 동굴 안에는 용암이 흐르며 남긴 지형과 여러 형태의 동굴 생성물을 관찰할 수 있어 제주의 화산 역사를 살펴보는 장소로 알려져 있다. 거문오름용암동굴계는 제주 화산섬과 용암 동굴의 구성 유산으로 유네스코 세계자연유산에 등재되어 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202608/12/71968712-4e81-415a-bc16-703f03a8937b.jpg'),
(41, '조랑말박물관', '제주특별자치도 서귀포시 표선면 녹산로 381-15', 33.3830767, 126.7363199, 'EXPERIENCE', 1, '조랑말체험공원은, 조선시대에 왕에게 진상되던 최고의 말을 사육했던 갑마장이 있던 가시리마을 자리에 조성된 공원으로 600년 목축 문화의 역사를…', '조랑말체험공원은, 조선시대에 왕에게 진상되던 최고의 말을 사육했던 갑마장이 있던 가시리마을 자리에 조성된 공원으로 600년 목축 문화의 역사를 녹여 만든 조랑말박물관, 너른승마체험장, 마음카페. 등을 운영하고 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202407/11/b9b9c4e2-1f97-495f-98fe-ff2bdf44992c.webp'),
(42, '보롬왓', '제주특별자치도 서귀포시 표선면 번영로 2350-104', 33.4134994, 126.7525343, 'EXPERIENCE', 1, '보롬왓은 전국 최대 메밀산지인 제주에서 자연과 사람이 서로 상생하는 ''같이의 가치'' 농업을 꿈꾸는 6차 산업 인증 농업회사입니다.', '보롬왓은 전국 최대 메밀산지인 제주에서 자연과 사람이 서로 상생하는 ''같이의 가치'' 농업을 꿈꾸는 6차 산업 인증 농업회사입니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202110/29/e478e6c4-4a5f-40ec-9ded-36da33da5d9b.webp'),
(43, '천주교황사평성지', '제주특별자치도 제주시 기와5길 117-22', 33.4904757, 126.5598768, 'HISTORY', 4, '제주 지역 천주교의 역사와 신앙 문화를 살펴볼 수 있는 성지입니다.', '제주 지역 천주교의 역사와 신앙 문화를 살펴볼 수 있는 성지입니다. 종교적 의미와 지역의 역사적 이야기를 함께 간직하고 있습니다. 조용히 둘러보며 제주 천주교의 발자취를 느끼기 좋은 곳입니다.', 'https://info.catholic.or.kr/common/readImg.asp?ctxtOrgNum=2369&filenm=%C8%B2%BB%E7%C6%F2%5F%C0%FC%B0%E6%5FDSC00920%2EJPG'),
(44, '성이시돌목장', '제주특별자치도 제주시 한림읍 금악리 365-5 목', 33.3512170, 126.3260293, 'EXPERIENCE', 2, '성이시돌목장은 아일랜드인 맥글린치(한국명 임피제) 신부님이 1954년 제주 한림지역에 부임하면서 가난한 지역민을 돕기 위한 가축은행을 열면서…', '성이시돌목장은 아일랜드인 맥글린치(한국명 임피제) 신부님이 1954년 제주 한림지역에 부임하면서 가난한 지역민을 돕기 위한 가축은행을 열면서 시작되었다. 1961년 정식으로 중앙 실습 목장을 열고 축산업 교육과 함께 양돈, 면양, 비육우 및 낙농사업을 펼쳤으며 현재는 경주마와 젖소를 주로 사육하여 유수의 경주마와 유기농 우유를 생산하여 그 수익을 여러 복지사업에 사용하고 있다. 넓은 초지와 오랜 역사를 상징하는 ‘테쉬폰’ 등 근대건축물이 어우러져 이국적인 풍광을 즐길 수 있고, 목장의 우유를 이용한 카페와 신앙을 주제로 한 산책로와 공원 등을 방문할 수 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202110/28/f2223296-ce4a-4352-86fe-8e2b85f5edd3.webp'),
(45, '한라수목원', '제주특별자치도 제주시 수목원길 72', 33.4697839, 126.4932661, 'NATURE', 4, '제주 자생수종과 아열대 식물을 비롯한 다양한 식물을 관찰하며 산책할 수 있는 도심 속 수목원이다.', '제주 자생수종과 아열대 식물을 비롯한 다양한 식물을 관찰하며 산책할 수 있는 도심 속 수목원이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/10/3ee79bde-47e4-4659-90b4-1f4acb55253e.webp'),
(46, '스카이워터쇼', '제주특별자치도 제주시 구좌읍 번영로 2172-80', 33.4239312, 126.7441268, 'CULTURE', 1, '제주 스카이워터쇼는 구좌읍에 위치한 실내 공연장에서 상연되는 워터쇼이다.', '제주 스카이워터쇼는 구좌읍에 위치한 실내 공연장에서 상연되는 워터쇼이다. 대형 분수쇼와 고난도 다이빙쇼가 어우러지는 역동적이고 신기한 워터쇼로 외줄 타기 공연은 물론이고 고공낙하쇼 그리고 분수쇼까지 화려한 퍼포먼스와 환상적인 무대는 긴장감을 놓을 수 없는 재미를 선사한다. 또한, 물과 빛이 아름답게 어우러지는 국내 최초의 스카이 워터쇼로 손꼽힌다. 필리핀공연단, 러시아, 우즈베키스탄, 우크라이나 세계대회 우승 다이버 등 여러 나라의 공연단들과 함께 대형 분수쇼, 화려한 공중 퍼포먼스와 코믹하고 멋진 다이빙 쇼를 동시에 선보이고 있다. 공연이 끝나면 공연단들과 함께 사진 촬영도 가능하다. 아이가 있는 가족여행객뿐 아니라 부모님도 만족하는 공연으로 온 가족이 함께 즐기기 좋은 제주도 실내관광지이다. 주변으로 산굼부리분화구와 에코랜드가 있어 연계해서 방문해 보는 것도 좋다.', 'https://tong.visitkorea.or.kr/cms/resource/08/3037608_image2_1.jpg'),
(47, '한림공원', '제주특별자치도 제주시 한림읍 한림로 300', 33.3891904, 126.2401849, 'NATURE', 2, '제주 한림공원은 1971년 창업인 송봉규 선생이 10만여 평의 황무지 모래밭에 야자수 씨앗을 파종하여 육묘함으로써 탄생하게 된 비경지대이다.', '제주 한림공원은 1971년 창업인 송봉규 선생이 10만여 평의 황무지 모래밭에 야자수 씨앗을 파종하여 육묘함으로써 탄생하게 된 비경지대이다. 협재, 금릉 해수욕장의 비경과 아름다운 비양도의 경관을 마주하고 있는 제주도내 최고의 관광명소로 손꼽히고 있다. 10만여 평의 대지에 하늘로 우뚝 뻗은 야자수군락과 울창한 송림으로 둘러싸인 한림공원은 다양한 종류의 꽃과 나무가 사계절 아름다운 경관을 연출하며, 남국의 정취가 물씬 풍기는 야자수길, 분재와 돌을 소재로 하여 구성된 제주석분재원, 제주의 옛 모습을 재현한 재암민속마을 등 다양한 볼거리를 함께 갖추고 있다. 환상적인 9가지 다양한 테마가 펼쳐지는 한림공원은 장쩌민 중국 전 국가주석과 나까소네 전 일본수상을 비롯한 세계 각국의 저명인사들이 방문한 곳으로, 국내외 관광객이 찾는 세계적인 관광명소이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202205/30/e0145d42-16eb-4055-873c-ba683a16dede.webp'),
(48, '외돌개', '제주특별자치도 서귀포시 호근동 336 임', 33.2397525, 126.5433516, 'NATURE', 3, '바다 위에 홀로 우뚝, 우직한 외돌개', '바다 위에 홀로 우뚝, 우직한 외돌개', 'https://api.cdn.visitjeju.net/photomng/imgpath/202110/26/a434d9b2-a595-485f-89d6-1423bd989912.webp'),
(49, '용연구름다리', '제주특별자치도 제주시 용담이동 2581천', 33.5148841, 126.5143808, 'NATURE', 4, '용연구름다리는 제주공항 서쪽에 위치한 다리이다.', '용연구름다리는 제주공항 서쪽에 위치한 다리이다. 용연은 제주시 용담동에 위치한 계곡의 물이 유입되는 하천으로, 산등성이부터 바닷가로 흘러 바닷물과 민물이 만나 신비로움을 선사한다. 용연은 가뭄이 들어도 물이 마르지 않아 이곳에 살던 용이 승천해 비를 내리게 했다는 전설이 내려온다. 물이 풍부해 선인들이 풍류를 즐긴 장소로도 이용되었다. 출렁다리로 연결된 용연구름다리는 용연의 기암절벽 사이를 잇는, 현수교 형태이다. 붉은빛이 감도는 정자와 에메랄드빛 계곡이 어우러진 경관을 감상할 수 있다. 특히 야경이 멋진 곳으로, 저녁 산책코스로 좋다. 밤이면 다리에 켜지는 불빛들과 잔잔한 호수, 그리고 우거진 나무숲들이 어우러진 모습을 볼 수 있다. 또한 제주올레 17코스가 통과하는 곳으로 제주 자연의 아름다움과 은은함을 느낄 수 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202311/28/517a602c-0c88-4874-b6e8-6e0aa1b14326.webp'),
(50, '제주양떼목장', '제주특별자치도 제주시 애월읍 도치돌길 289-13', 33.4110747, 126.3654095, 'EXPERIENCE', 2, '제주 애월읍에 있는 제주 양떼목장은 양뿐만 아니라 염소, 말, 돼지 등 다양한 동물들을 만날 수 있는 자연 친화적인 공간이다.', '제주 애월읍에 있는 제주 양떼목장은 양뿐만 아니라 염소, 말, 돼지 등 다양한 동물들을 만날 수 있는 자연 친화적인 공간이다. 동물에게 먹이를 줄 수 있는 목장 체험은 물론이고, 신선한 산양유 커피를 맛볼 수 있는 목장 카페, 통나무 펜션까지 운영해 다른 체험 목장보다 풍성한 추억을 만들 수 있다. 다양한 프로그램이 있는 체험 목장에서 숙박까지 하는 이색 체험이 마련되어 있어 관광객에게 인기가 많은 관광지이다.', 'https://tong.visitkorea.or.kr/cms/resource/29/4073429_image2_1.jpg'),
(51, '걸매생태공원', '제주특별자치도 서귀포시 서홍동 462전', 33.2494716, 126.5556866, 'NATURE', 3, '봄을 알리는 매화가 가득한 시민공원.', '봄을 알리는 매화가 가득한 시민공원.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201903/12/9f94ece3-2dae-4baa-9ac8-fa87d3f031fc.webp'),
(52, '산방산탄산온천', '제주특별자치도 서귀포시 안덕면 사계북로41번길 192', 33.2486039, 126.2990062, 'THEME', 2, '제주 최초의 대중온천으로 알려진 국내에서도 보기 드문 탄산온천, 산방산 탄산온천', '제주 최초의 대중온천으로 알려진 국내에서도 보기 드문 탄산온천, 산방산 탄산온천', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/19/07c8d978-3c3c-49e1-9ae5-9b4b7a92ab61.webp'),
(53, '화조원', '제주특별자치도 제주시 애월읍 애원로 804', 33.4111284, 126.3719794, 'EXPERIENCE', 2, '제주 화조원(花鳥園)은 다양한 새들과 알파카 등 온순한 소동물들을 가까이에서 보고, 직접 만지며 교감할 수 있는 체험형 조류 동물원이다.', '제주 화조원(花鳥園)은 다양한 새들과 알파카 등 온순한 소동물들을 가까이에서 보고, 직접 만지며 교감할 수 있는 체험형 조류 동물원이다. 단순히 관람만 하는 공간이 아니라 아이부터 어른까지 자연스럽게 동물과 소통할 수 있도록 구성되어 있어 가족 단위 방문객들에게 특히 인기가 많다. 하루 4차례 진행되는 조류생태설명회에서는 사육사가 직접 새들의 생태와 습성을 설명해 주어 시간대에 맞춰 방문하면 더욱 알찬 관람이 가능하다. 조류 외에도 토끼, 잉어, 미니말 등 다양한 소동물에게 먹이를 주는 체험이 마련되어 있어 아이들이 배우며 즐거운 추억을 쌓을 수 있는 공간이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202607/16/a4676a11-8768-456c-9a1f-72b005d65875.jpg'),
(54, '서귀포항', '제주특별자치도 서귀포시 서귀동 758-5 잡', 33.2351603, 126.5700614, 'NATURE', 3, '우리나라 최남단에 위치하는 이 서귀포항은 한라산이 있어 여름철을 제외한 대부분이 평온한 해상 기온을 유지하고 있다.', '우리나라 최남단에 위치하는 이 서귀포항은 한라산이 있어 여름철을 제외한 대부분이 평온한 해상 기온을 유지하고 있다. 본래 기능은 어항이나 관광객을 받아들이는 관광항으로서의 기능도 커 오래전부터 관광잠수정 등의 해양 관광지로 각광을 받으며 현재는 잠수함과 유람선 제트보트 등 청명한 바다를 즐길 수 있는 레저시설이 있다. 서귀포항 주변은 해양 생태계 보전 지역 및 해양 보호 지역으로 지정되어 있는 등 환경 민감 자원이 다수 분포되어 있으며, 문섬과 새섬, 섶섬 등 아름다운 섬들이 펼쳐진 풍경도 서귀포항의 관광 자원에 한 몫 한다. 서귀포항에서 보이는 문섬 앞 바다는 푸른 바다 속 산호 풍경이 아름다워 다이버들이 즐겨 찾는 곳이기도 하다. 

(출처 : 비짓제주)', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/51fa1314-f59a-4f33-916e-855f4113cf13.webp'),
(55, '금능식물원', '제주특별자치도 제주시 한림읍 한림로 176', 33.3856925, 126.2270320, 'HISTORY', 2, '똑같이 생긴 하르방만 본 여행객들에게 제주 석물의 진수를 감상할 수 있게 하는 곳', '똑같이 생긴 하르방만 본 여행객들에게 제주 석물의 진수를 감상할 수 있게 하는 곳', 'https://api.cdn.visitjeju.net/photomng/imgpath/202205/30/fd593a05-2426-4e3e-bd17-5760419eb329.webp'),
(56, '서복전시관', '제주특별자치도 서귀포시 칠십리로 156-8', 33.2447173, 126.5708296, 'CULTURE', 3, '서복전시관은 중국 진나라 때 진시황의 불로장생의 꿈을 이루기 위해 불로초를 찾아 제주도로 왔다고 전해지는 서복을 기념하여 만든 전시관이다.', '서복전시관은 중국 진나라 때 진시황의 불로장생의 꿈을 이루기 위해 불로초를 찾아 제주도로 왔다고 전해지는 서복을 기념하여 만든 전시관이다. 1999년 2월 27일 문화관광부 전국 7대 문화관광권 개발 사업으로 지정되어 2003년 9월 26일 개관했다. 서복은 영주산에서 불로초를 구한 후 서귀포 앞바다 정방폭포 암벽에 "서복이 이곳을 지나갔다"라는 글자를 새겨 놓고 서쪽인 중국으로 돌아갔다고 전해진다. 서귀포의 지명도 ‘서쪽으로 돌아간 포구’에서 유래됐다는 이야기가 있다. 전시관에는 서복상을 비롯해 진시황릉의 청동마차, 병마용갱의 실물 복제품과 조각 작품들이 전시되어 있다. 중국 원자바오 총리의 실물 크기 사진과 촬영하는 포토존, 주변 해안 전망대와 쉼터 등이 조성되어 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202112/23/968cc936-9abe-4648-8a7b-d12fd67f2b06.webp'),
(57, '저지문화예술인마을', '제주특별자치도 제주시 한경면 저지14길 35', 33.3397863, 126.2656069, 'CULTURE', 2, '제주시 한경면 저지리에 위치한 저지예술마을, 일명 새오름이라 하는 저지악이 마을 중심에 있어 풍광이 독특하고, 전국의 유명 예술인들이 모여 작…', '제주시 한경면 저지리에 위치한 저지예술마을, 일명 새오름이라 하는 저지악이 마을 중심에 있어 풍광이 독특하고, 전국의 유명 예술인들이 모여 작품을 생산하는 문화예술인촌이 형성돼 있어 문화적 향취가 남다르다. 또 동양 최대의 분재 정원으로 알려진 생각하는 공원과 세계적으로도 희귀한 천연 난대림 지역인 곶자왈, 야생화가 지천인 방림원 등 이색 공간이 많아 제주의 문화와 함께 볼거리까지 풍성하게 돌아볼 수 있다.

(출처 : 제주 문화관광 홈페이지)', 'https://api.cdn.visitjeju.net/photomng/imgpath/202112/01/b87cc8a3-c01d-4119-802c-32bbd770b4d7.webp'),
(58, '우리승마장', '제주특별자치도 서귀포시 성산읍 중산간동로 4517', 33.3868304, 126.8123956, 'EXPERIENCE', 1, '성읍민속마을 근처에 위치한 우리승마장은 잘 훈련된 말 위에서 제주의 아름다운 풍경을 만끽하며 일상의 스트레스를 한 번에 날릴 수 있는 이색 승…', '성읍민속마을 근처에 위치한 우리승마장은 잘 훈련된 말 위에서 제주의 아름다운 풍경을 만끽하며 일상의 스트레스를 한 번에 날릴 수 있는 이색 승마체험장이다. 이곳의 말들은 성품이 온순하여 초보자는 물론, 아이도 안전하게 승마를 즐길 수 있다. 승마장 주변 드넓게 조성된 예쁜 꽃밭에서 개성 넘치는 포즈를 취하며 생생한 추억을 남길 수 있다. 특히 아이들에게 동물은 호기심과 즐거움의 대상이고 생명에 대한 존중, 호기심을 기르기에 동물과 직접 교감하는 것 만한 경험은 없을 것이다. 승마체험에 어울리는 카우보이모자, 장화 대여가 가능하고 안전상의 문제로 핸드폰을 소지한 채로 승마체험은 할 수 없으며 사진도 정해진 자리에서만 찍어야 한다. 또한 양산이나 우산도 사용 금지이다. 성읍마을 주변 방문 시 아이와 함께 짧게 즐기기에 좋고 승마체험이 끝난 후에는 말에게 당근 먹이 주기 체험도 가능하다. 무엇보다도 이곳의 경쟁력은 저렴하게 짧은 코스의 승마체험이 가능하다는 점이다. 따라서 성읍민속마을뿐만 아니라 표선해수욕장, 제주민속촌, 허브동산 등 성산 쪽 여러 관광지를 둘러보는 코스에 포함시켜 방문하길 추천한다.', 'https://tong.visitkorea.or.kr/cms/resource/35/3030935_image2_1.jpg'),
(59, '본태박물관', '제주특별자치도 서귀포시 안덕면 산록남로762번길 69', 33.3040383, 126.3921565, 'HISTORY', 2, '세계적인 건축가 안도다다오의 자연 친화적인 건축과 전통공예 · 현대미술의 조화', '세계적인 건축가 안도다다오의 자연 친화적인 건축과 전통공예 · 현대미술의 조화', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/04/c0e907e9-4cf5-4803-a3a5-bd3806b6e218.webp'),
(60, '라온더마파크', '제주특별자치도 제주시 한림읍 월림7길 155', 33.3547367, 126.2426487, 'CULTURE', 2, '승마·기마공연·카트를 즐기는 말 테마공원', '승마·기마공연·카트를 즐기는 말 테마공원', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/16/84fd9eab-8916-47b2-b2d9-db0fb87a1f8a.webp'),
(61, '서프라이즈테마파크', '제주특별자치도 제주시 조천읍 남조로 2243', 33.4656162, 126.6598717, 'THEME', 1, '서프라이즈테마파크는 문화예술계에서 주목하고 있는 재활용 소재를 활용한 장인정신의 숨결과 혼이 깃든 신비로운 정크아트 (Junk Art 폐품으로…', '서프라이즈테마파크는 문화예술계에서 주목하고 있는 재활용 소재를 활용한 장인정신의 숨결과 혼이 깃든 신비로운 정크아트 (Junk Art 폐품으로 만든 입체 예술작품)를 만나볼 수 있는 곳이다. 재활용 소재로 만들었으나 디테일과 크기는 그 어떤 작품 못지않은 정교함과 웅장함을 자랑한다. ‘SBS 세상에 이런 일이’에 방영된 깜짝 놀랄만한 세계 수준의 예술작품을 생동감 있게 구현한 영화 속 히어로들 그리고 애니메이션 주인공들과 함께 가까이에서 만날 수 있다. 다양한 크기와 형태로 작품화된 캐릭터를 통해 그들을 직접 만나고 체험해 봄으로써 흥미와 감동으로 아 동과 청소년들의 꿈을 키우고 용기와 진취적 기상을 심어줄 수 있는 계기가 될 것이다. 50,000여 평의 넓은 대지 위에 펼쳐진 500여 점의 작품과 주변 풍경의 파노라마는 전 지역이 포토존으 로 활용될 수 있어서 가족 단위의 나들이를 통해 추억의 시간을 간직할 수 있으며, 곶자왈둘레길 생태체 험 산책을 통해 삼림욕을 함으로써 웰빙을 구가할 수 있다. 또한 단체 학생들의 체험 활동을 통해 꿈과 끼를 키우는 감성 교육의 장으로 활용될 수 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202207/06/af880d88-514c-4389-b4fa-44fc59ec6a97.webp'),
(62, '새별헤이요목장', '제주특별자치도 제주시 애월읍 평화로 1529', 33.3630340, 126.3641169, 'EXPERIENCE', 2, '새별오름 인근의 제주 목장 풍경과 동물을 함께 경험할 수 있는 공간입니다.', '새별오름 인근의 제주 목장 풍경과 동물을 함께 경험할 수 있는 공간입니다. 넓은 초지와 자연 속에서 여유롭게 시간을 보내기 좋습니다. 가족 단위 방문이나 사진 촬영을 즐기기 좋은 체험형 장소입니다.', 'https://lh3.googleusercontent.com/gps-cs-s/ANWiy9QYToR7Q1MRUuJd5mMtzexfFOLww0BHqec1lFduqUPrwMi9LDIqHcQWLsV9pQry7kDWHTKeAB04ubOqCE-FzWQBSGiYXaZsZ4StfGm98hUePmeboR2NBrF9B47UKK-TzVOPmk8mZg=s1360-w1360-h1020-rw'),
(63, '제주국제평화센터', '제주특별자치도 서귀포시 중문관광로 227-24', 33.2451893, 126.4213758, 'CULTURE', 3, '제주국제평화센터는 2005년 제주특별자치도가 대한민국 정부로부터 세계평화의 섬으로 공식 지정되면서 상징시설인 제주국제평화센터를 서귀포시 중문관…', '제주국제평화센터는 2005년 제주특별자치도가 대한민국 정부로부터 세계평화의 섬으로 공식 지정되면서 상징시설인 제주국제평화센터를 서귀포시 중문관광단지 내에 건립하였다. 제주국제평화센터는 지상 2층, 지하 1층 건물에 4개의 전시실과 세미나실, 정보 자료실, 기념품 매장, 카페테리아 등의 부대 시설을 갖추고 있다. 제주국제평화센터는 다양한 시청각 자료들을 전시하고 있으며, 제주가 평화의 섬으로 지정되기까지의 정치적, 지리적, 환경적인 이유를 쉽고 자세하게 설명하고 있다. 전시실 내부의 한국어, 영어, 중국어 안내문은 국내 관람객뿐 아니라 제주를 찾는 해외 관광객들에게 동북아시아 평화의 중심으로서의 제주를 알리는 역할을 하고 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/7cdd9eb6-8040-4938-9e37-7bd5a9581608.webp'),
(64, '제주 세계자연유산센터', '제주특별자치도 제주시 조천읍 선교로 569-36', 33.4567416, 126.7149906, 'CULTURE', 1, '대한민국 최초의 세계자연유산으로서의 상징성을 위해 기념된 곳입니다', '대한민국 최초의 세계자연유산으로서의 상징성을 위해 기념된 곳입니다', 'https://api.cdn.visitjeju.net/photomng/imgpath/202112/08/c29d545c-bf68-462e-8606-510c50930951.webp'),
(65, '납읍목장', '제주특별자치도 제주시 애월읍 산록서로 15', 33.3902387, 126.3754269, 'EXPERIENCE', 2, '목장 매표 후 카페 이용이 가능하며 티켓은 1인 1매입니다.양과 새끼 염소 등의 동물들을 가까이서 볼 수 있는 체험 공간이 마련되어 있습니다.…', '목장 매표 후 카페 이용이 가능하며 티켓은 1인 1매입니다.양과 새끼 염소 등의 동물들을 가까이서 볼 수 있는 체험 공간이 마련되어 있습니다.외부 음식은 반입이 금지되어 있습니다.', 'https://cdn.jejusori.net/news/photo/202112/336071_349015_1242.jpg'),
(66, '방림원', '제주특별자치도 제주시 한림읍 월림리 115-224 임', 33.3382628, 126.2695818, 'NATURE', 2, '국내최초 세계야생화 작품 전시 박물관, 저지리 예술인 마을에 위치', '국내최초 세계야생화 작품 전시 박물관, 저지리 예술인 마을에 위치', 'https://api.cdn.visitjeju.net/photomng/imgpath/202205/30/725e93f1-8ed2-4290-84e3-431ac76b78b3.webp'),
(67, '이중섭미술관', '제주특별자치도 서귀포시 이중섭로 27-3', 33.2458618, 126.5648746, 'CULTURE', 3, '불운한 시대의 천재 화가 이중섭의 작품을 전시한 미술관', '불운한 시대의 천재 화가 이중섭의 작품을 전시한 미술관', 'https://api.cdn.visitjeju.net/photomng/imgpath/202409/06/eed44a97-f06d-4c3d-8014-65a3a01f45f0.webp'),
(68, '감귤박물관', '제주특별자치도 서귀포시 효돈순환로 441', 33.2712931, 126.6070117, 'HISTORY', 3, '주렁주렁 노랗게 익은 감귤을 직접 딸 수 있는 체험장', '주렁주렁 노랗게 익은 감귤을 직접 딸 수 있는 체험장', 'https://api.cdn.visitjeju.net/photomng/imgpath/202311/21/d37fb821-40fb-4510-b001-9415cc2f186d.webp'),
(69, '절물자연휴양림', '제주특별자치도 제주시 명림로 584', 33.4367638, 126.6284646, 'NATURE', 4, '삼나무 숲에서 즐기는 산림욕', '삼나무 숲에서 즐기는 산림욕', 'https://api.cdn.visitjeju.net/photomng/imgpath/202408/26/805247f8-451f-4ff7-88ec-d4512ee1fb3e.webp'),
(70, '용담공원', '제주특별자치도 제주시 용담이동 372전', 33.5140240, 126.5147319, 'NATURE', 4, '용담공원은 용두암 근처에 있는 작은 공원으로, 용연 다리와도 연결된 도심 속의 자그마한 쉼터이다.', '용담공원은 용두암 근처에 있는 작은 공원으로, 용연 다리와도 연결된 도심 속의 자그마한 쉼터이다. 근처 관광지인 용두암은 기암괴석 사이에 있는 용머리 모양의 관광 명소이며, 용연 다리는 용담 공원과 건너편을 잇는 거대한 출렁다리다. 밤이면 화려한 조명이 켜지면서 아름다운 야경을 자랑한다. 다리 건너편 용담공원은 비록 규모가 크지는 않지만, 오밀조밀 잘 꾸며놓아 산책하기에 좋다. 나무 벤치와 조각상이 설치되어 있어 해안을 바라보며 잠시 쉬었다가 갈 수도 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202112/08/02cadb7a-e2d4-4698-9dea-4e9e7fe17154.webp'),
(71, '9.81파크', '제주특별자치도 제주시 애월읍 천덕로 880-24', 33.3901786, 126.3665666, 'THEME', 2, '제주도의 중심 한라산과 비양도를 품은 푸른 바다를 마주하는 실외 공간과 ‘iF 디자인 어워드’를 수상한 감각적인 실내 공간을 모두 경험할 수…', '제주도의 중심 한라산과 비양도를 품은 푸른 바다를 마주하는 실외 공간과 ‘iF 디자인 어워드’를 수상한 감각적인 실내 공간을 모두 경험할 수 있는 테마파크다. 제주의 자연과 어우러져 전혀 새로운 형태의 스마트하고 다채로운 어트랙션과 트렌디한 부대시설을 즐기며 사랑하는 이들과 잊지 못할 특별한 추억을 만들어보자.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202310/17/84b1f251-5276-42e8-a56c-daacab394252.webp'),
(72, '왈종미술관', '제주특별자치도 서귀포시 칠십리로214번길 30', 33.2452893, 126.5736655, 'CULTURE', 3, '왈종미술관은 제주도 서귀포시 정방폭포 입구에 자리한 사립 미술관이다.', '왈종미술관은 제주도 서귀포시 정방폭포 입구에 자리한 사립 미술관이다. 이곳은 평생 동안 제주의 풍요로움과 아름다움을 화폭에 담아 온 이왈종 화백이 자신의 이름을 걸고 개관한 곳이다. 전체 넓이 300평(약 992㎡) 규모의 3층 건물로, 조선백자의 찻잔을 조형화한 모습이 파란 하늘과 짙푸른 바다를 배경으로 멋진 한 폭의 그림을 그려내는 것 같다. 미술관 1층은 어린이 미술교육실과 수장고, 도예실로 이루어졌고, 2층에 마련된 전시실에는 이 화백의 회화와 도예 작품 90여 점이 전시되어 있다. 3층은 이 화백의 작업공간으로 꾸며졌으며, 커피숍을 겸한 아트숍이 미술관 옆에 자리하고 있어 그림과 휴식을 함께 즐기는 복합 문화공간으로 이용할 수 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/b00f25ec-42b7-4251-a7a5-531f077ea4b4.webp'),
(73, '화순금모래해수욕장', '제주특별자치도 서귀포시 안덕면 화순해안로 69', 33.2400324, 126.3335893, 'NATURE', 2, '화순금모래 해변은 검은 모래밭이 펼쳐진 곳으로 주변에 천혜의 자연조건을 가지고 있다.', '화순금모래 해변은 검은 모래밭이 펼쳐진 곳으로 주변에 천혜의 자연조건을 가지고 있다. 해수욕장 옆으로는 소금막 해변 백사장이 넓게 펼쳐져 있고, 뒤로는 산방산이 서있으며, 앞으로는 가파도, 마라도, 형제섬 등이 한눈에 펼져쳐 있어 동양의 산수화를 연상케 하는 해변이다. 해수욕장의 모래는 검은 빛으로 부드럽고 고운편이며 여름이면 바로 옆에 야외수영장이 설치되어 해수욕과 담수욕을 동시에 즐길 수 있다. 야외수영장은 일년 내내 낮은 온도를 유지하는 용천수를 사용해 물이 무척 시원하며 슬라이딩 미끄럼틀 등의 기구를 설치해 아이들과 함께 물놀이 할 수 있다. 안덕면 소재지인 화순리에 있어서 교통, 숙박, 매점, 음식점 등의 편의 시설이 풍부하다는 점도 빼놓을 수 없다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/1870af1d-0694-450a-a960-b5743558461a.webp'),
(74, '바이제주', '제주특별자치도 제주시 노연로 81', 33.4861043, 126.4888047, 'COMMERCIAL', 4, '제주시 연동에 위치한 제주 관련 상품을 만나볼 수 있는 상업 공간입니다.', '제주시 연동에 위치한 제주 관련 상품을 만나볼 수 있는 상업 공간입니다. 여행 기념품이나 제주를 주제로 한 다양한 제품을 둘러보기 좋습니다. 시내 관광이나 쇼핑 일정과 함께 가볍게 방문하기 좋은 곳입니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202512/05/c39d8625-3adf-4f85-8e2e-e1e3971446f7.webp'),
(75, '아침미소목장', '제주특별자치도 제주시 첨단동길 160-20', 33.4550029, 126.5858278, 'EXPERIENCE', 4, '제주시 근교에서 방목 젖소와 목가적인 풍경을 만나고, 목장에서 생산한 유제품을 맛볼 수 있는 친환경 목장.', '제주시 근교에서 방목 젖소와 목가적인 풍경을 만나고, 목장에서 생산한 유제품을 맛볼 수 있는 친환경 목장.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/01/11fe3cc5-450b-4f3a-ab14-11a9e0b6d284.webp'),
(76, '피규어뮤지엄제주', '제주특별자치도 서귀포시 안덕면 한창로 243', 33.2817163, 126.3553772, 'CULTURE', 2, '국내 최대규모의 피규어 뮤지엄, 피규어 취향저격 기프트샵', '국내 최대규모의 피규어 뮤지엄, 피규어 취향저격 기프트샵', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/42161641-a82b-42d5-9648-7c75a07d498f.webp'),
(77, '산지등대', '제주특별자치도 제주시 사라봉동길 108-1', 33.5214796, 126.5457740, 'CULTURE', 4, '산지등대는 제주 사라봉 북쪽 비탈면에 있는 등대이다.', '산지등대는 제주 사라봉 북쪽 비탈면에 있는 등대이다. 일제강점기인 1916년 10월 무인 등대로 처음 설치했으며 1917년 3월 유인 등대로 변경되었고 1999년 12월에 새롭게 등탑을 신설했다. 100년 이상의 오랜 역사를 간직한 등대로 제주도를 대표한다. 산지라는 명칭은 조선 숙종 때 제작한 ‘탐라순력도’에 이곳이 산지촌으로 기록된 데서 유래했다. 처음에는 산저였다가 산지로 바뀌었다는 설도 있다. 
산지등대는 주변 경관이 뛰어나고 도심지와 가까운 위치에 있어 학생들의 등대 탐방 체험장소로도 인기가 있다. 일몰 때면 등대 앞쪽 바다에 수십 척의 고기잡이배들이 모여 수놓는 아름다운 야경도 볼 수 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202112/07/272be9bc-ac7c-41ea-9f8d-aa715205799f.webp'),
(78, '대성농장', '제주특별자치도 서귀포시 안덕면 병악로 44-33', 33.2801422, 126.3657592, 'EXPERIENCE', 2, '제주의 농촌 풍경과 지역 농업을 가까이에서 접할 수 있는 농장입니다.', '제주의 농촌 풍경과 지역 농업을 가까이에서 접할 수 있는 농장입니다. 계절과 운영 방식에 따라 다양한 농작물과 농장 풍경을 볼 수 있습니다. 제주 농촌의 한적한 분위기를 느끼며 둘러보기 좋은 곳입니다.', 'https://cdn.imweb.me/thumbnail/20210614/eb62754d29e31.gif'),
(79, '해녀박물관', '제주특별자치도 제주시 구좌읍 해녀박물관길 26', 33.5228343, 126.8634508, 'HISTORY', 1, '바당의 어멍 제주해녀의 삶을 느낄 수 있는 곳', '바당의 어멍 제주해녀의 삶을 느낄 수 있는 곳', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/08/0d4afd3d-f164-4685-bd89-61436f09be7f.webp'),
(80, '세계자동차&피아노박물관', '제주특별자치도 서귀포시 안덕면 중산간서로 1610', 33.2837201, 126.3497853, 'HISTORY', 2, '세계자동차 & 피아노 박물관은 2008년 아시아 최초 개인 소장 자동차 박물관 개관에 이어 2019년 한국 최초의 피아노 박물관을 개관하여 역…', '세계자동차 & 피아노 박물관은 2008년 아시아 최초 개인 소장 자동차 박물관 개관에 이어 2019년 한국 최초의 피아노 박물관을 개관하여 역사와 문화, 예술이 함께 공존하는 교육의 장이 되도록 노력하고 있는 곳이다.
인류 최고의 발명품 자동차, 자동차는 단순한 운송 수단이 아니라, 라이프 스타일의 상징이자 인류의 꿈과 미래를 담은 상징이기도 하다. 최초의 자동차에서 시작하여 각 시대를 대표하는 전 세계에서 수집된 100여 대의 자동차를 통해 자동차가 발전하는 역사와 문화를 만나 볼 수 있으며, 2019년 7월 개관한 피아노박물관은 세계적 조각가 오귀스트 로댕이 조각한 전 세계 단 하나뿐인 진귀한 피아노를 비롯해 베토벤, 쇼팽, 하이든 등 위대한 음악가들이 사랑했던 피아노의 특별한 스토리와 300년의 역사가 살아 숨 쉬는 피아노 예술품들이 전시되어 있다. 어린이들이 직접 피아노를 연주하거나 지휘를 하며 공연할 수 있는 복합음악 체험 공간이 마련되어 있다. 전시된 자동차와 피아노 관람과 더불어 어린이 무료 교통 체험, 음악 체험 , 사슴, 토끼 먹이 주기 체험을 할 수 있다. 이외에도 100여 종의 식물이 서식하고 있는 곶자왈 힐링 로드도 여유롭게 즐겨보기를 권한다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202207/06/335554bd-1dcf-4580-8b50-8d4452a41e35.webp'),
(81, '아라리오뮤지엄 탑동시네마', '제주특별자치도 제주시 탑동로 14', 33.5174201, 126.5233586, 'CULTURE', 4, '원도심속 버려진 건물을 개조해 만든 전시관', '원도심속 버려진 건물을 개조해 만든 전시관', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/3b15f398-8e0b-40be-82d4-37e9916fbab5.webp'),
(82, '제주연동오네프', '제주특별자치도 제주시 삼무로11길 9', 33.4926061, 126.4962579, 'EXPERIENCE', 4, '제주시 연동 지역에서 휴식과 여가를 즐길 수 있는 공간입니다.', '제주시 연동 지역에서 휴식과 여가를 즐길 수 있는 공간입니다. 도심 접근성이 좋아 주변 관광이나 식사 일정과 함께 방문하기 편리합니다. 제주 시내에서 가볍게 머물며 쉬어가기 좋은 장소입니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202407/24/94b5195f-87ed-4f37-92cd-cc2310ed6927.webp'),
(83, '소인국테마파크', '제주특별자치도 서귀포시 안덕면 중산간서로 1878', 33.2901890, 126.3225652, 'THEME', 2, '돌하루방 가족의 정원!', '돌하루방 가족의 정원! 디오라마 전시관을 관람하며 캐릭터 정원을 지나 무료로 운행되는 통통열차 탑승', 'https://api.cdn.visitjeju.net/photomng/imgpath/202505/13/e90e70ab-70a3-4ebe-9935-89b7cb7a328b.webp'),
(84, '세화민속오일시장', '제주특별자치도 제주시 구좌읍 해맞이해안로 1412', 33.5259486, 126.8571967, 'COMMERCIAL', 1, '세화민속오일시장은 세화 중심가 사거리에서 인접해 있어서 교통이 편리하고, 주민들과 상인들이 함께 어우러져 서로 사고 파는 제주 사람들의 진솔한…', '세화민속오일시장은 세화 중심가 사거리에서 인접해 있어서 교통이 편리하고, 주민들과 상인들이 함께 어우러져 서로 사고 파는 제주 사람들의 진솔한 삶의 모습을 들여다볼 수 있는 제주의 전통적인 재래시장이다. 우리나라 장이 거의 그렇듯 제주의 재래시장도 5일 간격으로 서는 오일장이며, 상품의 종류도 많고 가격도 저렴한 편이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202110/27/1efbaf5c-f767-4115-810a-adf1ed6f99d3.webp'),
(85, '여미지식물원', '제주특별자치도 서귀포시 색달동 2484-1 원', 33.2541723, 126.4170918, 'THEME', 3, '마음의 안식을 주는 대형 온실 식물원', '마음의 안식을 주는 대형 온실 식물원', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/02/da2c9853-630b-4527-9a7b-68c5c2634d64.webp'),
(86, '노루생이삼거리', '제주특별자치도 제주시 연동 산 146-9도', 33.4224010, 126.4931044, 'LEISURE', 4, '제주시 연동 일대에 위치한 삼거리로 주변 도로와 지역을 연결하는 지점입니다.', '제주시 연동 일대에 위치한 삼거리로 주변 도로와 지역을 연결하는 지점입니다. 관광시설보다는 이동 과정에서 지나게 되는 지역 지형·교통 지점에 가깝습니다. 인근 지역을 둘러보거나 이동할 때 위치를 확인하기 좋은 장소입니다.', 'https://cdn.newsje.com/news/photo/201704/91935_102309_311.jpg'),
(87, '가시리조랑말체험공원', '제주특별자치도 서귀포시 표선면 녹산로 381-15', 33.3830959, 126.7362847, 'EXPERIENCE', 1, '조랑말박물관은 가시리가 농림부의 신문화공간조성사업 지원을 받아서 설립한 국내 최초의 ''리립(里立)박물관''으로, 전시물을 천천히 둘러보고 나면…', '조랑말박물관은 가시리가 농림부의 신문화공간조성사업 지원을 받아서 설립한 국내 최초의 ''리립(里立)박물관''으로, 전시물을 천천히 둘러보고 나면, 제주마에 대한 전반적인 상식과 이해를 갖출수 있게 된다. 말과 관련된 유물 및 문화예술작품 100여 점이 박물관 자료로 소장되어 있어 제주의 목동 말테우리의 삶이 녹아있는 제주의 목축문화, 조랑말의 생태와 습성에 대한 내용들을 살펴볼 수 있고 조랑말을 주제로 도내에서 활동하는 작가들의 작품을 감상할 수 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202407/11/d52288df-bb4c-498b-8403-aaca148bc35c.webp'),
(88, '서귀포유람선', '제주특별자치도 제주시 한경면 노을해안로 1163', 33.3089133, 126.1654873, 'LEISURE', 2, '섬속의 섬 차귀도 둘레길 탐방과 수월봉, 차귀도의 절경 유람을 동시에 즐길 수 있는 유람선', '섬속의 섬 차귀도 둘레길 탐방과 수월봉, 차귀도의 절경 유람을 동시에 즐길 수 있는 유람선', 'https://api.cdn.visitjeju.net/photomng/imgpath/201907/03/2f12fc8c-9716-4f7a-8b99-5f2557a98429.webp'),
(89, '환상숲곶자왈공원', '제주특별자치도 제주시 한경면 녹차분재로 594-1', 33.3229067, 126.2630279, 'NATURE', 2, '제주도의 진짜 자연을 볼 수 있는 에코힐링여행', '제주도의 진짜 자연을 볼 수 있는 에코힐링여행', 'https://api.cdn.visitjeju.net/photomng/imgpath/202508/20/5819a814-f967-4e66-923f-fac97fae302a.webp'),
(90, '서귀포천문과학문화관', '제주특별자치도 서귀포시 1100로 506-1', 33.2888733, 126.4604181, 'CULTURE', 3, '서귀포천문과학문화관은 무병장수를 상징하는 별인 노인성을 관측하기에 최적의 장소로서 천문우주 관련 전시물들과 밤하늘의 천체 및 태양을 관측할 수…', '서귀포천문과학문화관은 무병장수를 상징하는 별인 노인성을 관측하기에 최적의 장소로서 천문우주 관련 전시물들과 밤하늘의 천체 및 태양을 관측할 수 있는 천체 망원경들을 보유하고 있으며 아울러 가상의 밤하늘과 디지털 영상을 상영할 수 있는 천체 투영실을 갖추고 있다. 노인성은 무병장수를 상징하는 별로 겨울이 되면 서귀포시 밤하늘에서 관측할 수 있는 별이다. 노인성은 고도가 매우 낮아 지구 북반구의 중위도 지역에서는 관측하기가 쉽지 않다. 북반구에 위치한 우리나라에선 매우 보기 어려운 별이어서 노인성을 볼 수 있는 제주는 노인성이 비치는 땅, 장수하는 사람이 많은 곳으로 여겨졌다. 천문과학문화관에는 주관측실, 천체투영실, 전시실, 강의실이 있으며 황도 12궁을 살펴볼 수 있는 야외조형물이 있다. 또한 별빛 체험 교실, 방학 천문교실 등의 천문우주과학교육 프로그램을 운영하고 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202008/28/4797c592-4502-4298-ac25-31d68b58400f.webp'),
(91, '세계술박물관', '제주특별자치도 서귀포시 표선면 한마음초등로 431', 33.3541183, 126.8175825, 'HISTORY', 1, '우리나라 전통주를 비롯하여 세계의 술의 역사를 알 수 있는 박물관', '우리나라 전통주를 비롯하여 세계의 술의 역사를 알 수 있는 박물관', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/bbeee928-9c57-4824-a8cb-bc104ff3a9fb.webp'),
(92, '산방산랜드', '제주특별자치도 서귀포시 안덕면 사계남로216번길 24-9', 33.2337761, 126.3115291, 'THEME', 2, '웅장하고 신비로운 산방산을 배경으로 우리나라에서 가장 높게 올라가는 짜릿한 바이킹을 즐거보세요', '웅장하고 신비로운 산방산을 배경으로 우리나라에서 가장 높게 올라가는 짜릿한 바이킹을 즐거보세요', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/0a1153e3-088a-4a99-a89b-4001ccb64fff.webp'),
(93, '중문랜드', '제주특별자치도 서귀포시 소보리당로164번길 62', 33.2636334, 126.3855125, 'EXPERIENCE', 3, '서귀포 중문 지역에서 다양한 레저와 체험 활동을 즐길 수 있는 복합 관광 공간입니다.', '서귀포 중문 지역에서 다양한 레저와 체험 활동을 즐길 수 있는 복합 관광 공간입니다. 가족이나 친구와 함께 가볍게 체험형 콘텐츠를 즐기기 좋습니다. 중문 관광 일정과 함께 방문하기 좋은 장소입니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/01/986c8136-faec-4682-b3a6-fc1d6251df3f.webp'),
(94, '일출랜드선인장하우스', '제주특별자치도 서귀포시 성산읍 중산간동로 4150-30', 33.3837073, 126.8409909, 'THEME', 1, '‘새로운 태양이 떠오르는 휴식 공간’이라는 주제로 설립된 일출랜드는 제주 토종 동백나무, 비자나무를 포함한 60만본의 식물들을 관리, 보존하고…', '‘새로운 태양이 떠오르는 휴식 공간’이라는 주제로 설립된 일출랜드는 제주 토종 동백나무, 비자나무를 포함한 60만본의 식물들을 관리, 보존하고 있으며, 사계절 꽃의 축제가 열리고 있는 식물원이다. 천연용암동굴인 미천굴을 중심으로 수변공원, 잔디광장, 제주종갓집초가, 화석원, 분재정원, 조각의 거리, 공예체험 아트센터, 선인장 온실, 아열대 식물원 등 다양한 테마로 구성되어 있어, 제주 청정 자연의 생태, 문화, 체험을 모두 만나볼 수 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202205/30/8d1fb97b-1ad0-48cc-9aa0-2ec519e9575c.webp'),
(95, '통나무파크', '제주특별자치도 제주시 애월읍 도치돌길 293', 33.4099524, 126.3657889, 'EXPERIENCE', 2, '통나무와 자연 소재를 활용한 독특한 분위기의 체험형 공간입니다.', '통나무와 자연 소재를 활용한 독특한 분위기의 체험형 공간입니다. 제주 자연과 어우러진 편안한 분위기 속에서 산책과 휴식을 즐길 수 있습니다. 가족 단위 방문객이 여유롭게 머물기 좋은 곳입니다.', 'https://lh3.googleusercontent.com/grass-proxy/AIM7gW1Lej9cgMIWGaSly0kXROFgMzFLIZ6TGlEvElfgcM47uhZSp47G91-U8yXBDuaorv3C2jvquSwC29Pau05ntk6cnUqAZ7UOHc0SdOiorMbdOh1F4Dyb-56ZNDgoYqDTGoLm_4SVbyWqHrsiS9qjxet5TPQcPQQ4gUptuiOYr3DjoK4TDgKZ6UuW=w324-h312-n-k-no'),
(96, '송당본향당(민속자료9-1)', '제주특별자치도 제주시 구좌읍 송당리 산 199-1임', 33.4684469, 126.7756882, 'HISTORY', 1, '제주 민간신앙의 자취를 확인할 수 있는 송당본향당', '제주 민간신앙의 자취를 확인할 수 있는 송당본향당', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/7c4987a6-d528-40fc-840b-c1877e7e07fa.webp'),
(97, '삼매봉도서관', '제주특별자치도 서귀포시 남성중로153번길 15', 33.2444313, 126.5521091, 'CULTURE', 3, '삼매봉도서관은 제주특별자치도에 있는 15개의 공공도서관 중 한 곳으로 서귀포시 서홍동 기당미술관 옆에 있다.', '삼매봉도서관은 제주특별자치도에 있는 15개의 공공도서관 중 한 곳으로 서귀포시 서홍동 기당미술관 옆에 있다. 다양한 자료를 수집 및 제공함으로써 도민의 독서 생활화에 기여하고 있으며, 다양한 계층별 독서 문화 프로그램을 통해 도민들의 평생교육 실현에 앞장서고 있는 문화 소통의 복합 공간이다. 천장에는 외부를 그대로 보여주고 있어 바깥 풍경을 볼 수 있으며, 실내에 식물들이 식재되어 있어 편안한 느낌을 준다.
이곳은 제주 올레길 중 가장 인기가 많은 제주 올레 7코스에 포함되어 있어 오름도 오르고 독서도 하며 휴식을 취하고 싶다면 삼매봉도서관이 제격이다.', 'https://tong.visitkorea.or.kr/cms/resource/49/3383849_image2_1.jpg'),
(98, '뽀로로앤타요테마파크', '제주특별자치도 서귀포시 안덕면 병악로 269', 33.3004579, 126.3708050, 'THEME', 2, '아이들에게 인기만점인 캐릭터 뽀로로와 타요를 만날 수 있는 테마파크 다양한 어트랙션이 실내와 실외에 골고루 있어 비가 와도 문제없이 즐길 수…', '아이들에게 인기만점인 캐릭터 뽀로로와 타요를 만날 수 있는 테마파크
다양한 어트랙션이 실내와 실외에 골고루 있어 비가 와도 문제없이 즐길 수 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202002/06/19eb3655-5106-418e-b7b8-0e0ba24dbd31.webp'),
(99, '산굼부리', '제주특별자치도 제주시 조천읍 비자림로 768', 33.4342353, 126.6888240, 'NATURE', 1, '산굼부리는 천연기념물로 둘레가 2㎞가 넘는 화구이다.', '산굼부리는 천연기념물로 둘레가 2㎞가 넘는 화구이다. 제주도에는 360여 개의 기생화산이 분포되어 있지만 이곳 산굼부리를 제외한 다른 화산은 모두 대접을 엎어놓은 듯한 분화구의 형태이고, 산굼부리 분화구만은 제주도에서 유일하게 용암이나 화산재의 분출 없이 폭발이 일어나 그곳에 있던 암석을 날려 그 구멍만이 남게 된 것이다. 이러한 화산을 마르(Maar)라고 부르는데 한국에는 하나밖에 없는 세계적으로도 아주 희귀한 화산이다.

특히, 산굼부리 밑바닥에는 틈이 많아서 물이 모두 스며들기 때문에 이 화구 안에는 식물의 생태계가 특이하게 분포되어 있다. 분화구의 내부높이에 따라 온대와 난대지역이 형성되어 있고 태양이 비치는 일사량과 일조시간에 따라 다양한 분포를 이루고 있다. 즉, 햇볕이 잘 드는 북쪽벼랑은 난대지역을 이뤄서 붉가시나무를 비롯해서 후박나무, 구실잣밤나무, 센달나무 등 상록활엽수군이 형성되어 있으며, 그 아래층에는 금새우란과 같은 희귀 식물과 자금우, 겨울딸기 등이 분포되어 있다. 또한, 햇볕이 잘 들지 않는 남쪽벼랑에는 북쪽과는 판이한 분포를 이루는 상수리나무를 비롯하여 졸창나무, 산딸나무, 단풍나무, 곰솔등 온대성낙엽수 군락이 진을 치고 있다.

뿐만 아니라, 다른 곳에서는 보기 힘든 왕쥐똥나무군락을 비롯해서 상산 군락, 제주조릿대군락, 복수초군락, 변산바람꽃군락등이 매우 화려하고 완벽하게 보존되어 있음은 학술적으로도 연구 가치가 매우 높게 평가되고 있다. 그리고 노루와 오소리 등의 포유류를 비롯하여 조류, 파충류 등 야생동물들의 서식처로도 유명하다. 봄에는 분화구 밑바닥에서 구름이 형성돼서 위로 올라가는 모양이 신비에 가까우며, 쑥부쟁이를 비롯한 무룻과 용담, 물매화 등 천연색 꽃과 더불어 이 산굼부리에는 일 년 사시사철 관광객들에게 신비와 아름다움을 보여준다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/c44bb372-4717-4e89-ad89-2c5dba285168.webp'),
(100, '대정5일시장', '제주특별자치도 서귀포시 대정읍 하모리 1067-26 도', 33.2205095, 126.2489213, 'COMMERCIAL', 2, '제주도 서부 지역에서 가장 큰 오일시장', '제주도 서부 지역에서 가장 큰 오일시장', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/16/fa58b3b8-d622-44ea-bcc2-77528553d84c.webp');

INSERT INTO `POI` (`poi_id`, `poi_name`, `address`, `latitude`, `longitude`, `category_code`, `region_id`, `description`, `detail_description`, `image_url`) VALUES
(101, '제주올레여행자센터', '제주특별자치도 서귀포시 중정로 22', 33.2474052, 126.5586670, 'TRAIL', 3, '제주 여행자들의 베이스캠프', '제주 여행자들의 베이스캠프', 'https://api.cdn.visitjeju.net/photomng/imgpath/202401/17/c478d5d8-bf53-4591-8c23-768147a815da.webp'),
(102, '건강과성박물관', '제주특별자치도 서귀포시 안덕면 일주서로 1611', 33.2553313, 126.3452378, 'HISTORY', 2, '건강과 성 박물관은 서귀포시 안덕면 감산리에서 세계최대, 최초의 제1종 성 박물관으로 운영되고 있다.', '건강과 성 박물관은 서귀포시 안덕면 감산리에서 세계최대, 최초의 제1종 성 박물관으로 운영되고 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202301/09/82bcc672-47a9-4bc4-8292-6cafd7dd62d7.webp'),
(103, '제주민속촌', '제주특별자치도 서귀포시 표선면 민속해안로 631-34', 33.3205301, 126.8431877, 'HISTORY', 1, '제주에서 가장 제주다움을 볼 수 있는 곳, ‘제주민속촌’', '제주에서 가장 제주다움을 볼 수 있는 곳, ‘제주민속촌’', 'https://api.cdn.visitjeju.net/photomng/imgpath/202407/08/279e016a-35d4-4a6e-a432-799743d168df.webp'),
(104, '서바이벌체험관', '제주특별자치도 서귀포시 토평공단로 78-27', 33.2895399, 126.5889654, 'LEISURE', 3, '장비를 착용하고 팀별 게임을 즐길 수 있는 서바이벌 체험 공간입니다.', '장비를 착용하고 팀별 게임을 즐길 수 있는 서바이벌 체험 공간입니다. 활동적인 체험을 원하는 친구나 단체 방문객에게 잘 어울립니다. 게임을 통해 색다른 재미와 협동 활동을 경험할 수 있습니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/15/09312989-4825-478e-84e5-bdf9f10ee8bd.webp'),
(105, '점보빌리지', '제주특별자치도 서귀포시 안덕면 서광리 2351 원', 33.2764673, 126.3055237, 'CULTURE', 2, '제주속 작은 동남아 점보빌리지 코끼리테마쇼', '제주속 작은 동남아 점보빌리지 코끼리테마쇼', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/16/6d04e8eb-b47b-4e76-9d9d-56c290e678b2.webp'),
(106, '제주특별자치도 민속자연사박물관', '제주특별자치도 제주시 삼성로 40', 33.5055115, 126.5315677, 'HISTORY', 4, '제주민속자연사박물관은 제주 사람들이 오랜 세월 지켜온 전통문화와 자연 환경을 깊이 들여다보고 이해하는 공간이다.', '제주민속자연사박물관은 제주 사람들이 오랜 세월 지켜온 전통문화와 자연 환경을 깊이 들여다보고 이해하는 공간이다. 볼거리가 많고 내용이 알차서 관람 시간을 넉넉히 잡는 것이 좋다. 제주 신화의 발상지인 삼성혈과 이웃해 함께 둘러보면 편하다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/15/83f1fd6b-f86a-4136-a02e-75c9baca7d12.webp'),
(107, 'D&DEPARTMENTJEJUBYARARIO', '제주특별자치도 제주시 탑동로2길 3', 33.5177427, 126.5231658, 'COMMERCIAL', 4, '제주시 탑동 인근에 위치한 디자인·라이프스타일 중심의 상업·문화 공간입니다.', '제주시 탑동 인근에 위치한 디자인·라이프스타일 중심의 상업·문화 공간입니다. 제주 지역의 생활문화와 디자인 상품을 함께 접할 수 있는 곳입니다. 원도심과 탑동 일대를 둘러보며 쇼핑과 공간 관람을 함께 즐기기 좋습니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202311/21/f244b303-e0ab-4d06-8bc9-87fdb969cc9e.webp'),
(108, '중문골프클럽', '제주특별자치도 서귀포시 중문관광로72번길 60', 33.2454226, 126.4013982, 'LEISURE', 3, '중문관광단지에 위치한 중문골프클럽은 해안절벽을 따라 30여 만평 부지에 18홀 규모로 1981년에 조성되었다.', '중문관광단지에 위치한 중문골프클럽은 해안절벽을 따라 30여 만평 부지에 18홀 규모로 1981년에 조성되었다. 수려한 자연경관과 계곡을 낀 국내 유일의 해안코스를 따라 라운딩이 가능하며, 계절마다 다른 느낌의 코스로 즐길 수 있다. 또한, 양잔디로 시공하여 연중 푸르고 쾌적한 라운딩을 즐길 수 있다. 본래 회원제 골프장이지만, 국내외 관광객 이용기회를 확대하기 위하여 관광객 공유개념의 비회원제로 운영을 하고 있다. 철저한 사전예약제 운영으로 예약질서 확립 및 외국관광객 우선 예약을 실시하고 있다. 수려한 주변경관과 단지 내의 다양한 관광시설들을 이용할 수 있어 관광의 즐거움을 더해준다.', 'https://tong.visitkorea.or.kr/cms/resource/92/2607292_image2_1.bmp'),
(109, '오늘은녹차한잔', '제주특별자치도 서귀포시 표선면 중산간동로 4772', 33.3818497, 126.7910726, 'EXPERIENCE', 1, '제주 녹차를 주제로 차와 디저트를 즐길 수 있는 휴식 공간입니다.', '제주 녹차를 주제로 차와 디저트를 즐길 수 있는 휴식 공간입니다. 푸른 차밭과 자연 풍경을 감상하며 여유롭게 시간을 보내기 좋습니다. 제주 녹차의 향과 분위기를 함께 경험할 수 있는 곳입니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/0af223cf-769a-4b51-bc68-7a5eecc59c1b.webp'),
(110, '제주라프', '제주특별자치도 제주시 조천읍 선교로 115-1', 33.4867534, 126.7069211, 'EXPERIENCE', 1, '제주시 조천읍에 위치한 종합아트클러스터로서 짚와이어, 족욕, F&B, 예술작품, 빛축제 등 다양한 볼거리와 체험을 제공한다.', '제주시 조천읍에 위치한 종합아트클러스터로서 짚와이어, 족욕, F&B, 예술작품, 빛축제 등 다양한 볼거리와 체험을 제공한다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202109/24/da02d6fd-c002-4b03-b3a9-f194e7cc64fd.webp'),
(111, '와흘메밀농촌체험휴양마을', '제주특별자치도 제주시 조천읍 남조로 2455', 33.4827890, 126.6500808, 'EXPERIENCE', 1, '제주 한라산 북쪽 사면 밑에 자리 잡은 와흘리는 구그네오름, 세미오름 등 여러 오름에 둘러 쌓여있고, 넓은 초지가 있는 중산간 마을이다.', '제주 한라산 북쪽 사면 밑에 자리 잡은 와흘리는 구그네오름, 세미오름 등 여러 오름에 둘러 쌓여있고, 넓은 초지가 있는 중산간 마을이다. 산세모습이 마치 사람이 편안하게 누운 모습과 같다 하여 누울 ‘와’, 산 높을 ‘흘’이라 칭한 만큼 편안한 인심을 가진 사람들이 모여 하늘을 섬기던 전통을 잇고, 땅을 지키며, 이웃과 함께하는 아름다운 전형적인 농촌마을이다. 
매년 5월과 10월이면 하얀 메밀꽃이 만개해 사진 촬영 명소로 유명하다. 5월에는 축제가 열리며 다양한 체험행사도 진행한다. 
제주특별자치도 제주시 조천읍에 소재하고 있으며 제주공항에서 30분으로 제주시와 가까운 거리에 위치해 있다.', 'https://tong.visitkorea.or.kr/cms/resource/09/4074109_image2_1.jpg'),
(112, '관음사', '제주특별자치도 제주시 산록북로 660', 33.4237403, 126.5581237, 'NATURE', 4, '휴식, 명상을 통해 자기자신을 들여다보는 시간', '휴식, 명상을 통해 자기자신을 들여다보는 시간', 'https://api.cdn.visitjeju.net/photomng/imgpath/201908/29/3da5f721-c928-466d-ad52-00e4e844cfa5.webp'),
(113, '포레스트공룡사파리', '제주특별자치도 제주시 조천읍 선교로 474-1', 33.4631025, 126.7095874, 'CULTURE', 1, '생동감 있게 움직이는 공룡들과 스탬프 미션이 기다리고 있는 포레스트 공룡사파리는 제주 최대 사파리테마파크이다.', '생동감 있게 움직이는 공룡들과 스탬프 미션이 기다리고 있는 포레스트 공룡사파리는 제주 최대 사파리테마파크이다. 포토 존, 힐링 존, 체험 존, 페인팅 존, 실내 놀이시설 등 다양한 공간과 체험을 즐길 수 있으며, 어린이가 올라타도 되는 안전하고 편안한 동물 모형과 어른들이 쉴 수 있는 공간까지 가족 모두가 즐길 수 있는 테마파크이다. 공룡사파리 존은 마치 살아 숨 쉬는 듯한 공룡 친구들을 만날 수 있으며, 직접 동물을 만져보고 동물들에게 먹이도 주며 동물과 교감해 보는 동물 먹이 주기 체험 존과 어린이들만의 개성으로 동물을 페인팅해 보며 어린이의 창의성을 배가하는 페인팅 존, 비가 오나 눈이 오나 날씨와 상관없이 신나게 놀 수 있는 실내놀이터 존 등에서 어린이는 물론 어른들도 시간 가는 줄 모르는 흥미진진한 가족 여행지이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202304/05/05e647d8-e47e-4da1-a951-9a56227aaf56.webp'),
(114, '사라봉', '제주특별자치도 제주시 건입동 387-1임', 33.5171582, 126.5448000, 'NATURE', 4, '고운 비단을 뜻하는 사라봉은 제주에서 가장 아름다운 열 곳을 선정한 영주십경 중 사봉낙조에 해당하는 오름이다.', '고운 비단을 뜻하는 사라봉은 제주에서 가장 아름다운 열 곳을 선정한 영주십경 중 사봉낙조에 해당하는 오름이다. 사봉낙조는 사라봉에서 지는 붉은 노을을 의미하며, 사라봉 정상에 올라 노을로 붉게 물든 바다를 보면 절로 감탄사가 나온다. 정상에 오르면 북쪽으로는 파란 바다, 남쪽으로는 웅장한 한라산을 볼 수 있고 발 아래로 제주 시내의 모습이 보여 일몰 뿐 아니라 막힘없이 펼쳐진 평소의 풍경도 아름답다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/23/2151c0ac-0bf8-4d48-b92f-dc8dc18f47ef.webp'),
(115, '제주레포츠랜드', '제주특별자치도 제주시 조천읍 와흘상서2길 47', 33.4827616, 126.6386278, 'LEISURE', 1, '일반 카트장의 3배 크기, 국제경기유치가 가능한 국내최대규모카트장', '일반 카트장의 3배 크기, 국제경기유치가 가능한 국내최대규모카트장', 'https://api.cdn.visitjeju.net/photomng/imgpath/202506/30/e2da395b-cea0-49da-83e0-11a593ebc482.webp'),
(116, '휴애리자연생활공원', '제주특별자치도 서귀포시 남원읍 신례동로 256', 33.3094105, 126.6354098, 'THEME', 3, '자연 속 동·식물과 교감하며 계절별 꽃과 다양한 체험을 즐길 수 있는 자연생활공원', '자연 속 동·식물과 교감하며 계절별 꽃과 다양한 체험을 즐길 수 있는 자연생활공원', 'https://api.cdn.visitjeju.net/photomng/imgpath/202308/29/4c6ef2f3-3fa8-44fd-978b-de5559495d58.webp'),
(117, '테지움', '제주특별자치도 제주시 애월읍 평화로 2157-1', 33.4124994, 126.3933370, 'CULTURE', 2, '테디베어와 동물인형들을 직접만져보고,안아보고 함께 사진찍을수있는 체험형 오픈전시관', '테디베어와 동물인형들을 직접만져보고,안아보고 함께 사진찍을수있는 체험형 오픈전시관', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/24/ea35a3d0-8c0f-46b5-b193-c3ea5250967f.webp'),
(118, '법화사중화루', '제주특별자치도 서귀포시 하원북로35번길 15-38', 33.2647004, 126.4575098, 'HISTORY', 3, '법화사 경내 입구 쪽에 자리한 전통 누각 건물입니다.중화루 앞에는 아름다운 연꽃 연못인 ''구품연지''가 있어 경관이 뛰어납니다.법화사는 통일신라…', '법화사 경내 입구 쪽에 자리한 전통 누각 건물입니다.중화루 앞에는 아름다운 연꽃 연못인 ''구품연지''가 있어 경관이 뛰어납니다.법화사는 통일신라 시대 장보고가 창건한 것으로 전해지는 유서 깊은 사찰입니다.', 'https://mblogthumb-phinf.pstatic.net/MjAxNzA4MTlfNTEg/MDAxNTAzMTIwMTg3NDEy.G2YCNqcF_0pdx-Ho1O4fvriHIam7NzVAUkglUxrlioUg.067epbrtYOfKJpsdkzdloDtDzjhjE06AyTCRLrcvwA8g.JPEG.ontheroad_gh/_MG_7688.JPG?type=w420'),
(119, '제주해양동물박물관', '제주특별자치도 서귀포시 성산읍 서성일로 689-21', 33.4292468, 126.8552557, 'HISTORY', 1, '성산에 위치한 제주해양동물박물관', '성산에 위치한 제주해양동물박물관', 'https://api.cdn.visitjeju.net/photomng/imgpath/202207/06/7f0222de-09f9-4c43-8b7c-1bec1f1d31c0.webp'),
(120, '이중섭거리', '제주특별자치도 서귀포시 이중섭로 29', 33.2455503, 126.5643255, 'HISTORY', 3, '이중섭 거주지는 이중섭이 서귀포로 피난을 와서 정착한 곳이다.', '이중섭 거주지는 이중섭이 서귀포로 피난을 와서 정착한 곳이다. 천재 화가 이중섭과 그의 작품세계를 기리기 위해 그가 잠시 살다 간 서귀포 정방동 거주지를 당시 모습으로 복원, 정비하고 정방동 매일시장 입구부터 솔동산까지 360m를 이중섭 거리로 지정하여 그의 서귀포 체류 시절을 기념하고 있다. 1995년 11월 이중섭 거주지 기념 표석이 세워졌고, 이듬해 2월 말 그가 자주 거닐곤 했던 길가는 이중섭 거리로 그리고 그 이듬해인 1997년 4월 그가 기거했던 집과 부속 건물을 복원, 정리하여 이중섭 거주지와 그의 호 ''대향''을 따라서 대향 전시실로 꾸며 놓고 소개하게 되었다.
이로써 제주 서귀포시의 이중섭 거리는 한국 최초로 화가의 이름이 붙여진 거리가 되었으며, 더불어 매년 10월 말 그의 사망 주기에 맞추어 "이중섭 예술제"를 이곳에서 거행해 그의 예술혼을 기리는 행사를 하고 있다. 이중섭과 그의 가족 4명이 기거했던 방은 1.3평 정도의 아주 협소한 공간으로 명성에 비하여 얼마나 그의 인생이 초라했고 치열했는지 알 수 있다. 전시실은 8평 남짓한 공간에 그의 서귀포 생활이 담긴 작품을 중심으로 서귀포의 추억물고기 등의 그림이 전시되어 있으며, 특히 눈길을 끄는 것은 담배 은박지에 그린 은지화 작품으로 6·25전쟁 후 생활고로 인한 그림재료의 열악함을 짐작할 수 있는 부분이다. 이곳은 이중섭 가족의 추억이 담긴 장소이자 이중섭 화백의 숨결을 느낄 수 있는 소중한 공간이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/08/711eb171-3b4a-4840-8987-dade1247ca2a.webp'),
(121, '우도', '제주특별자치도 제주시 우도면 우도해안길 90', 33.4941146, 126.9504750, 'LEISURE', 1, '소가 누운 형상을 닮은 제주의 가장 큰 부속섬', '소가 누운 형상을 닮은 제주의 가장 큰 부속섬', 'https://api.cdn.visitjeju.net/photomng/imgpath/202408/21/edc894d2-02ca-4bc6-9d89-0681a696f58c.webp'),
(122, '김녕미로공원', '제주특별자치도 제주시 구좌읍 만장굴길 122', 33.5366309, 126.7726647, 'NATURE', 1, '제주도 제주시의 만장굴과 김녕사굴 사이에 유명한 관광지인 제주 김녕미로공원이 있다.', '제주도 제주시의 만장굴과 김녕사굴 사이에 유명한 관광지인 제주 김녕미로공원이 있다. 키 큰 나무 사이로 샛길이 만들어져 한번 들어가면 방향감각을 잃게 되어 어디로 나와야 할지 헷갈리게 하는 매력의 우리나라 최초 미로공원이다. 제주대학교에서 퇴직한 미국인 더스틴(F.H. Dustin) 교수가 세계적으로 유명한 영국의 미로 디자이너 에드린 피셔(Adrian Flsher Minotaur Maze Designs)와 함께 국제 전화, 국제 우편을 주고받으며 1983년부터 약 3년에 걸쳐 기본 디자인 작업을 마무리하였다. 그 후 1987년 처음으로 랠란디 나무를 산목 후 8년 동안 나무를 가꾸면서 1995년부터 운영을 시작했다. 
김녕미로공원의 수벽을 리우고 있는 나무는 랠란디나무는 사계절 푸른 상록수로서 향기는 사람의 정신을 맑게 해 주고 심리적 압박감을 완화시켜 주는 효과를 지니고 있다. 미로의 붉은빛이 감도는 바닥은 제주 천연 화산석이 송이이며 오염된 공기를 정화시키고 인체의 혈액 순환을 촉진시키는 효과를 지니고 있다. 
미로공원뿐만 아니라 다양한 포토존, 아이들과 놀 수 있는 놀이터, 미로공원에서 자라고 있는 고양이들에게 사료를 주는 등의 체험 프로그램을 진행하고 있어 가족 단위의 관광객들이 많이 방문한다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202409/09/3ecb92bb-b673-4d11-bd79-9e6c0564b975.webp'),
(123, '해미안', '제주특별자치도 제주시 일주서로 7353', 33.4938186, 126.4321388, 'EXPERIENCE', 4, '제주 바다와 자연 풍경을 가까이에서 즐기며 휴식을 취할 수 있는 공간입니다.', '제주 바다와 자연 풍경을 가까이에서 즐기며 휴식을 취할 수 있는 공간입니다. 한적한 분위기 속에서 제주다운 여유를 느끼기 좋습니다. 주변 관광 일정과 함께 가볍게 들러 쉬어가기 좋은 장소입니다.', 'https://img1.kakaocdn.net/thumb/R1280x0.fjpg/?fname=https://t1.kakaocdn.net/brunch/service/user/i2LY/image/FhEKM0TdNoLeX_bcrRD3pIoU7h0.jpg'),
(124, '제주안전체험관', '제주특별자치도 제주시 애월읍 평화로 1885', 33.3941443, 126.3734121, 'EXPERIENCE', 2, '각종 재난에 대처하는 능력을 겸비한 현직 소방관이 직접 안전교육을 하는 특별한 체험공간에서 스스로 행동하는 방법을 배우고 안전의 소중함에 대해…', '각종 재난에 대처하는 능력을 겸비한 현직 소방관이 직접 안전교육을 하는 특별한 체험공간에서 스스로 행동하는 방법을 배우고 안전의 소중함에 대해 생각할 수 있는 유익한 시간을 보낼 수 있습니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202406/27/3e5fe5a3-7344-4d34-a319-59ef5868d6ae.webp'),
(125, '서귀포향토오일시장', '제주특별자치도 서귀포시 천제연로188번길 12', 33.2507871, 126.4241625, 'COMMERCIAL', 3, '서귀포 관광 명소가 가득한 중문 관광단지 가운데 위치한 중문향토오일시장은 1950년대 피난민들과 함께 형성된 시장으로, 1965년 정식으로 장…', '서귀포 관광 명소가 가득한 중문 관광단지 가운데 위치한 중문향토오일시장은 1950년대 피난민들과 함께 형성된 시장으로, 1965년 정식으로 장을 열어 현재까지 이어지는 역사를 지닌 시장이다. 이곳에서는 손수 농사지은 농산물과 물가에 나가 잡은 수산물을 주로 판매하며 주로 제주도 현지인들이 장을 보는 오일장이다. 서귀포매일올레시장이나 제주민속오일시장에 비하면 큰 규모의 시장은 아니나, 볼거리와 살 거리가 다양하다. 도심의 시장과는 전혀 다른 분위기로 옛 시골 장터 분위기와 할머니들의 소박함과 정겨움을 느낄 수 있는 곳이다. 시장을 둘러보다 보면 상인들의 삶을 엿볼 수도 있고 활기찬 에너지를 얻을 수 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/2b12c0a6-aa6f-4197-951c-2dc02c810640.webp'),
(126, '거문오름', '제주특별자치도 제주시 한림읍 금악리 3445잡', 33.3262500, 126.2946139, 'NATURE', 2, '거문오름은 해발 456m(둘레 4,551m)의 오름으로 거문오름 용암동굴계를 형성한 모체로 알려져 있다.', '거문오름은 해발 456m(둘레 4,551m)의 오름으로 거문오름 용암동굴계를 형성한 모체로 알려져 있다. 숲이 우거져 검게 보여 검은 오름이라 하였다고 전해진다. 제주도의 오름 중 유일하게 유네스코 세계자연유산에 등재되었는데, 이는 거문오름에서 흘러나온 용암류가 경사를 따라 북동쪽 해안가까지 흘러가면서 지질학적 가치가 높은 화산 지형과 용암동굴을 만들어 냈기 때문이다. 제주도 자연유산지구 학술조사용역결과에 따르면 선흘리 거문오름 주변에 발달한 동굴의 규모는 용암동굴로서는 세계적인 수준인 것으로 확인되었다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202002/25/0dfb8693-2a32-4fb1-9b3e-41ab57964f01.webp'),
(127, '서림연대', '제주특별자치도 서귀포시 대정읍', 33.2365211, 126.2306855, 'NATURE', 2, '제주 해안 방어를 위해 설치된 옛 연대 시설로, 과거 외적의 침입과 해상 상황을 감시하던 장소입니다.', '제주 해안 방어를 위해 설치된 옛 연대 시설로, 과거 외적의 침입과 해상 상황을 감시하던 장소입니다. 제주 특유의 방어 유적과 역사적 흔적을 살펴볼 수 있습니다. 주변 해안 풍경과 함께 둘러보기 좋은 역사 유적입니다.', 'https://www.heritage.go.kr/unisearch/images/monument/thumb/1657856.jpg'),
(128, '신산공원', '제주특별자치도 제주시 건입동 1335-3 대', 33.5158154, 126.5287797, 'NATURE', 4, '제주시 중심지 한복판에 위치한 공원', '제주시 중심지 한복판에 위치한 공원', 'https://api.cdn.visitjeju.net/photomng/imgpath/201812/20/63e7d14d-3939-47d5-870f-535162cfe5f2.webp'),
(129, '제주아리랑혼', '제주특별자치도 서귀포시 표선면 번영로 2564-21', 33.4027143, 126.7786654, 'EXPERIENCE', 1, '2018 평창동계올림픽 공식 초청 작품으로 신명나는 제주아리랑과 환장적인 태권뮤지컬, 두드림, 한국무용을 감상할 수 있다.', '2018 평창동계올림픽 공식 초청 작품으로 신명나는 제주아리랑과 환장적인 태권뮤지컬, 두드림, 한국무용을 감상할 수 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202004/08/a542d1a6-dddb-4f09-a200-02fce2cd5d8d.webp'),
(130, '국립제주박물관어린이올레', '제주특별자치도 제주시 일주동로 17', 33.5137212, 126.5485887, 'HISTORY', 4, '동북아시아 문화교류의 거점인 제주도 역사와 문화의 전당', '동북아시아 문화교류의 거점인 제주도 역사와 문화의 전당', 'https://api.cdn.visitjeju.net/photomng/imgpath/201806/28/a9a2562a-6f36-4223-b185-9d250af3306a.webp'),
(131, '약천사', '제주특별자치도 서귀포시 이어도로 293-28', 33.2460534, 126.4493769, 'HISTORY', 3, '해안을 내려다볼 수 있는 동양 최대의 법당을 자랑하는 절', '해안을 내려다볼 수 있는 동양 최대의 법당을 자랑하는 절', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/11fc5ab2-808e-4197-92e7-fd560309e7f5.webp'),
(132, '세계조가비박물관', '제주특별자치도 서귀포시 태평로 284', 33.2474382, 126.5516158, 'HISTORY', 3, '서양화 화가 명연숙 관장이 41여 년간 세계 각국에서 수집한 8,800여 종 개체 수 억 만점 이상의 신비하고 아름다운 오방색 조가비와 산호…', '서양화 화가 명연숙 관장이 41여 년간 세계 각국에서 수집한 8,800여 종 개체 수 억 만점 이상의 신비하고 아름다운 오방색 조가비와 산호 그리고 동을 이용하여 세계 최초로 시도하는 새로운 형식의 세계조가비박물관이다. 바닷속 아름다운 조가비 세계를 예술 작가들이 연출하였는데, 부관장(권오균 금속조형작가)의 작품인 동을 소재로 하여 만든 받침대 위에 올려진 조가비와 산호의 아름다운 하모니는 관람객들의 발길을 멈추게 한다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202207/07/797d138f-1382-46eb-9b8c-4c5a33a84d28.webp'),
(133, '서귀다원', '제주특별자치도 서귀포시 516로 717', 33.3129068, 126.5966305, 'EXPERIENCE', 3, '서귀다원은 원래 감귤농원으로 운영되었으나, 2005년 차밭으로 새롭게 바꿔 운영되고 있다.', '서귀다원은 원래 감귤농원으로 운영되었으나, 2005년 차밭으로 새롭게 바꿔 운영되고 있다. 개인이 운영하고 있는 조용한 다원으로 한라산 해발 250m에서 제주 녹차를 재배하고 있으며, 다른 다원보다 비교적 사람이 적어 여유롭게 둘러볼 수 있다. 나무 가로수길, 잎이 무성한 동백나무, 현무암 조각, 차밭이 어우러져 있으며, 한라산과 녹차밭이 한눈에 보이는 절경을 한적하게 구경할 수 있다. 서귀다원은 매년 5월경 말차 수확을 위해 차광막을 덮어놓아 원활한 관람이 어려운 시기가 있으니, 방문 전 문의하는 것을 추천한다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/cfafbc7a-0461-4a4b-843c-740c944ded2b.webp'),
(134, '목장카페드르쿰다', '제주특별자치도 서귀포시 표선면 번영로 2454', 33.4094794, 126.7703113, 'EXPERIENCE', 1, '탁 트인 경치를 품은 목장카페 드르쿰다는 카트,승마, 먹이주기 체험,까지 즐길 거리가 많은 곳이다.', '탁 트인 경치를 품은 목장카페 드르쿰다는 카트,승마, 먹이주기 체험,까지 즐길 거리가 많은 곳이다. 번영로 대로변에 위치해 찾기 쉽고 편안한 카페와 체험장이 한 공간에 있어 이용하기 편하다. 카페 전망창 너머로는 푸른 들판이 펼쳐진다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202607/16/f9c87184-186e-44c9-819a-43f25a241cc6.jpg'),
(135, '토종흑염소목장', '제주특별자치도 서귀포시 남원읍 자배오름로 74-274', 33.3174809, 126.6596889, 'EXPERIENCE', 3, '제주에서 사육되는 흑염소와 목장 풍경을 가까이에서 볼 수 있는 곳입니다.', '제주에서 사육되는 흑염소와 목장 풍경을 가까이에서 볼 수 있는 곳입니다. 넓은 초지와 동물이 어우러진 농촌 분위기를 경험할 수 있습니다. 가족 방문이나 자연 체험에 어울리는 장소입니다.', 'https://res.klook.com/images/w_1200,h_630,c_fill,q_65/w_80,x_15,y_15,g_south_west,l_Klook_water_br_trans_yhcmh3/activities/v5qbccxecdjnqrpx6yuy/%5B%EC%A0%9C%EC%A3%BC%2F%EB%82%A8%EB%B6%80%5D%20%ED%8E%B8%EB%B0%B1%EC%88%B2%20%ED%86%A0%EC%A2%85%20%ED%9D%91%EC%97%BC%EC%86%8C%20%EB%AA%A9%EC%9E%A5.jpg'),
(136, '라온골프클럽&빌리지', '제주특별자치도 제주시 한경면 용금로 998', 33.3355900, 126.2873254, 'LEISURE', 2, '세계적인 골퍼 콜린 몽고메리가 설계했으며, Stone, Lake, Pine의 3가지 코스로 구성되어 있습니다.', '세계적인 골퍼 콜린 몽고메리가 설계했으며, Stone, Lake, Pine의 3가지 코스로 구성되어 있습니다. 천연 난대림 속에 위치하며 눈, 안개, 바람의 영향을 적게 받아 휴장일수가 적은 편입니다.', 'https://image.withstatic.com/330/169/174/92b597d2773b43eea30f305ae46b2ded.jpg?width=1280&height=1024&format=webp'),
(137, '혼인지마을', '제주특별자치도 서귀포시 성산읍 환해장성로 549', 33.4055164, 126.9038478, 'TRAIL', 1, '제주특별자치도 기념물 제 17호, 탐라의 시조인 삼신인(三神人)이 혼례를 올렸다는 장소 · 서귀포시 성산읍 온평리 · 제주특별자치도 기념물 제…', '제주특별자치도 기념물 제 17호, 탐라의 시조인 삼신인(三神人)이 혼례를 올렸다는 장소
· 서귀포시 성산읍 온평리
· 제주특별자치도 기념물 제17호
· 올레2코스', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/12/432b52d2-39d5-4c71-83a3-9fd3f56aaaa6.webp'),
(138, '한림 작은영화관', '제주특별자치도 제주시 한림읍 한림중앙로 71-9', 33.4087576, 126.2680786, 'CULTURE', 2, '제주시 한림읍에 위치한 지역 밀착형 소규모 영화관입니다.', '제주시 한림읍에 위치한 지역 밀착형 소규모 영화관입니다.
2개의 상영관을 갖추고 있으며 최신 영화와 다양한 기획 상영 프로그램을 운영하는 문화시설입니다.
대형 멀티플렉스가 아닌 지역 주민의 영화·문화 향유를 위해 조성된 공간입니다.', 'https://img.extmovie.com/files/attach/images/135/169/203/075/fb4431f5441c84704e02b3d54eb752a4.jpg'),
(139, '렛츠런파크제주', '제주특별자치도 제주시 애월읍 평화로 2144', 33.4053618, 126.3922604, 'FESTIVAL', 2, '렛츠런파크 제주는 천연기념물 제347호인 ‘제주마’의 보호 및 육성을 위해 1990년 개장된 테마공원이다.', '렛츠런파크 제주는 천연기념물 제347호인 ‘제주마’의 보호 및 육성을 위해 1990년 개장된 테마공원이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/19/b5d32881-a414-484d-a0df-265d40315e7c.webp'),
(140, '한림수협위판장', '제주특별자치도 제주시 한림읍 한림해안로 141-4', 33.4161044, 126.2615019, 'COMMERCIAL', 2, '제주시 한림항 인근에서 수산물이 유통되고 거래되는 수협 위판장입니다.', '제주시 한림항 인근에서 수산물이 유통되고 거래되는 수협 위판장입니다. 제주 서부 어업과 수산물 유통 현장을 가까이에서 볼 수 있는 공간입니다. 한림항과 주변 해안 지역을 둘러보며 지역의 어촌 분위기를 느끼기 좋습니다.', 'https://blog.kakaocdn.net/dna/crM3C2/btsGlf3Gizm/AAAAAAAAAAAAAAAAAAAAAJfyC0LGO1tKgzsh2TF3rj9IEWJyL0bnYnoOUmKbjsd2/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1790780399&allow_ip=&allow_referer=&signature=9n4W2t6yvdYZ4DTuhA6Dyb9u37Q%3D'),
(141, '노형수산시장', '제주특별자치도 제주시 한라대학로 7', 33.4803945, 126.4730749, 'COMMERCIAL', 4, '제주시 노형동에 위치한 수산물 중심의 시장입니다.', '제주시 노형동에 위치한 수산물 중심의 시장입니다. 다양한 생선과 해산물을 살펴보며 제주 지역의 수산 먹거리를 접할 수 있습니다. 시내에서 제주 수산물을 구입하거나 시장 분위기를 경험하기 좋은 장소입니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202306/28/5f173cf0-3c6d-4b7e-90cf-9f94f7893d60.webp'),
(142, '세리월드', '제주특별자치도 서귀포시 법환동 928 원', 33.2464395, 126.5121189, 'LEISURE', 3, '세리월드는 카트레이싱, 미로공원이 있어 체험과 관광을 두 가지 만족도를 동시에 제공하는 레저 테마파크이다.', '세리월드는 카트레이싱, 미로공원이 있어 체험과 관광을 두 가지 만족도를 동시에 제공하는 레저 테마파크이다. 서귀포 월드컵경기장 옆에 위치해 있다. 카트레이싱 체험이 대표 상품이다. 크기는 일반 범퍼카와 비슷하지만, 직접 운전하고 가속 페달을 밟아 빠른 속도로 주행한다는 점에서 범퍼카와 다르다. 안전 수칙에 따라 어린아이도 체험할 수 있다. 동백나무길 곳곳을 아기자기하게 꾸민 미로공원을 운영하고 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/b32d8cc2-d0ea-4271-a210-624d8dde3dd3.webp'),
(143, '노루생태관찰원', '제주특별자치도 제주시 명림로 520', 33.4448104, 126.6265555, 'NATURE', 4, '제주의 야생 노루를 언제든지 가까이서 만날 수 있는 곳', '제주의 야생 노루를 언제든지 가까이서 만날 수 있는 곳', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/18/2488302c-e919-42a9-85b2-cfd3ff40d228.webp'),
(144, '금오름', '제주특별자치도 제주시 한림읍 금악리 산 1-1임', 33.3545723, 126.3058389, 'NATURE', 2, '서부 중산간 지역의 대표적인 오름 중의 하나이다.', '서부 중산간 지역의 대표적인 오름 중의 하나이다. 산정부에 대형의 원형 분화구와 산정화구호(山頂火口湖)를 갖는 신기(新期)의 기생화산체이며, 남북으로 2개의 봉우리가 동서의 낮은 안부로 이어지며 원형의 분화구 (깊이 52m)를 이루고 있다. 분화구내의 산정화구호 (일명 今岳潭)는 예전에는 풍부한 수량을 갖고 있었으나 현재는 화구 바닥이 드러나 있다. ‘검, 감, 곰, 금’ 등은 어원상 신(神)이란 뜻인 ‘곰(고어)’과 상통하며, 동일한 뜻을 지닌 ‘곰’係語(계어)로서 고조선시대부터 쓰여 온 말이라고 한다. 즉 ‘금오름’은 神이란 뜻의 어원을 가진 호칭으로 해석되며, 옛날부터 신성시 되어 온 오름임을 알 수 있다. 해송, 삼나무, 찔레, 보리수, 윤노리나무 등 원형 분화구와 산정화구호이다. 
* 표고 427.5m, 비고 178m, 둘레 2,861m, 면적 613,966㎡, 저경 1,008m', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/17c48543-c1da-4033-b315-f8f7eae3c005.webp'),
(145, '김영갑갤러리두모악', '제주특별자치도 서귀포시 성산읍 삼달로 137', 33.3723705, 126.8542417, 'CULTURE', 1, '갤러리두모악에는 제주를 매우 사랑하여 두모악에 잠든 김영갑의 20여 년간의 작품들이 전시되어 있다.', '갤러리두모악에는 제주를 매우 사랑하여 두모악에 잠든 김영갑의 20여 년간의 작품들이 전시되어 있다. 제주를 사랑하고 모든 열정과 영혼을 담아 제주를 담고자 했던 김영갑의 생애가 담긴 곳이다. 
내부 전시관은 두모악관, 하날오름관이 있는데 지금은 사라진 제주의 옛 모습과 쉽게 드러나지 않는 속살을 전시된 사진을 통해 볼 수 있다. 용눈이 오름, 눈·비·안개 그리고 바람 환상곡, 구름이 내게 가져다준 행복, 지평선 너머의 꿈, 바람, 숲 속의 사랑, 오름, 마라도라는 작품 등이 있다. 
유품전시실에는 김영갑의 유품들이 전시되어 있는데 평소 그가 보던 책, 카메라 등이 전시되어 있고 영상실에서는 왕성한 활동을 하던 젊은 시절의 그와 루게릭병으로 투병하던 사진과 영상을 만나볼 수 있다. 또한 야외 정원과 무인 찻집은 미술관을 찾는 이들이 휴식과 명상의 공간으로 만들어져 있다. 갤러리 홍보와 지역민들에게 문화를 쉽게 접할 수 있도록 야외 공연장에서 음악회도 개최하고 있다. 두모악은 한라산의 옛 이름이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202110/29/0252afe0-942c-4598-bdb2-da9efc7e0620.webp'),
(146, '용담레포츠공원', '제주특별자치도 제주시 용담삼동 1089-3잡', 33.5188247, 126.4994290, 'LEISURE', 4, '편의시설과 체육시설이 잘 갖춰진 공원', '편의시설과 체육시설이 잘 갖춰진 공원', 'https://api.cdn.visitjeju.net/photomng/imgpath/202112/08/02cadb7a-e2d4-4698-9dea-4e9e7fe17154.webp'),
(147, '제주항공우주박물관', '제주특별자치도 서귀포시 안덕면 녹차분재로 218', 33.3042428, 126.2996871, 'HISTORY', 2, '제주항공우주박물관은 항공 기술과 우주를 꿈꾸는 사람들에게 무한한 상상력을 심어준다.', '제주항공우주박물관은 항공 기술과 우주를 꿈꾸는 사람들에게 무한한 상상력을 심어준다. 하늘을 날고자 했던 라이트 형제의 수많은 도전과 미래 행성을 세우는 일까지 마음껏 상상의 나래를 펼칠 수 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202008/28/fc8f02ff-55bd-4ab8-b038-a2b492c17143.webp'),
(148, '제주돌마을공원수석박물관', '제주특별자치도 제주시 한림읍 금능남로 421', 33.3538842, 126.2536013, 'NATURE', 2, '제주의 자연석으로 꾸며진 테마공원', '제주의 자연석으로 꾸며진 테마공원', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/39683aa8-90e3-400a-9d08-91b72706fad6.webp'),
(149, '브릭캠퍼스', '제주특별자치도 제주시 노형동 244-16 임', 33.4582146, 126.4860221, 'THEME', 4, '브릭 작품과 대형 조형물을 감상할 수 있는 실내 전시·체험 공간입니다.', '브릭 작품과 대형 조형물을 감상할 수 있는 실내 전시·체험 공간입니다. 다양한 테마의 창작 작품을 가까이에서 보고 사진 촬영도 즐길 수 있습니다. 아이부터 성인까지 함께 방문하기 좋은 문화 체험 장소입니다.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQUiv_VzChzvgT2FhpQ1tnhm9Xr6wfv4E6nao2_MpDnCg&s=10'),
(150, '서복공원', '제주특별자치도 서귀포시 서귀동 93-19 대', 33.2447484, 126.5702674, 'NATURE', 3, '서귀포 해안 일대의 역사와 자연 경관을 함께 즐길 수 있도록 조성된 공원입니다.', '서귀포 해안 일대의 역사와 자연 경관을 함께 즐길 수 있도록 조성된 공원입니다. 산책로와 휴식 공간을 따라 바다 풍경을 감상하기 좋습니다. 서귀포 도심 관광 중 가볍게 둘러보기 좋은 장소입니다.', 'https://cdn.jejuwapeople.com/news/photo/202206/1591_1514_82.jpg'),
(151, '창열사', '제주특별자치도 제주시 조천읍 신북로 303', 33.5410372, 126.6407100, 'HISTORY', 1, '제주 지역의 역사적 인물과 충절을 기리기 위해 마련된 사당입니다.', '제주 지역의 역사적 인물과 충절을 기리기 위해 마련된 사당입니다. 제주가 간직한 전통적인 제향 문화와 역사적 의미를 살펴볼 수 있습니다. 한적한 분위기에서 지역의 옛 이야기를 접하기 좋은 곳입니다.', 'https://mfis.mpva.go.kr/comm/fileDownload.do;mfis_jsessionid=DCepp_XiEhUTp3FCL4wIhKx9_kkjhOVnGnD3iHxT.mfisweb10?fileNo=8265&procGbn=mmrl'),
(152, '뱅듸승마클럽', '제주특별자치도 제주시 조천읍 번영로 1118-33', 33.4666262, 126.6535053, 'LEISURE', 1, '말을 타며 달리는 제주의 푸른 초원', '말을 타며 달리는 제주의 푸른 초원', 'https://api.cdn.visitjeju.net/photomng/imgpath/202306/18/49d1dcf9-8eb4-4c43-a3b0-d1ae152e19d3.webp'),
(153, '조천도서관', '제주특별자치도 제주시 조천읍 함덕리 919 대', 33.5377814, 126.6677670, 'CULTURE', 1, '조천읍도서관은 다양한 자료를 수집 및 제공함으로써 도민의 독서생활화에 기여하고 있는 공공도서관이다.', '조천읍도서관은 다양한 자료를 수집 및 제공함으로써 도민의 독서생활화에 기여하고 있는 공공도서관이다. 1999년에 개관하였으며, 현재는 제주시 문화관광체육국 산하 우당도서관에서 관리하고 있다. 다양한 계층별 독서문화 프로그램을 통해 도민들의 평생교육 실현에 앞장서고 있는 문화·소통의 복합공간을 위해 힘쓰고 있다. 지하 1층, 지상 2층 규모로 총 250석의 좌석을 갖춘 열람실과 서예실, 정보이용실, 다목적강당, 어린이자료실 등이 있다. 어린이자료실은 아이들이 자유롭게 앉고 기대거나 누워서 볼 수 있는 편안한 공간으로 마련되어 있다. 영유아를 위한 온돌방 형태의 공간도 갖추고 있어 부모와 자녀가 함께 책을 즐길 수 있다.', 'https://tong.visitkorea.or.kr/cms/resource/91/3553091_image2_1.jpg'),
(154, '별방진', '제주특별자치도 제주시 구좌읍 하도리 3354사', 33.5267692, 126.8828752, 'HISTORY', 1, '별방성은 1973년 4월 13일에 제주도 기념물로 지정되어 보호되고 있다.', '별방성은 1973년 4월 13일에 제주도 기념물로 지정되어 보호되고 있다. 별방성에 대해 ''신증동국여지승람'' 제주목 관방조에는 ‘별방성은 돌로 쌓았는데 둘레가 2,390자이고 높이는 7자이다. 중종 5년(1510)에 장림 목사가 이 땅이 우도(牛島)로 왜선이 가까이 댈 수 있는 곳이라 하여 성을 쌓고 김녕방호소를 이곳으로 옮기어 별방(別防)이라 이름하였다.’라고 하였고, 김상헌의 ''남사록''에는 ‘별방성은 동·서·남에 세문이 있고 성 안에는 우물이 있으나 맛이 짜다. 지명은 옛날에 하도의탄리라 하였다.’라고 하였으며 ‘탐라지''에는 ‘북성에 대변청이 있고 중앙에는 객사(客舍), 별창(別倉), 군기고(軍器庫)가 있다.’라고 하였다. 박천형의 서계(書啓) 내용에는 ‘동쪽과 북쪽이 바다에 임하였고 성 안은 화북이나 조천에 비해 조금 넓으며 동·서·남에 세문과 성안에 두 우물이 있으나 포구의 공간이 몹시 좁고 뾰족 나온 돌모서리가 창 같이 날카로워 배를 정박할 수가 없다. 횃불을 비치해 경보하는 것이 좋을 듯하며 성을 설치하여 방어하는 데에는 적합한 곳이 아닌 듯하다.’라고 하였다. 헌종 14년(1848)에 장인식 목사가 이를 중수하였다.

◎ 한류의 매력을 만나는 여행 정보 - 
조선시대의 성곽에 ‘부’씨로 구성된 밴드와 함께 부승관이 올랐다. 제주를 개국했다는 고 씨, 양 씨, 부 씨 세 성씨 중 하나인 부 씨이다. 별방진이 위치한 제주도 구좌읍 하도리는 부 씨의 집성촌이다. 승관의 고향 제주에서도 의미 있는 지역이다. 별방진은 유채꽃 명소로, 이른 봄 노란 유채꽃과 어우러지는 검은 돌의 성곽이 매력적이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/9e1691e1-2199-4b38-86f1-9b141a532f68.webp'),
(155, '제주오름승마랜드', '제주특별자치도 제주시 조천읍 선흘리 454-3 목', 33.4487247, 126.7131982, 'LEISURE', 1, '영화 속 한 장면처럼, 말을 타고 숲을 거니는 ‘제주오름승마랜드’', '영화 속 한 장면처럼, 말을 타고 숲을 거니는 ‘제주오름승마랜드’', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/83e804d2-81dd-4c63-80f5-d42ba506d826.webp'),
(156, '그리스신화박물관', '제주특별자치도 제주시 한림읍 광산로 942', 33.3486929, 126.3566388, 'HISTORY', 2, '그리스신화박물관은 아름다운 섬 제주도에서 그리스 신화와 관련된 명화와 대리석을 눈으로 보고 손으로 만져볼 수 있는 체험형 박물관이다.', '그리스신화박물관은 아름다운 섬 제주도에서 그리스 신화와 관련된 명화와 대리석을 눈으로 보고 손으로 만져볼 수 있는 체험형 박물관이다. 박물관은 루브르와 바티칸 박물관의 명화와 대리석 조각상 재현 작품을 전시한 공간과 관람객 모두 그리스인으로 변신하는 그리스 마을로 구성되어 있다. 창조관, 올림포스관, 신탁관, 영웅관, 휴먼관, 사랑관, 그리스 마을에서 기존 유물 중심의 수동적인 관람 방식에서 벗어나 전시물과 관람객이 교감할 수 있도록 다양한 체험형 전시를 제공한다. 대표 체험으로는 그리스의상 체험, 아테네 시민권 발급 체험, 올림포스 12신 가면 만들기 체험 등이 있다.', 'https://tong.visitkorea.or.kr/cms/resource/71/3053171_image2_1.jpg'),
(157, '아프리카박물관', '제주특별자치도 서귀포시 이어도로 49', 33.2395471, 126.4294034, 'HISTORY', 3, '아프리카 박물관은 1998년 11월 서울 대학로에 아프리카란 우리에겐 다소 생소한 문화를 토대로 한 박물관을 개관하였으며, 2004년 12월…', '아프리카 박물관은 1998년 11월 서울 대학로에 아프리카란 우리에겐 다소 생소한 문화를 토대로 한 박물관을 개관하였으며, 2004년 12월 새로운 문화적 도약을 위해 제주도 서귀포시 중문관광단지 국제컨벤션센터 동쪽에 박물관 건물을 신축하고 이전하였다. 서귀포시 중문관광단지에 새롭게 선보인 아프리카 박물관의 건물은 서아프리카 말리의 젠네에 위치하고 있는 이슬람 대사원을 토대로 설계하였다. 젠네 대사원은 흙으로 지어진 건물 중 세계 최대 규모이며, 국제 문화 협력 교류기관인 유네스코는 전 인류가 함께 보존해야 할 세계문화유산으로 지정하고 있다. 신축된 아프리카 박물관은 아프리카 대륙 문화의 정통성을 훼손하지 않고 보다 다양한 시각으로 소개하고자 하는 본 박물관의 의지를 표방하고 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202205/30/f3c1978d-eaf6-4d6e-a5d8-81f7889caaee.webp'),
(158, '제주아트서커스', '제주특별자치도 서귀포시 안덕면 동광로 214', 33.3143826, 126.3448196, 'CULTURE', 2, '국내 최초로 선보이는 7인 여전사 오토바이쇼', '국내 최초로 선보이는 7인 여전사 오토바이쇼', 'https://api.cdn.visitjeju.net/photomng/imgpath/202112/02/0bf4675c-1d69-41a3-9594-dd6c5fe70a5a.webp'),
(159, '비양도망대', '제주특별자치도 제주시 우도면 안비양길 51', 33.5144182, 126.9723466, 'NATURE', 1, '우도 섬 속에 또 하나의 섬, 비양도', '우도 섬 속에 또 하나의 섬, 비양도', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/02/1b8d9a22-d8bf-44bc-9769-10836f5049af.webp'),
(160, '성이시돌센터', '제주특별자치도 제주시 한림읍 금악북로 353', 33.3466451, 126.3226204, 'HISTORY', 2, '아름다운 풍경이 있는 목장', '아름다운 풍경이 있는 목장', 'https://api.cdn.visitjeju.net/photomng/imgpath/202110/28/f2223296-ce4a-4352-86fe-8e2b85f5edd3.webp'),
(161, '하멜상선전시관', '제주특별자치도 서귀포시 안덕면 사계남로216번길 24-30', 33.2333951, 126.3136868, 'CULTURE', 2, '하멜 일행이 타고 제주에 표착했던 네덜란드 상선 스페르웨르호를 재현한 전시시설입니다.', '하멜 일행이 타고 제주에 표착했던 네덜란드 상선 스페르웨르호를 재현한 전시시설입니다.
하멜의 제주 표착과 조선 생활, 하멜표류기와 관련된 역사를 살펴볼 수 있는 장소입니다.
용머리해안·하멜기념비 등 주변 관광지와 함께 제주와 네덜란드의 역사적 인연을 살펴보기 좋은 곳입니다.', 'https://img.tf.co.kr/article/home/2023/06/21/202347211687313117.jpg'),
(162, '선녀와나무꾼 테마공원', '제주특별자치도 제주시 조천읍 선교로 267', 33.4786386, 126.7032128, 'THEME', 1, '어릴 적 향수를 부르는 선녀와나무꾼 테마공원', '어릴 적 향수를 부르는 선녀와나무꾼 테마공원', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/01/3fee6f3b-395a-411e-bdbf-d4a2de8bfdb8.webp'),
(163, '제주커피박물관Baum', '제주특별자치도 서귀포시 성산읍 서성일로1168번길 89-17', 33.4398657, 126.8991545, 'HISTORY', 1, '나무, 숲과 함께 다채로운 커피의 향을 즐길 수 있는 커피박물관', '나무, 숲과 함께 다채로운 커피의 향을 즐길 수 있는 커피박물관', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/e821998c-9e36-478a-b724-b612aa85c605.webp'),
(164, '(주)제주유리의성', '제주특별자치도 제주시 한경면 녹차분재로 462', 33.3146339, 126.2736624, 'THEME', 2, '유리 공예와 조형 작품을 테마로 꾸며진 제주 대표 체험형 관광지입니다.', '유리 공예와 조형 작품을 테마로 꾸며진 제주 대표 체험형 관광지입니다. 다양한 유리 작품과 정원을 둘러보며 색다른 분위기를 즐길 수 있습니다. 전시 관람과 사진 촬영, 공예 체험을 함께 하기 좋은 곳입니다.', 'https://lh3.googleusercontent.com/grass-cs/AABkmLcJywAipnekY0oYao4bqogluzuGCCN5aRQGyBYjb-DVhoHRRoebGjCj3MrAnVfJ6qOfwAtP9sy4rsIjj-RrK9WdyEawnqEFVlRU26_TiTYLf9WjM2vkj80lMM6v3ZB4tj6wSofc=w270-h312-n-k-no'),
(165, '혼인지', '제주특별자치도 서귀포시 성산읍 혼인지로 39-46', 33.4151952, 126.8937741, 'HISTORY', 1, '제주특별자치도 기념물 제 17호, 탐라의 시조인 삼신인(三神人)이 혼례를 올렸다는 장소 · 서귀포시 성산읍 온평리 · 제주특별자치도 기념물 제…', '제주특별자치도 기념물 제 17호, 탐라의 시조인 삼신인(三神人)이 혼례를 올렸다는 장소
· 서귀포시 성산읍 온평리
· 제주특별자치도 기념물 제17호
· 올레2코스', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/12/432b52d2-39d5-4c71-83a3-9fd3f56aaaa6.webp'),
(166, '액트몬제주푸드박스', '제주특별자치도 서귀포시 중문관광로 205', 33.2438864, 126.4216624, 'EXPERIENCE', 3, '제주 중문에서 비 오는 날에도 즐길 수 있는 실내 액티비티를 찾고 있다면, 액트몬 제주중문점!', '제주 중문에서 비 오는 날에도 즐길 수 있는 실내 액티비티를 찾고 있다면, 액트몬 제주중문점!
제주 중문관광단지에 위치한 약 1,000평 규모의 실내 액티비티 공간으로, 아이부터 어른까지 날씨에 상관없이 다양한 게임과 체험을 즐길 수 있습니다.
액트몬 제주중문점에서는 각기 다른 재미를 가진 4개의 콘텐츠를 만나볼 수 있습니다.

1. 아이존팝
다양한 아케이드 게임을 시간제로 자유롭게 즐기는 대형 실내 오락실

2. 레이저 미션
200평 규모의 레이저 서바이벌 경기장에서 친구, 가족들과 함께 즐기는 레이저 서바이벌 배틀 게임

3. 액트몬스터 보물찾기
30개의 보물존을 탐험하며 숨겨진 은화를 찾아가는 방탈출형 해적 보물찾기 입니다. 미션을 수행하며 은화를 모으고, 찾은 은화는 가챠 상품으로 교환할 수 있습니다.

4. 포즐파크
직접 꾸민 나만의 냥냥이와 함께 여권을 들고 스티커 미션존, 셀프 포토존, 런웨이존 등 냥냥별 여행을 떠나는 테마형 체험공간

전 구역이 실내라 비가 오거나 더운 날에도 이용할 수 있으며, 평균 체류시간은 1~2시간입니다. 예약 없이 당일 입장이 가능하며 무료주차도 가능합니다.
제주 중문에서 아이와 갈 곳, 비 오는 날 실내 놀거리, 가족이 함께 즐길 수 있는 제주 오락실을 찾는다면 액트몬 제주중문점에서 만나보세요.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202609/11/85181d4f-912c-412d-b64e-c6f1dddfbcd0.jpg'),
(167, '갯갓다리', '제주특별자치도 서귀포시 예래동', 33.2411675, 126.3967469, 'NATURE', 3, '제주의 하천과 주변 마을 풍경을 잇는 다리로, 인근 자연을 감상하며 걷기 좋은 장소입니다.', '제주의 하천과 주변 마을 풍경을 잇는 다리로, 인근 자연을 감상하며 걷기 좋은 장소입니다. 비교적 한적한 분위기 속에서 제주 지역의 일상적인 풍경을 느낄 수 있습니다. 주변 산책 코스와 함께 둘러보기 좋습니다.', 'https://mblogthumb-phinf.pstatic.net/MjAyNDA0MDZfMTMx/MDAxNzEyNDE0OTM5MzU1.t6DUoh0Of72SCjExSLl-UIZypjBIZi7R0l9gO4_3TBcg.8DLBU6dEG3j_yQPvN5t6s85FhOrNMtqsIN1UVlUAMXsg.JPEG/1712413829151.jpg?type=w800'),
(168, '소정방폭포', '제주특별자치도 서귀포시 동홍동 233-2답', 33.2452717, 126.5775327, 'TRAIL', 3, '소정방폭포는 제주도 서귀포시 제주올레 6코스에 있는 폭포이다.', '소정방폭포는 제주도 서귀포시 제주올레 6코스에 있는 폭포이다. 소정방이라는 말은 정방폭포 옆의 작은 폭포라는 의미로 정방 폭포의 동쪽 570m 지점에 있다. 대한민국 폭포 중 정방폭포와 같은 해안 폭포로 육지에서 곧바로 바다로 연결되어 낙수가 떨어진다. 폭포의 높이가 낮고 물이 워낙 차가워 주변 주민들의 물맞이 장소로 인기가 있다. 
제주에는 백중날(음력 7월 15일) 차가운 물을 맞으면 일 년 동안 무사 건강하다는 풍속이 있어 백중날 물맞이 장소로도 사랑받는다. 아담한 물줄기가 친근한 느낌을 주며 이곳에서 보는 서귀포 앞 바다의 야경은 가히 일품이다. 소라의성과 소정방굴이 이웃해 있으며, 주변에 있는 정방폭포와 함께 관광하길 추천한다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/fec4430a-317a-4cb4-bd20-9fba73026012.webp'),
(169, '액티브파크', '제주특별자치도 제주시 한림읍 금능남로 76', 33.3811424, 126.2360785, 'LEISURE', 2, '액티브파크 제주는 남녀노소 누구나 신나는 체험을 통해 최고의 성취감을 느낄 수 있는 복합체험공간이다.', '액티브파크 제주는 남녀노소 누구나 신나는 체험을 통해 최고의 성취감을 느낄 수 있는 복합체험공간이다. 이곳은 아이부터 어른까지 모두가 즐길 수 있는 다양한 액티비티가 마련되어 있다. 대표적인 시설 중 하나인 클립 앤 클라임은 독특한 디자인과 안전한 시스템을 갖춘 실내 클라이밍 놀이로 도전과 재미를 동시에 느낄 수 있어 남녀노소 인기가 많은 체험이다. 친환경 카트 트랙 위에서 스피디 하고 바람을 가르는 짜릿한 질주 체험을 느낄 수 있는 엑티브 파크의 카트 체험은 일상의 스트레스를 시원하게 날려버릴 수 있다. 여기에 호기심 많고 에너지가 넘치는 어린이들을 위한 키즈 카페도 마련되어 있는데, 이곳은 마치 마법 같은 공간으로 아이들에게 창의력과 상상력을 자극하고 다양한 놀이를 통해 배움의 즐거움을 느끼게 해준다.', 'https://tong.visitkorea.or.kr/cms/resource/40/4095340_image2_1.jpg'),
(170, '위미항활어회센터', '제주특별자치도 서귀포시 남원읍 위미중앙로196번길 6-37', 33.2703764, 126.6641044, 'COMMERCIAL', 3, '위미항은 국가 어항으로 풍부한 수산자원을 보유한 연근해 어업의 근거지다.', '위미항은 국가 어항으로 풍부한 수산자원을 보유한 연근해 어업의 근거지다. 제주에서 가장 포근하고 따뜻한 곳으로 봄에는 제주도에서 가장 먼저 벚꽃이 개화하는 곳이며 석양이 아름답기로도 유명하다. 위미항은 바닥이 훤히 보일 정도로 맑고 깨끗한 것이 특징이다. 바다 멀리 편평하게 다듬어 놓은 듯한 지귀도가 보인다. 제주 올레 5코스에 속해 있는 이곳은 걷기에도 좋고, 주변에 동백나무 군락지가 있어 구석구석 아름다운 풍경을 감상할 수 있다. 체험학습과 낚시를 즐길 수 있는 관광용 어장이 있어 여름철에 가족 단위의 관광객들이 많이 찾는다. 또한 동방파제에 있는 수협 활어 어판장에서 싱싱한 회를 바로 손질해 먹을 수 있어 식도락 여행지로도 손색이 없다.', 'https://tong.visitkorea.or.kr/cms/resource/57/3390157_image2_1.jpg'),
(171, '아끈다랑쉬오름', '제주특별자치도 제주시 구좌읍 세화리 산 6임', 33.4776861, 126.8215361, 'TRAIL', 1, '제주 동부의 대표적인 오름 가운데 하나로, 정상부의 깊고 뚜렷한 분화구와 주변 오름·들판을 조망할 수 있는 곳이다.', '제주 동부의 대표적인 오름 가운데 하나로, 정상부의 깊고 뚜렷한 분화구와 주변 오름·들판을 조망할 수 있는 곳이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/21ead729-dd07-42e8-be6b-e272828c7317.webp'),
(172, '초콜릿랜드', '제주특별자치도 서귀포시 중문관광로110번길 15', 33.2494004, 126.4134525, 'EXPERIENCE', 3, '중문관광단지에 있는 제주 초콜릿랜드는 초콜릿을 테마로 다양한 재미를 선보인다.', '중문관광단지에 있는 제주 초콜릿랜드는 초콜릿을 테마로 다양한 재미를 선보인다. 전 세계 다양한 형태의 초콜릿 작품들과 세계 최초 초콜릿 그림, 각국을 구분하여 전시해 놓은 세계 초콜릿 전시장, 어린이를 위한 포토존, 초콜릿 만들기 체험장, 전망대가 있다. 초콜릿 만들기 체험은 재료와 도구가 준비되어 있어 손쉽게 만들며 맛과 재미를 느낄 수 있다. 직접 만든 초콜릿을 포장해 소중한 사람에게 선물하기도 좋다. 이 밖에 마카롱 만들기, 초코크러스트 피자 만들기 체험 등이 있다. 연인과 가족, 아이들과 함께 달콤한 시간을 만들고 싶은 사람들이 즐겨 찾는 곳이다. 중문관광단지 내의 다른 전시관들과 같이 둘러보기 좋다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202112/15/af22cee2-e14d-42a5-9b55-2fb06507b6e1.webp'),
(173, '엠브리지1971', '제주특별자치도 서귀포시 대정읍 최남단해안로 128', 33.2101121, 126.2571274, 'CULTURE', 2, '서귀포시 대정읍의 해안 풍경을 즐길 수 있는 카페·휴식공간입니다.', '서귀포시 대정읍의 해안 풍경을 즐길 수 있는 카페·휴식공간입니다.
인근 해양레저 체험과 함께 제주 남서부 바다를 바라보며 머무를 수 있는 공간입니다.
일반적인 자연관광지보다는 카페와 해양레저가 결합된 상업·체험 관광지 성격이 강한 곳입니다.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSkWh2WSLBl66dvxerHsk2F6yOJz528BT0sNF2tdcgv3Q&s=10'),
(174, '테디베어뮤지엄 제주점', '제주특별자치도 서귀포시 중문관광로110번길 31', 33.2504156, 126.4122790, 'CULTURE', 3, '다양한 테마와 재미있는 볼거리가 가득한 국내 유일의 테디베어 박물관, 중문관광단지 중심에 있음', '다양한 테마와 재미있는 볼거리가 가득한 국내 유일의 테디베어 박물관, 중문관광단지 중심에 있음', 'https://api.cdn.visitjeju.net/photomng/imgpath/202409/09/8c18f0f6-56e4-4388-9cb3-c3e0a9e34595.webp'),
(175, '송당승마장', '제주특별자치도 제주시 구좌읍 번영로 2015', 33.4360325, 126.7393536, 'LEISURE', 1, '구좌의 들판을 달려보자', '구좌의 들판을 달려보자', 'https://api.cdn.visitjeju.net/photomng/imgpath/201908/22/ec81b062-d5b0-4ebd-b3cf-ca1663606a47.webp'),
(176, '함덕돌핀레져', '제주특별자치도 제주시 조천읍 함덕리 1008', 33.5440111, 126.6682792, 'LEISURE', 1, '함덕해수욕장 인근에서 운영되는 해양레저 체험시설입니다.', '함덕해수욕장 인근에서 운영되는 해양레저 체험시설입니다.
제트스키 등 제주 바다에서 즐기는 수상레저 활동을 중심으로 하는 장소입니다.
경관을 관람하는 관광지보다는 직접 바다에서 활동하는 체험·스포츠형 관광시설입니다.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRn4NtL9zs9MOiZQQx6IguneM_YqZeGaaVsN3ThRFZOQA&s=10'),
(177, '연동연대(도지정기념물제23-10호)', '제주특별자치도 서귀포시 서호동 73임', 33.2419739, 126.5242333, 'NATURE', 3, '서귀포시 서호동에 남아 있는 조선시대 통신·방어 시설인 연대입니다.', '서귀포시 서호동에 남아 있는 조선시대 통신·방어 시설인 연대입니다.
해안의 상황을 감시하고 불이나 연기를 이용해 주변 연대와 정보를 전달하던 군사시설입니다.
제주 해안방어체계의 역사적 흔적을 살펴볼 수 있는 지정문화유산입니다.', 'https://www.heritage.go.kr/unisearch/images/monument/thumb/1657820.jpg'),
(178, '물의도시베니스랜드', '제주특별자치도 서귀포시 성산읍 서성일로 474', 33.4153900, 126.8406939, 'NATURE', 1, '제주에서 만나는 아름다운 수상도시 베니스 여행~', '제주에서 만나는 아름다운 수상도시 베니스 여행~', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/16/11d585f4-e20b-4e78-8ccb-fb28450ab38c.webp'),
(179, '해변산책', '제주특별자치도 제주시 애월읍 곽지9길 7', 33.4520466, 126.3080135, 'TRAIL', 2, '제주의 바다를 가까이에서 느끼며 천천히 걸을 수 있는 해안 산책 공간입니다.', '제주의 바다를 가까이에서 느끼며 천천히 걸을 수 있는 해안 산책 공간입니다. 파도 소리와 탁 트인 바다 풍경을 감상하며 휴식을 취하기 좋습니다. 일몰이나 아침 풍경을 즐기며 가볍게 걷기 좋은 장소입니다.', 'https://www.jejunews.com/news/photo/202010/2173460_194853_5321.jpg'),
(180, '가시리문화센터', '제주특별자치도 서귀포시 표선면 가시로565번길 20', 33.3535717, 126.7707759, 'CULTURE', 1, '서귀포시 표선면 가시리 주민들의 문화·커뮤니티 활동을 위한 마을문화시설입니다.', '서귀포시 표선면 가시리 주민들의 문화·커뮤니티 활동을 위한 마을문화시설입니다.
주민 행사와 회의, 지역 프로그램 등이 이루어지는 가시리의 생활문화 거점 공간입니다.
일반적인 관광 명소라기보다는 지역 주민을 위한 마을 공공시설 성격이 강한 장소입니다.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQXzc2EE5n-GvuWTLm9pBQsKjvdEtQJT5Ucs1hcJUw405xzarjb5XyVrx7C&s=10'),
(181, '단산사', '제주특별자치도 서귀포시 대정읍 향교로 119', 33.2397498, 126.2849450, 'HISTORY', 2, '거대한 박쥐가 날개를 펴고 있는 듯한 곳', '거대한 박쥐가 날개를 펴고 있는 듯한 곳', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/7df96177-a4e0-4bfa-96e3-2283ae56fa94.webp'),
(182, '제주남문교회', '제주특별자치도 제주시 광양13길 6-3', 33.4986403, 126.5314660, 'HISTORY', 4, '제주 지역에 자리한 기독교 교회로 지역 주민들의 예배와 신앙 공동체 활동이 이루어지는 공간입니다.', '제주 지역에 자리한 기독교 교회로 지역 주민들의 예배와 신앙 공동체 활동이 이루어지는 공간입니다. 제주 지역 기독교 문화의 한 모습을 볼 수 있습니다. 주변 지역과 함께 둘러볼 수 있는 종교 시설입니다.', 'https://img1.kakaocdn.net/thumb/R1280x0.fjpg/?fname=https://t1.daumcdn.net/brunch/service/user/cxIi/image/tFGW5UzEGNsnpKxC99bBC1foUkw.jpg'),
(183, '수월봉전망대', '제주특별자치도 제주시 한경면 고산리 3760임', 33.2947695, 126.1631083, 'NATURE', 2, '제주의 가장 서쪽 끝머리에 있는 한경면 고산리에 가면 제주에서 가장 넓은 들이 있다.', '제주의 가장 서쪽 끝머리에 있는 한경면 고산리에 가면 제주에서 가장 넓은 들이 있다. 이 들판 끝 해안가에 솟아있는 조그마한 봉우리가 수월봉이다. 수월봉은 해안에 돌출해 있는 높이 약 77m의 봉우리로 절벽이 예리하고 운치가 있으며 곳곳에서 솟는 용천수는 약수로 유명하다. 수월봉 정상에는 기우제를 지내던 육각정인 수월정이 있다. 수월봉 아래 해안을 끼고 이어지는 절벽은 화석층이 뚜렷하여 자연의 신기함을 더하는 곳이다. 수월봉에서는 제주에서 가장 아름답다는 섬인 차귀도가 내려다 보이고, 더욱이 수월봉 정상에 있는 수월정에 앉아서 바라보는 낙조는 제주 어느 곳에서 보는 것보다 아름답다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201907/30/2436b568-5046-4df2-a4cf-0b28b6ee29ff.webp'),
(184, '무오법정사항일운동발상지(제주도기념물제61-1호)', '제주특별자치도 서귀포시 도순동 산 1임', 33.3124429, 126.4738017, 'TRAIL', 3, '법정사항일운동의 발상지로 알려져있는 역사적 장소', '법정사항일운동의 발상지로 알려져있는 역사적 장소', 'https://api.cdn.visitjeju.net/photomng/imgpath/201810/19/eacc0e18-9724-4b8c-a3bb-854828376080.webp'),
(185, '송악산둘레길', '제주특별자치도 서귀포시 대정읍 상모리 산 2 임', 33.1990834, 126.2897917, 'NATURE', 2, '서남부의 절경을 선사하는 산방산의 이웃산', '서남부의 절경을 선사하는 산방산의 이웃산', 'https://api.cdn.visitjeju.net/photomng/imgpath/202008/21/a8ee7cef-10ef-42a1-b1f7-d5730021f0dc.webp'),
(186, '서귀포칠십리시공원', '제주특별자치도 서귀포시 서홍동 659-2대', 33.2447129, 126.5567628, 'NATURE', 3, '외돌개와 해안올레길을 연결하는 공원', '외돌개와 해안올레길을 연결하는 공원', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/a5f0edec-ff91-4ee4-8dcf-f2ca24f76dfc.webp'),
(187, '김만덕객주', '제주특별자치도 제주시 임항로 68', 33.5164850, 126.5322531, 'HISTORY', 4, '제주 구도심에 있는 미니 민속촌', '제주 구도심에 있는 미니 민속촌', 'https://api.cdn.visitjeju.net/photomng/imgpath/202112/06/8ab726aa-2425-4724-9ca2-9803524ff927.webp'),
(188, '어승생승마장', '제주특별자치도 제주시 1100로 2659', 33.4256144, 126.4900201, 'EXPERIENCE', 4, '어승생 승마장은 제주시에 위치해 있고 승마와 목장체험을 동시에 즐길 수 있는 복합레저단지이다.', '어승생 승마장은 제주시에 위치해 있고 승마와 목장체험을 동시에 즐길 수 있는 복합레저단지이다. 미국 서부를 테마로 한 공간이며 10만평 규모의 넓은 초지가 있어, 말을 타고 초원을 달릴 수 있다. 외승을 나가지 않더라도 구보로 400m 이상을 쉬지 않고 전력질주를 할 수 있다. 또한 말에 처음 오르는 초보자도 교관의 도움을 받아 평보부터 속보, 경속보, 구보까지 원스텝으로 경험할 수 있는 프로그램이 있다. 날씨가 좋은 날에는 에메랄드빛 제주바다를 볼 수 있고 웅장한 한라산까지 조망이 가능하다.', 'https://tong.visitkorea.or.kr/cms/resource/86/4073686_image2_1.jpg'),
(189, '무민랜드제주', '제주특별자치도 서귀포시 안덕면 병악로 420', 33.3067993, 126.3815342, 'THEME', 2, '무민 캐릭터와 이야기를 테마로 조성된 전시·체험 공간입니다.', '무민 캐릭터와 이야기를 테마로 조성된 전시·체험 공간입니다. 캐릭터 전시와 포토존을 통해 동화 같은 분위기를 즐길 수 있습니다. 가족이나 연인과 함께 가볍게 방문하기 좋은 실내 관광지입니다.', 'https://image.kkday.com/v2/image/get/c_fill%2Cq_55%2Ct_webp%2Cw_960/s1.kkday.com/product_104093/20220928082840_Qeymp/jpg'),
(190, '캐슬렉스제주골프클럽', '제주특별자치도 제주시 한림읍 금악리 산 41체', 33.3422761, 126.3503629, 'LEISURE', 2, '한라산과 한림바다가 한눈에 들어오는 서귀포시 안덕면에 위치한 캐슬렉스제주 골프클럽은 1995년 개장 이래 국내 최초로 미국여자프로 골프협회 공…', '한라산과 한림바다가 한눈에 들어오는 서귀포시 안덕면에 위치한 캐슬렉스제주 골프클럽은 1995년 개장 이래 국내 최초로 미국여자프로 골프협회 공식 투어인 삼성월드챔피언쉽 여자 골프대회를 유치하는 등 제주를 대표하는 골프클럽으로 인정받고 있다. 구릉지를 이용해 코스를 조성하는 등 자연 지형의 특성을 살려 개성적인 링크스 스타일 골프 코스로 평가받는 캐슬렉스제주 골프클럽의 골프 코스는 제주도 오름 특유의 언듈레이션을 그대로 살려 자연과 절묘한 조화를 이룸으로써 파워와 테크 그리고 부드러움을 요구하는 개성이 강한 골프 코스로 구성되어 있다.', 'https://tong.visitkorea.or.kr/cms/resource/07/3402907_image2_1.jpg'),
(191, '연동근린공원', '제주특별자치도 제주시 연동 1373-4공', 33.4823701, 126.4904591, 'NATURE', 4, '제주시 연동 지역 주민들의 산책과 휴식을 위해 조성된 생활권 공원입니다.', '제주시 연동 지역 주민들의 산책과 휴식을 위해 조성된 생활권 공원입니다. 녹지와 산책로가 마련되어 있어 가볍게 걷거나 쉬기 좋습니다. 도심 속에서 잠시 여유를 즐길 수 있는 공간입니다.', 'https://ak-d.tripcdn.com/images/1i65s2215aisge8qq0D28.jpg?proc=resize%2Fm_z%2Cw_375%2Ch_0%3Bformat%2Ff_webp%2C9C2E'),
(192, '탑동수산시장', '제주특별자치도 제주시 중앙로 28', 33.5157960, 126.5245604, 'COMMERCIAL', 4, '제주 원도심 바닷가를 따라 산책과 공연을 즐길 수 있는 해안광장', '제주 원도심 바닷가를 따라 산책과 공연을 즐길 수 있는 해안광장', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/1c70914e-57d4-4469-b7d2-072e321dc580.webp'),
(193, '성산일출도서관', '제주특별자치도 서귀포시 성산읍 고성오조로 133', 33.4552766, 126.9122911, 'CULTURE', 1, '서귀포시 성산읍에 위치한 지역 공공도서관입니다.', '서귀포시 성산읍에 위치한 지역 공공도서관입니다.
도서 열람과 대출, 독서·문화 프로그램 등을 통해 지역 주민의 문화생활을 지원하는 시설입니다.
성산일출봉 이름을 사용하지만 관광지라기보다는 지역 주민을 위한 공공문화시설입니다.', 'https://mblogthumb-phinf.pstatic.net/MjAyMTAyMDVfMjM3/MDAxNjEyNTAxNTI1NTg4.nNHE-PhG6fMMFMjHg5tOl616d13mttb1hemzmZVelxEg.Uej4fPXq2wt-2zoIiqWDMOgrIQslpMzdY6E23SW2NIcg.JPEG.passdongs/SE-7965b0f1-6744-4112-b43c-56fb815a078f.jpg?type=w800'),
(194, '대한불교조계종천왕사', '제주특별자치도 제주시 노형동 산 20-18임', 33.4092659, 126.4934781, 'HISTORY', 4, '아흔아홉 골의 수려한 풍광 속에 들어앉은 천왕사는 한라산 어승생 동쪽에 수많은 봉우리와 골짜기로 이루어진 아흔아홉 골 중 하나인 금봉곡 아래…', '아흔아홉 골의 수려한 풍광 속에 들어앉은 천왕사는 한라산 어승생 동쪽에 수많은 봉우리와 골짜기로 이루어진 아흔아홉 골 중 하나인 금봉곡 아래 위치한 사찰이다. 1955년 천왕사 근처 토굴에서 참선수행하던 비룡스님에 의해 수영산 선원이란 명칭으로 처음 창건되었다. 비록 건립된 지 오래되지 않았으나 1994년 전통 사찰로 지정되었다. 대웅전 바로 뒤로는 용바위라 불리는 커다란 바위가 있고, 마당 왼쪽 자락에 기세 좋게 곧게 뻗은 바위가 울창한 숲과 어우러져 절경을 이룬다. 사찰 옆의 냇물을 따라 올라가면 한라산의 유일한 폭포라는 선녀 폭포가 나오고, 사찰 입구에는 약수터가 있다. 특히 가을에 기암절벽 아래 물드는 단풍이 장관으로 알려져 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/25/269913d5-3512-4270-b0a1-0d8353478e8a.webp'),
(195, '동법사대웅전', '제주특별자치도 제주시 구좌읍 한동로1길 14', 33.5366510, 126.8275641, 'HISTORY', 1, '불교 사찰인 동법사의 중심 법당으로 불교 예배와 의식이 이루어지는 공간입니다.', '불교 사찰인 동법사의 중심 법당으로 불교 예배와 의식이 이루어지는 공간입니다. 전통적인 사찰 분위기와 불교 문화를 느낄 수 있습니다. 조용한 환경에서 사찰을 둘러보며 휴식을 취하기 좋습니다.', 'https://cdn.news.bbsi.co.kr/news/photo/202503/4020493_631186_1130.jpg'),
(196, '서귀포예술의전당', '제주특별자치도 서귀포시 태평로 270', 33.2462855, 126.5506386, 'CULTURE', 3, '지역 문화예술의 소통을 위해 2014년 개관된 서귀포 예술의전당', '지역 문화예술의 소통을 위해 2014년 개관된 서귀포 예술의전당', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/b9f02ff9-e369-44a2-8e78-6ad13e256feb.webp'),
(197, '명월리백난아기념관', '제주특별자치도 제주시 한림읍 명월로 48', 33.3884415, 126.2647915, 'EXPERIENCE', 2, '제주시 한림읍 명월리 출신 가수 백난아를 기념하기 위해 조성된 문화공간입니다.', '제주시 한림읍 명월리 출신 가수 백난아를 기념하기 위해 조성된 문화공간입니다.
대표곡인 찔레꽃 등 백난아의 음악과 생애를 통해 제주 출신 대중가수의 흔적을 살펴볼 수 있는 장소입니다.
명월성지와 명월대 등 한림 명월리의 역사·문화 관광지와 함께 둘러보기 좋은 곳입니다.', 'https://mblogthumb-phinf.pstatic.net/MjAyMzAxMDdfMjcw/MDAxNjczMDk1NjIwODk0.uaH9j6fBb_EQDpsKt9NiozYhNCQJMqjQdfS8KeOoZMUg.DS63iSnOvHdRbFigKPyBq4-_XY3yheMZFRTOY0YTIJIg.JPEG.okju0718/20230107%EF%BC%BF160543.jpg?type=w800'),
(198, '헌마공신 김만일기념관', '제주특별자치도 서귀포시 남원읍 서성로 919', 33.3360846, 126.6907789, 'HISTORY', 3, '83년의 일생동안 수천여 마리의 말을 나라에 바치다!', '83년의 일생동안 수천여 마리의 말을 나라에 바치다!', 'https://api.cdn.visitjeju.net/photomng/imgpath/202401/17/45669581-0ca1-4fac-9ff7-326aef767c1a.webp'),
(199, '동복해녀해산물직판장', '제주특별자치도 제주시 구좌읍 구좌해안로 35', 33.5560347, 126.7187189, 'HISTORY', 1, '제주 동복 지역에서 해녀와 지역 어민들이 채취한 해산물을 만나볼 수 있는 곳입니다.', '제주 동복 지역에서 해녀와 지역 어민들이 채취한 해산물을 만나볼 수 있는 곳입니다. 제주 바다에서 나는 다양한 해산물을 가까이에서 접할 수 있습니다. 제주 해녀 문화와 지역 먹거리를 함께 경험하기 좋은 장소입니다.', 'https://media.tel-co.net/isr/uploads/01_8187e5d29a.jpg?w=720'),
(200, '삼다수숲길', '제주특별자치도 제주시 조천읍 비자림로 485-15', 33.4298578, 126.6587641, 'LEISURE', 1, '푸른 초원을 거닐며 즐기는 승마체험', '푸른 초원을 거닐며 즐기는 승마체험', 'https://api.cdn.visitjeju.net/photomng/imgpath/202306/19/8b87ce43-4812-41ee-aec4-3ba59d5360a5.webp');

INSERT INTO `POI` (`poi_id`, `poi_name`, `address`, `latitude`, `longitude`, `category_code`, `region_id`, `description`, `detail_description`, `image_url`) VALUES
(201, 'K-아일랜드제주', '제주특별자치도 서귀포시 중문관광로 42', 33.2547079, 126.4100017, 'THEME', 3, '감귤·돌·곶자왈·바다·바람 등 제주를 상징하는 소재를 활용한 참여형 실내 전시공간입니다.', '감귤·돌·곶자왈·바다·바람 등 제주를 상징하는 소재를 활용한 참여형 실내 전시공간입니다.
트릭아트와 디지털아트, 오브제 등을 활용해 관람객이 직접 작품 속에 들어가 사진을 찍고 체험할 수 있습니다.
날씨와 관계없이 가족이나 친구와 즐기기 좋은 체험형 테마 관광시설입니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202608/31/cefd6466-45b4-439f-9d29-5064bfce8e42.webp'),
(202, '물영아리', '제주특별자치도 서귀포시 남원읍 수망리 산 188임', 33.3683944, 126.6920639, 'TRAIL', 3, '영아리는 신령스런 산이란 뜻이다.', '영아리는 신령스런 산이란 뜻이다. 앞에 ‘물’이란 접두어가 붙은 것은 분화구에 물이 고인 습지를 품고 있기 때문이다. 물영아리오름은 수망리 중잣성 생태 탐방로와 연계되어 있다. 잣성은 제주도의 전통적인 목축 문화 유물로 목초지에 쌓아 올린 경계용 돌담을 뜻한다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201907/24/67082bf5-af9a-4723-b9a1-ee8ce2a296b3.webp'),
(203, '제주허브동산', '제주특별자치도 서귀포시 표선면 돈오름로 170', 33.3285659, 126.8148443, 'THEME', 1, '2000년 부지매입을 시작으로 약 5년간 59,504m²(18,000평)의 대지 위에 허브동산을 만들어왔다.', '2000년 부지매입을 시작으로 약 5년간 59,504m²(18,000평)의 대지 위에 허브동산을 만들어왔다. 현재 약 180여 종의 허브와 우리 산하의 야생화로 채워진 각양각색의 정원들과 작은 동산들, 그리고 611.6m²(2,000평)의 체험 감귤농장 등 다양한 형태의 테마공원이 조성되어 있다. 또한 허브동산을 휘어감은 산책로, 허브 관련 제품을 구입할 수 있는 허브샵, 허브를 이용한 다양한 퓨전 음식을 맛볼 수 있는 카페, 허브에 대한 지식과 정보를 공유하고, 더욱 다양한 체험을 할 수 있는 허브체험관 등의 시설이 잘 구비되어 있어 연인 및 가족단위 혹은 기업의 단체에서 자연학습 및 데이트 코스, 워크숍 등 여러 가지 목적으로 이용 가능한 편안한 휴식처가 될 것이다.
그리고 허브 동산의 매력을 만끽할 수 있도록 설계된 6개 동의 각 숙소들은 허브정원 사이에 자리를 잡고 쾌적하고 안락한 여행이 될 수 있도록 최적의 환경을 구비하고 있다. 각 동 2층 침실 어디에서나 일출과 바다를 조망할 수 있고, 뒤로는 한라산이 한눈에 들어온다. 허브동산의 주요 테마는 ‘쉴休’, 봄날 오후 같은 편안하고 조용한 휴식. ‘번잡한 일상과 긴장된 도시 생활의 피로를 털어버리고, 몸과 마음에 쉼을 주자, 실컷 게으름을 피워도 하나 바쁠 것 없는, 느리게 사는 여유를 신이 인간에게 준 선물 가운데 마음껏 누리자.’ 이것이 허브동산이 추구하는 방향이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201810/16/f70e8222-2682-45e1-a1dc-aa63380f16f2.webp'),
(204, '고산성당', '제주특별자치도 제주시 한경면 칠전로 1', 33.3011273, 126.1802111, 'HISTORY', 2, '제주 고산 지역에 위치한 천주교 성당으로 지역 신자들의 미사와 공동체 활동이 이루어지는 곳입니다.', '제주 고산 지역에 위치한 천주교 성당으로 지역 신자들의 미사와 공동체 활동이 이루어지는 곳입니다. 조용하고 평온한 분위기 속에서 종교 공간의 모습을 살펴볼 수 있습니다. 제주 서부 지역의 천주교 문화를 접할 수 있는 장소입니다.', 'https://mblogthumb-phinf.pstatic.net/MjAyMzA0MjBfMTc0/MDAxNjgxOTM4OTE5OTIy.mKP7hXpGv8x_xD0p2KM8aCsfyT4xamo71_1hwvQGrLcg.8SmQV_gAVWBPqtdXhdjQkAReJ7tVrfm8Cc4IrVaVwusg.JPEG.pdi134/%EA%B3%A0%EC%82%B0%EC%84%B1%EB%8B%B913.jpg?type=w800'),
(205, '핀크스비오토피아', '제주특별자치도 서귀포시 안덕면 산록남로762번길 79', 33.3001490, 126.3953908, 'HISTORY', 2, '제주 자연환경과 어우러진 고급 주거·휴양 공간으로 조성된 곳입니다.', '제주 자연환경과 어우러진 고급 주거·휴양 공간으로 조성된 곳입니다. 주변의 오름과 녹지 등 제주 특유의 자연 경관을 가까이에서 만날 수 있습니다. 건축과 자연이 조화를 이루는 공간으로 알려져 있습니다.', 'https://cdn.imweb.me/upload/S202302013ae11fd38e6b6/307743ab1faa4.jpg'),
(206, '석부작박물관', '제주특별자치도 서귀포시 일주동로 8941', 33.2507852, 126.5363549, 'THEME', 3, '제주 현무암에 풍란과 야생화를 착근시킨 석부작 작품을 중심으로 조성된 생태형 박물관입니다.', '제주 현무암에 풍란과 야생화를 착근시킨 석부작 작품을 중심으로 조성된 생태형 박물관입니다.
제주의 돌과 식물을 활용한 작품뿐 아니라 다양한 야생화와 분재를 감상할 수 있는 정원형 공간입니다.
제주 자연과 식물의 생명력을 느끼며 산책하기 좋은 문화·생태 관광지입니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202112/13/eadb0e7e-d377-4253-a73e-c0fa673962bb.webp'),
(207, '제주동문재래야시장', '제주특별자치도 서귀포시 남원읍 중산간동로 6596-3', 33.2992720, 126.6811094, 'COMMERCIAL', 3, '다양한 먹거리와 상업의 중심, 제주 동문 재래시장', '다양한 먹거리와 상업의 중심, 제주 동문 재래시장', 'https://api.cdn.visitjeju.net/photomng/imgpath/202410/16/cb66093f-ad09-4347-8e91-3476ea9637bb.webp'),
(208, '핀크스골프클럽', '제주특별자치도 서귀포시 안덕면 산록남로 863', 33.3162110, 126.3951133, 'CULTURE', 2, '한국 골프장을 대표하는 세계적인 골프장', '한국 골프장을 대표하는 세계적인 골프장', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/e64fc6a8-98ff-438a-8d98-16483cddd87c.webp'),
(209, '한라생태숲', '제주특별자치도 제주시 516로 2596', 33.4312933, 126.5976996, 'NATURE', 4, '한라생태숲은 1970년대 초부터 1995년까지 개인에게 대부돼 마소의 방목지로 사용했던 곳이었다.', '한라생태숲은 1970년대 초부터 1995년까지 개인에게 대부돼 마소의 방목지로 사용했던 곳이었다. 제주 식물의 보고에 걸맞은 산림생물 난대, 온대, 한대 식물 등 다양한 식물상을 조화롭게 설계하여 식재 생태복원 시켰으며, 곶자왈 지대, 천연림 지역을 유전자원 보전지역으로 관리하고 있다. 또한 한라생태숲은 시험연구림으로서의 기능도 갖추고 있어 제주도의 온.난대 수종 및 한라산 고산대 희귀수종에 대한 유전자 보전 연구와 한라산의 훼손지 복구를 위한 식물증식 및 내한성 적응시험림의 역할도 수행하고 있다. 한라생태숲은 훼손되어 방치되었던 야초지를 원래의 숲으로 복원 조성한 곳으로 산림트래킹과 함께 자연생태계의 다양한 모습을 즐길 수 있다. 한라산에 서식하는 동물을 만날 수 있으며, 특히 난대성식물에서부터 한라산 고산식물까지 모두 볼 수 있다. 생태로, 전망대, 양묘하우스, 테마별 산책로, 유전자보존 조직배양실 등 기반시설과 단풍나무숲, 벚나무숲, 구상나무숲, 참꽃나무숲 등 13개의 테마숲, 생태숲 전체의 축소판인 암석원이 중앙에 조성되어 숲다운 숲의 면모를 보여주고 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/19/fdcaeff5-bf92-44ae-a0f0-9e43288bd205.webp'),
(210, '드르쿰다in성산', '제주특별자치도 서귀포시 성산읍 섭지코지로25번길 64', 33.4445124, 126.9190859, 'EXPERIENCE', 1, '성산 지역의 제주 자연과 감성적인 공간 구성을 함께 즐길 수 있는 복합 관광지입니다.', '성산 지역의 제주 자연과 감성적인 공간 구성을 함께 즐길 수 있는 복합 관광지입니다. 다양한 포토존과 야외 공간이 마련되어 있어 사진 촬영과 산책을 즐기기 좋습니다. 성산 관광 일정 중 여유롭게 머물기 좋은 곳입니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202607/15/e07763e7-4c0d-4724-ab99-5c64cd2a0933.webp'),
(211, '한수풀도서관', '제주특별자치도 제주시 한림읍 한림상로 240-11', 33.4203220, 126.2684890, 'CULTURE', 2, '핸드메이드 소품들을 판매하고 있는 아기자기한 소품 숍', '핸드메이드 소품들을 판매하고 있는 아기자기한 소품 숍', 'https://api.cdn.visitjeju.net/photomng/imgpath/201812/20/13b9add0-2a33-4736-bd66-6fa5693ba398.webp'),
(212, '서문공설시장', '제주특별자치도 제주시 서문로4길 13-2', 33.5113351, 126.5179556, 'COMMERCIAL', 4, '서문공설시장은 제주시 서부중심에 위치한 60년의 역사를 가진 전통 재래시장이다.', '서문공설시장은 제주시 서부중심에 위치한 60년의 역사를 가진 전통 재래시장이다. 80여 개의 점포를 갖추고 있으며 축산, 정육 등 육류 소비 특화시장으로 선정되어 제주도내에서 가장 활발한 육류소비가 이루어지고 있다. 시장 내에는 3개의 정육 마트가 자리하고 있다. 원하는 부위의 고기를 저렴하게 구매한 후 정육 식당이 들어선 상가건물을 찾아가면 상차림 비용을 지불하고 구매한 고기를 그 자리에서 맛볼 수 있다. 이 외에도 식품과 건어물, 과일 등 다양한 품목들이 판매되고 있다. 다른 상설시장에 비해 한산한 편이며, 주차 시설이 잘 갖추어져 있는 것이 특징이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/195b9466-c9d3-496d-8b97-0af51b2d91cf.webp'),
(213, '퍼시픽랜드', '제주특별자치도 서귀포시 중문관광로 154-17', 33.2441856, 126.4172212, 'LEISURE', 3, '퍼시픽 리솜은 호반그룹의 레저계열사로 중문의 아름다운 해변길에, 드넓은 남태평양의 바다 위에 자리한 해양문화 복합공간이다.', '퍼시픽 리솜은 호반그룹의 레저계열사로 중문의 아름다운 해변길에, 드넓은 남태평양의 바다 위에 자리한 해양문화 복합공간이다. 남녀노소 즐길 수 있는 선진국형 해양레포츠 요트 마리나 프로그램과 함께 특급 호텔 출신의 셰프가 준비하는 신선하고 맛있는 씨푸드 다이닝, 이국적인 정경에서 누리는 각종 문화이벤트가 펼쳐지는 공간이다. 요트에서 바라보는 경이로운 바다, 제주의 신선한 해산물로 정성스럽게 만들어 내는 맛있는 요리와 함께 바다를 즐기는 다채로운 방법을 만날 수 있다.', 'https://tong.visitkorea.or.kr/cms/resource/60/2587960_image2_1.bmp'),
(214, '성클라라수도원', '제주특별자치도 제주시 한림읍 금악북로 320', 33.3480220, 126.3187446, 'HISTORY', 2, '성클라라수도원에 부속된 성당', '성클라라수도원에 부속된 성당', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/3e9a88bf-cf9b-4ef9-aa02-c53dd8023064.webp'),
(215, '아뮤제', '제주특별자치도 제주시 관덕로 26', 33.5128497, 126.5219420, 'CULTURE', 4, '제주시 원도심에 위치한 소규모 전시·문화공간입니다.', '제주시 원도심에 위치한 소규모 전시·문화공간입니다.
관덕정과 가까운 구도심에서 문화예술 콘텐츠를 접할 수 있는 공간입니다.
대규모 관광시설보다는 제주 원도심을 둘러보면서 함께 방문하기 좋은 문화공간입니다.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRSzhPJt-EipxoQFNDxp94yp5lbmCoht27Tt_BhvI5k8A&s'),
(216, '안덕산방도서관', '제주특별자치도 서귀포시 안덕면 화순리 1963 대', 33.2549332, 126.3306741, 'CULTURE', 2, '서귀포시 안덕면 지역 주민을 위해 운영되는 공공도서관입니다.', '서귀포시 안덕면 지역 주민을 위해 운영되는 공공도서관입니다.
도서 열람과 대출을 비롯해 어린이와 주민을 위한 독서·문화 프로그램을 제공하는 공간입니다.
산방산 관광지와 이름이 비슷하지만 일반 관광시설보다는 지역 생활문화시설에 해당하는 장소입니다.', 'https://cdn.jejusori.net/news/photo/202602/443731_477344_4938.jpg'),
(217, '새별오름', '제주특별자치도 제주시 애월읍 봉성리 산 59-8목', 33.3662778, 126.3577306, 'NATURE', 2, '제주 서부 애월에 위치한 억새가 아름다운 대표 오름', '제주 서부 애월에 위치한 억새가 아름다운 대표 오름', 'https://api.cdn.visitjeju.net/photomng/imgpath/202410/21/dd229994-9625-44a2-985c-f710bca7f286.webp'),
(218, '넓은목장', '제주특별자치도 서귀포시 표선면 성읍이리로57번길 162', 33.4238323, 126.7682184, 'TRAIL', 1, '제주의 넓은 초지와 목장 풍경을 감상할 수 있는 공간입니다.', '제주의 넓은 초지와 목장 풍경을 감상할 수 있는 공간입니다. 탁 트인 들판과 자연이 어우러져 제주 중산간의 여유로운 분위기를 느낄 수 있습니다. 드라이브 중 들러 풍경을 감상하거나 사진을 찍기 좋은 장소입니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202408/21/8a1b4b1b-4a06-46a6-87f9-e839954ad174.webp'),
(219, '귤한가', '제주특별자치도 제주시 한림읍 명월성로 234-1', 33.3884546, 126.2630733, 'COMMERCIAL', 2, '제주시 한림읍에 위치한 제주 감귤 관련 상품을 만나볼 수 있는 상업 공간입니다.', '제주시 한림읍에 위치한 제주 감귤 관련 상품을 만나볼 수 있는 상업 공간입니다. 제주를 대표하는 감귤을 소재로 한 제품과 지역 특색을 느낄 수 있습니다. 한림 지역 관광과 함께 가볍게 들러보기 좋은 곳입니다.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTj9Zkjp_qWJeC6mLdnp3kIaAGw-lmowKOZL1oEisomm4Oq72OwP7l0ITY&s=10'),
(220, '신천목', '제주특별자치도 서귀포시 성산읍 일주동로 5417', 33.3560159, 126.8637294, 'NATURE', 1, '제주 지역의 자연과 주변 경관을 감상할 수 있는 한적한 장소입니다.', '제주 지역의 자연과 주변 경관을 감상할 수 있는 한적한 장소입니다. 번잡한 관광지와는 다른 차분한 분위기 속에서 제주 특유의 풍경을 느낄 수 있습니다. 주변을 천천히 둘러보며 쉬어가기 좋은 곳입니다.', 'https://cdn.jejusori.net/news/photo/202407/428113_447884_5136.jpg'),
(221, '제주시산림조합가든센터', '제주특별자치도 제주시 오남로 288', 33.4702909, 126.5134041, 'COMMERCIAL', 4, '다양한 식물과 정원 관련 상품을 살펴볼 수 있는 산림·원예 공간입니다.', '다양한 식물과 정원 관련 상품을 살펴볼 수 있는 산림·원예 공간입니다. 계절별 식물과 묘목 등을 가까이에서 접할 수 있어 자연과 식물에 관심 있는 방문객에게 좋습니다. 여유롭게 둘러보며 정원 문화를 경험할 수 있습니다.', 'https://mblogthumb-phinf.pstatic.net/MjAyMTAzMDFfMTc5/MDAxNjE0NjA1NzIwNjE5.BVVGjkTiQPkvtmjCZY532I9dYMMea7IJcI7ihL4xxWUg.-T5L3F6cqNtc2yZiylHRKhQuSR0TihRyDAvaNmWgFuwg.JPEG.jejusilencer/SE-2f819920-ca97-4804-b06b-db2c26b664f2.jpg?type=w800'),
(222, '산방산', '제주특별자치도 서귀포시 안덕면 사계리 산 16임', 33.2415639, 126.3133694, 'NATURE', 2, '설문대할망이 한라산 꼭대기를 뽑아 던졌다는 전설이 전해지는 산방산 · 명승 제77호 · 산방산 암벽식물지대 천연기념물 제376호 · 제주올레…', '설문대할망이 한라산 꼭대기를 뽑아 던졌다는 전설이 전해지는 산방산 · 명승 제77호 · 산방산 암벽식물지대 천연기념물 제376호 · 제주올레 10코스', 'https://api.cdn.visitjeju.net/photomng/imgpath/202410/16/c2172c06-dda2-4f16-ae3f-a2314b6f9f05.webp'),
(223, '최남단체험감귤농장', '제주특별자치도 서귀포시 남원읍 남위남성로 164', 33.2910653, 126.6938838, 'EXPERIENCE', 3, '살아있는 제주농촌을 체험할 수 있는 농장', '살아있는 제주농촌을 체험할 수 있는 농장', 'https://api.cdn.visitjeju.net/photomng/imgpath/202401/17/613b487d-bb3a-4301-946e-08ae226b7790.webp'),
(224, '아라리오뮤지엄', '제주특별자치도 제주시 산지로 23', 33.5149333, 126.5293520, 'CULTURE', 4, '국내 최고의 미술품 컬렉터로 꼽히는 김창일 회장이 제주 탑동 인근 원도심에 버려진 옛 영화관 건물을 이용해 만든 현대미술관이다.', '국내 최고의 미술품 컬렉터로 꼽히는 김창일 회장이 제주 탑동 인근 원도심에 버려진 옛 영화관 건물을 이용해 만든 현대미술관이다. 오래된 건물을 크게 개조하지 않고 곳곳에 이전의 흔적을 남겨두어 현대 미술품 뿐만 아니라 원도심의 정취를 느낄 수 있다. 세계적으로 유명한 작가들의 작품부터 국내에서 유명한 작가들의 작품까지 제주에서 만날 수 있을 거라 기대하지 않았던 유명한 작품들을 만날 수 있는 곳이다.', 'https://dynamic-media-cdn.tripadvisor.com/media/photo-o/07/ab/6d/52/caption.jpg?w=1200&h=-1&s=1'),
(225, '함덕해수욕장', '제주특별자치도 제주시 조천읍 조함해안로 525', 33.5430616, 126.6692389, 'NATURE', 1, '제주올레 19코스를 걷다 보면 에메랄드빛 보석을 품고 있는 함덕해수욕장을 만날 수 있다.', '제주올레 19코스를 걷다 보면 에메랄드빛 보석을 품고 있는 함덕해수욕장을 만날 수 있다. 제주시 조천읍 함덕리에 자리한 함덕해수욕장은 해수욕장 바로 옆에 우뚝 선 오름(서우봉) 덕분에 ‘함덕서 우봉해변’이라고도 불린다. 제주공항에서 불과 20㎞ 떨어졌지만, 이곳에 도착하는 순간 다른 나라에 온 것 같은 기분이 든다. 입구부터 환영해 주는 키 큰 야자수들, 하얀 모래와 대조를 이루는 에메랄드빛 바다, 모래와 미역마저 투명하게 비춰주는 맑은 물과 하얀 파도가 그러하다. 제주도 수많은 해수욕장 중에서도, 바다색이 가장 예쁜 3곳을 꼽는다면 단연 협재, 김녕, 그리고 함덕해수욕장이다. 물이 맑고 수심이 얕아서 가족단위 피서지로도 좋다. 해수욕장 서쪽은 구름다리로 연결되어 있어 바다 위를 걷는 듯한 경험을 할 수 있다. 피크닉 하기 좋은 잔디밭, 밤에도 안심하고 바다를 즐길 수 있는 산책로가 매력이어서 사계절 찾는 이들의 발길이 끊이지 않는다. 특히 여름에는 야간개장도 하고 있어 제주의 푸른 밤을 바다에서 즐길 수 있다. 바로 옆에 자리한 서우봉은 봄이 되면 노란 유채꽃으로 여름엔 초록빛으로 계절마다 그림 같은 풍경을 선사한다. 서우봉에 오르면 함덕해수욕장을 한눈에 담을 수 있는 호사를 누릴 수 있다. 날씨가 좋으면 한라산과 동쪽 오름들도 내려다볼 수 있는 최고의 전망 포인트이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202408/20/513120bd-dc32-4f3a-9cf1-64d7561990c3.webp'),
(226, '제주목 관아', '제주특별자치도 제주시 관덕로 19', 33.5133517, 126.5214691, 'HISTORY', 4, '국가지정 보물 제 322호로 제주에 현존하는 건물 중 가장 오래된 건물 · 제주시 삼도2동 · 보물 제322호 · 올레17코스 · 4·3 유적지', '국가지정 보물 제 322호로 제주에 현존하는 건물 중 가장 오래된 건물
· 제주시 삼도2동
· 보물 제322호
· 올레17코스
· 4·3 유적지', 'https://api.cdn.visitjeju.net/photomng/imgpath/201908/16/3752d151-dad4-4199-8227-0e5d96e56d8e.webp'),
(227, '탐라승마장', '제주특별자치도 제주시 조천읍 교래리 산 10-8목', 33.4334168, 126.7184275, 'EXPERIENCE', 1, '1983년에 오픈한 ‘탐라승마장’은 31년 전통을 지닌 승마장이다.', '1983년에 오픈한 ‘탐라승마장’은 31년 전통을 지닌 승마장이다. 80여두의 잘 훈련된 한라마와 조랑말을 보유하고 있으며, 처음 타는 초보자도 쉽게 승마할 수 있다. 말 탑승 전 승마 모자를 착용 후 승마탑승을 시작한다. 주의사항으로는 승마체험자, 대기자, 일행은 체험이 끝날 때까지 교관의 통제에 반드시 따라야 하며 승마장 말들은 익숙하지 않은 사람이나 사물에 의해 놀랄 경우가 있어 안전을 위해 대기실에서 촬영을 해야 한다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202306/20/89bcbb87-2b33-470b-a4e9-704b97412889.webp'),
(228, '고호의정원', '제주특별자치도 서귀포시 성산읍 삼달신풍로 132', 33.3733672, 126.8437045, 'THEME', 1, '위대한 작가 반고흐의 지난 삶을 보고 듣고 만질 수 있는 ''고흐의 정원''', '위대한 작가 반고흐의 지난 삶을 보고 듣고 만질 수 있는 ''고흐의 정원''', 'https://api.cdn.visitjeju.net/photomng/imgpath/201911/19/f437e678-82e3-444c-a13d-70dfc85e63b3.webp'),
(229, '삼무공원', '제주특별자치도 제주시 신대로10길 48-9', 33.4917804, 126.4919526, 'NATURE', 4, '삼무공원은 제주 시내 연동에 있다.', '삼무공원은 제주 시내 연동에 있다. 1978년 도시 근린공원으로 조성하였으며 삼무의 의미는 제주에 도둑, 대문, 거지가 없다는 삼무에서 따 온 이름이다. 삼무공원은 베두리오름에 조성된 공원으로, 베두리오름은 작은 언덕으로 삼무공원이 곧 베두리오름이다. 공원에는 증기기관차가 있는데, 1978년 박정희 대통령이 섬에 사는 아이들에게 기차를 보여주려고 사용이 중단된 기차를 흑산도와 제주도에 보낸 것이다. 현재는 제주도에만 미카형 증기기관차가 남아있다. 연동 주민들이 산책과 운동을 즐기는 공원으로 봄에는 능수 벚꽃이 아름다워 여행자들이 찾아온다.', 'https://tong.visitkorea.or.kr/cms/resource/39/4067839_image2_1.jpg'),
(230, '생각하는정원', '제주특별자치도 제주시 한경면 녹차분재로 675', 33.3252730, 126.2548200, 'NATURE', 2, '국가지정 민간정원으로 대한민국 대표정원', '국가지정 민간정원으로 대한민국 대표정원', 'https://api.cdn.visitjeju.net/photomng/imgpath/202607/20/375e061d-2c5c-4dff-9b2d-02765077f4a0.jpg'),
(231, '방귤당', '제주특별자치도 서귀포시 효돈순환로 217-8', 33.2565184, 126.6217423, 'EXPERIENCE', 3, '제주의 감귤을 테마로 한 먹거리와 분위기를 즐길 수 있는 공간입니다.', '제주의 감귤을 테마로 한 먹거리와 분위기를 즐길 수 있는 공간입니다. 제주 특산물인 감귤을 활용한 다양한 메뉴와 제품을 접할 수 있습니다. 여행 중 제주다운 달콤한 휴식을 즐기기 좋은 장소입니다.', 'https://mblogthumb-phinf.pstatic.net/MjAxOTEyMDdfMTM2/MDAxNTc1NjQ1MDMxNTg1.0PSdVP6WbyL0rvgqhkA2MGn8NwYEX_d7_H4vUtGzTH4g.NF-INXTJ6YIN7Mo1R6nP6s9171Gb3DllKkWnZp3gjeEg.JPEG.kotmul77/IMG_8478.jpg?type=w800'),
(232, '성읍녹차마을 영농조합법인', '제주특별자치도 서귀포시 표선면 중산간동로 4778', 33.3810863, 126.7899569, 'NATURE', 1, '녹차재배의 최적지 청정제주에서 만나는 녹차다원', '녹차재배의 최적지 청정제주에서 만나는 녹차다원', 'https://api.cdn.visitjeju.net/photomng/imgpath/202112/02/c5d8b2e6-1417-4dbf-8f8e-e8863c6d7973.webp'),
(233, '김녕해수욕장', '제주특별자치도 제주시 구좌읍', 33.5579065, 126.7596007, 'NATURE', 1, '하얀 모래와 부서지는 파도가 아름다운 해수욕장', '하얀 모래와 부서지는 파도가 아름다운 해수욕장', 'https://api.cdn.visitjeju.net/photomng/imgpath/202407/15/92793810-56d3-493c-8566-55c63922229f.webp'),
(234, '노형수퍼마켙', '제주특별자치도 제주시 노형로 89', 33.4648249, 126.4553556, 'CULTURE', 4, '노형수퍼마켙은 약 4000㎡(1200여 평)의 면적과 최대 높이 20m(6층 건물 높이)의 웅장하고 압도적인 규모의 미디어아트 테마파크이다.', '노형수퍼마켙은 약 4000㎡(1200여 평)의 면적과 최대 높이 20m(6층 건물 높이)의 웅장하고 압도적인 규모의 미디어아트 테마파크이다.
‘일상과 비일상이 공존하는 공간 속에서 자신만의 아이덴티티를 발견하는 여정’이라는 스토리라인으로, 내부는 ‘노형수퍼마켙 프리쇼’, ‘베롱베롱’, ‘뭉테구름’, ‘와랑와랑’, ‘곱을락’ 등 미디어아트 영상 공간을 중심으로 한 총 5개의 전시 공간으로 구성되어 있다. 내부 카페인 ‘노형다방’에서는 흑백 콘셉트의 다양한 음료 및 디저트를 즐길 수 있으며, 기념품 샵인 ‘노형잡화점’에서는 노형수퍼마켙 고유의 패턴이 들어간 특별한 기념품들을 만나볼 수 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202410/10/04e34d17-5929-48b7-b3e7-351ecbec40ae.webp'),
(235, '금능석물원', '제주특별자치도 제주시 한림읍 금능리 1282-10임', 33.3856177, 126.2271520, 'EXPERIENCE', 2, '똑같이 생긴 하르방만 본 여행객들에게 제주 석물의 진수를 감상할 수 있게 하는 곳이 바로 금능석물원이다.', '똑같이 생긴 하르방만 본 여행객들에게 제주 석물의 진수를 감상할 수 있게 하는 곳이 바로 금능석물원이다. 금능석물원은 40여 년을 돌하르방 제작에 힘쓴 장공익 명장이 조성한 공원이다. 돌하르방을 비롯해 해녀상, 동자상, 물허벅을 지고 아이를 돌보는 어머니상 등 제주 지역의 전설을 돌로 표현한 작품, 제주의 생활, 민속, 문화를 상징하는 조각품들이 전시되어 있다. 세계 여러 나라의 대통령과 총리, 지도자들이 제주도를 방문했을 때 선물했던 돌하르방 모형도 함께 전시해 놓았다. 금능석물원의 전체적인 분위기를 주도하는 불교적인 색채가 묻어나는 석불들도 볼 수 있다. 금릉석물원 내에는 정녀굴과 조롱굴 2개의 동굴이 있으며 굴 안에는 불공을 드릴 수 있는 암자가 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202205/30/fd593a05-2426-4e3e-bd17-5760419eb329.webp'),
(236, '조안베어뮤지엄', '제주특별자치도 서귀포시 대포로 113', 33.2402746, 126.4341148, 'CULTURE', 3, '테디베어 아티스트 조안오 디자이너가 직접 만든 테디베어를 다양한 테마로 전시', '테디베어 아티스트 조안오 디자이너가 직접 만든 테디베어를 다양한 테마로 전시', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/e4d86d9a-fad1-4680-999b-9ced744125b6.webp'),
(237, '이마트 서귀포점', '제주특별자치도 서귀포시 태평로 363', 33.2461935, 126.5600880, 'EXPERIENCE', 3, '문섬과 새끼섬을 바라보며 새연교를 따라 걷는 아름다운 산책', '문섬과 새끼섬을 바라보며 새연교를 따라 걷는 아름다운 산책', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/51fa1314-f59a-4f33-916e-855f4113cf13.webp'),
(238, '한림민속5일시장', '제주특별자치도 제주시 한림읍 한수풀로4길 10', 33.4201858, 126.2741627, 'COMMERCIAL', 2, '여러분 곁에 가까이 있는 한림조끄뜨레시장', '여러분 곁에 가까이 있는 한림조끄뜨레시장', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/f5f50f9e-8b24-42d8-9845-1aa765fb2d3e.webp'),
(239, '제주문화원제주해변공연장', '제주특별자치도 제주시 중앙로 2', 33.5179034, 126.5241959, 'NATURE', 4, '제주시 탑동에 위치한 해변공연장', '제주시 탑동에 위치한 해변공연장', 'https://api.cdn.visitjeju.net/photomng/imgpath/202112/09/07a05c85-0944-4307-9954-6c00ad5bd7b8.webp'),
(240, '오현단', '제주특별자치도 제주시 오현길 61', 33.5102600, 126.5257285, 'HISTORY', 4, '제주도 기념물 제1호, 조선시대 제주 교학 발전에 공헌한 다섯 분을 배향했던 옛 터', '제주도 기념물 제1호, 조선시대 제주 교학 발전에 공헌한 다섯 분을 배향했던 옛 터', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/762ce4a4-4a10-494f-868c-20f6d5b2d256.webp'),
(241, '쇠소깍', '제주특별자치도 서귀포시 쇠소깍로 128', 33.2520909, 126.6229523, 'EXPERIENCE', 3, '제주올레 5코스의 끝이자 6코스의 시작으로, 바닷물과 민물이 만나는 비밀스러운 계곡', '제주올레 5코스의 끝이자 6코스의 시작으로, 바닷물과 민물이 만나는 비밀스러운 계곡', 'https://api.cdn.visitjeju.net/photomng/imgpath/202410/16/a8784094-08b6-4e9e-acf2-d86ab445dda5.webp'),
(242, '존자암', '제주특별자치도 서귀포시 영실로 243', 33.3477308, 126.4818133, 'HISTORY', 3, '제주도 서귀포시 하원동 볼래오름 기슭에 있는 옛 사찰 존자암의 자리', '제주도 서귀포시 하원동 볼래오름 기슭에 있는 옛 사찰 존자암의 자리', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/524dd81e-1b29-4bb3-8947-5dd421c51d44.webp'),
(243, 'J1카트클럽', '제주특별자치도 제주시 연북로 424', 33.4797943, 126.5265510, 'LEISURE', 4, '제주시에서 카트 주행을 즐길 수 있는 레저 체험 공간입니다.', '제주시에서 카트 주행을 즐길 수 있는 레저 체험 공간입니다. 직접 카트를 운전하며 속도감 있는 체험을 할 수 있어 활동적인 여행을 원하는 방문객에게 잘 어울립니다. 친구나 가족과 함께 색다른 스포츠 체험을 즐기기 좋은 곳입니다.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSWQJLCqnY5AzbJSV-m5xbsBeF1LhslaEoPTNlgTeSr91yo63XtaTL3VMsF&s=10'),
(244, '서귀포시국민체육센터서부도서관', '제주특별자치도 서귀포시 중문관광로 346', 33.2507928, 126.4320260, 'LEISURE', 3, '서귀포시 중문동에 위치한 생활체육·공공문화 기능의 복합시설입니다.', '서귀포시 중문동에 위치한 생활체육·공공문화 기능의 복합시설입니다.
체육활동을 위한 시설과 도서 열람·독서문화 서비스를 이용할 수 있는 공간입니다.
관광객 대상 명소보다는 지역 주민의 건강과 문화생활을 지원하는 공공시설 성격이 강한 장소입니다.', 'https://mblogthumb-phinf.pstatic.net/MjAyMzEyMDVfMjkx/MDAxNzAxNzM5ODY5NjA4.vpT1rwBXZVX041YhYL1pt-8aVoxnKZlNeTG0EFcKTnIg.EFmXhcNIGgiI0OfZvzCx-W35Qa_tvln_AiEJmtv8Kesg.JPEG.armdaunai/20231203%EF%BC%BF164035.jpg?type=w800'),
(245, '보성시장', '제주특별자치도 제주시 동광로1길 32', 33.5033085, 126.5277713, 'COMMERCIAL', 4, '제주 원도심 속에 있는 보성시장은 1972년에 개설되어, 50여 년 동안 자리를 지켜온 전통시장이다.', '제주 원도심 속에 있는 보성시장은 1972년에 개설되어, 50여 년 동안 자리를 지켜온 전통시장이다. 특유의 정감 가는 분위기로 제주시 상인들의 삶을 엿볼 수 있는 곳이다. 보성시장은 식당가와 정육, 수산물, 건어물, 빵집, 떡집, 수선집 등 다양한 종류의 점포가 들어서 있다. 장터에서 빠질 수 없는 먹거리도 풍성하다. 보성시장 최고의 먹거리는 제주식 전통 순대이다. 식당이 밀집해 있는 상가 내에는 대부분 순대를 전문으로 하는 식당이 주를 이루어 자연스레 순대 골목이 형성되었다. 제주식 전통 순대로, 식당 모두 각자 다른 특색을 보유하였으며 순대국밥, 모둠 순대, 순대 국수 등 다양한 순대 요리를 맛볼 수 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/00123e18-ec0b-4f2e-908c-474e7c9523b1.webp'),
(246, '법환항', '제주특별자치도 서귀포시 법환동 286-4 제', 33.2365580, 126.5162757, 'NATURE', 3, '서귀포 법환동에 위치한 작은 항구로, 어선과 바다가 어우러진 제주다운 풍경을 볼 수 있습니다.', '서귀포 법환동에 위치한 작은 항구로, 어선과 바다가 어우러진 제주다운 풍경을 볼 수 있습니다. 범섬을 비롯한 주변 해안 경관을 감상하기 좋습니다. 산책과 사진 촬영을 즐기며 한적한 포구 분위기를 느낄 수 있습니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/15/c79af702-3c56-4f15-9438-cb34f383244b.webp'),
(247, '맥파이브루영캠퍼니', '제주특별자치도 제주시 동회천1길 23', 33.5031722, 126.6172746, 'EXPERIENCE', 4, '경리단길 골목서 동네 친구 4명이 맥주를 마시다 시작하게 된 사업이 바로 맥파이 브루잉 컴퍼니이다.', '경리단길 골목서 동네 친구 4명이 맥주를 마시다 시작하게 된 사업이 바로 맥파이 브루잉 컴퍼니이다. 피맥집으로도 유명한 맥파이는 물 좋고 공기 좋은 제주도에 양조장을 두고 있다. 맥파이 제주 양조장투어는 예약 없이도 가능하나, 인원이 많다면 사전 예약을 추천한다. 예약은 이메일과 전화로 접수할 수 있다. 또한 시간대별로 총 4번 주말에만 투어가 가능하니 참고하자. 이곳에서는 맥주가 만들어지는 모든 과정을 처음부터 끝까지 직접 확인할 수 있으며, 투어를 위해 따로 마련된 전시장이 아니기 때문에 양조설비 사이를 직접 돌아보며 설명을 듣고 질문을 할 수 있다. 1인당 지급하는 참가비에는 투어를 포함해 맥주 한 잔 가격이 포함되어 있다. 현장결제만 가능하며, 만 8세 미만의 아동은 입장이 불가하다. 이밖에도 수제 맥주에 관한 다양한 교육 프로그램을 진행하고 있다. 맥주뿐만 아니라 맥주에 담긴 문화를 함께 나눌 수 있는 프로그램도 제공하고 있어 맥주를 좋아하는 사람들에게 인기 있는 양조장이다. 탑동에 맥파이 펍이 있으니 서귀포까지 가는 길이 멀다면 가까운 시내에서 간단하게 맥파이 맥주를 한 잔 즐겨보자.

(출처 :제주 문화관광 홈페이지)', 'https://tong.visitkorea.or.kr/cms/resource/88/3396588_image2_1.jpg'),
(248, '대유랜드', '제주특별자치도 서귀포시 상예로 381', 33.2756474, 126.3932686, 'LEISURE', 3, '제주 중산간 지역에서 다양한 야외 레저와 체험 활동을 즐길 수 있는 관광 공간입니다.', '제주 중산간 지역에서 다양한 야외 레저와 체험 활동을 즐길 수 있는 관광 공간입니다. 넓은 자연환경 속에서 활동적인 시간을 보내기 좋습니다. 가족이나 단체 여행객이 함께 방문하기 좋은 체험형 장소입니다.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTc0XMAjLffN7CF6VYQyuE0ii5iFK0ZLOQNj1LFXmjvrSHEqv6NWWMlCYCQ&s=10'),
(249, '제주참솣가마', '제주특별자치도 서귀포시 성산읍 삼달로 47', 33.3689841, 126.8633083, 'THEME', 1, '제주의 전통적인 숯가마 문화를 체험할 수 있는 공간입니다.', '제주의 전통적인 숯가마 문화를 체험할 수 있는 공간입니다. 숯과 열을 활용한 찜질이나 휴식을 즐기며 색다른 제주 체험을 할 수 있습니다. 여행 중 피로를 풀며 쉬어가기 좋은 곳입니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201905/16/d2b1047e-e823-484b-b7a4-a8b33f6e2e66.webp'),
(250, '보림사', '제주특별자치도 제주시 사라봉동길 61', 33.5175121, 126.5464874, 'HISTORY', 4, '보림사는 1957년에 창건되었으며 제주 사라봉 입구에 자리 잡고 있다.', '보림사는 1957년에 창건되었으며 제주 사라봉 입구에 자리 잡고 있다. 절에는 대웅전, 법당, 천왕문, 보림사 부도, 보림사 탑 등이 있다. 특히 2002년 5월 15일 제주도 유형문화유산으로 지정된 목조관음보살좌상이 보림사 본존불로 봉안되어 있는데, 전라남도 순천 선암사에서 조선 후기에 제작된 불상으로 보림사 창건 당시 제주로 옮겨 온 것이다. 보림사는 제주 오름인 사라봉 초입에 있어서 불교 신자뿐만 아니라 제주도민과 관광객이 자주 찾는 곳이다. 보림사 사찰 주변에는 칠머리당영등굿 전수관, 모충사, 우당도서관, 국립제주박물관 등이 있어 제주도 여행길에 함께 둘러보는 것도 좋다.', 'https://tong.visitkorea.or.kr/cms/resource/12/3477912_image2_1.jpg'),
(251, '제주승마공원', '제주특별자치도 제주시 애월읍 녹고메길 152-1', 33.4047855, 126.4060719, 'NATURE', 2, '국내 최대 외승,트래킹/ 국내 최초 야외 야간 승마 및 전문 승마체험 및 회원제 승마장', '국내 최대 외승,트래킹/ 국내 최초 야외 야간 승마 및 전문 승마체험 및 회원제 승마장', 'https://api.cdn.visitjeju.net/photomng/imgpath/202307/26/202bf177-0edd-4e66-9e43-d1d90e873149.webp'),
(252, '제주도립김창열미술관', '제주특별자치도 제주시 한림읍 용금로 883-5', 33.3390713, 126.2686718, 'CULTURE', 2, '물방울 화가로 불리는 김창열화백의 업적과 정신을 기리기 위해 설립한 제주도립 미술관', '물방울 화가로 불리는 김창열화백의 업적과 정신을 기리기 위해 설립한 제주도립 미술관', 'https://api.cdn.visitjeju.net/photomng/imgpath/202508/14/4617b75d-2499-4829-9c7e-509e140ef2a4.webp'),
(253, '북촌돌하르방공원', '제주특별자치도 제주시 조천읍 북촌서1길 78', 33.5390196, 126.6891716, 'CULTURE', 1, '숲, 만남, 그리고 평화.', '숲, 만남, 그리고 평화. 제주의 자연과 문화 그리고 예술이 함께 어우러진 감성공간.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/17/29194b1f-3fa2-4714-88d0-2c6711970a81.webp'),
(254, '추자도등대', '제주특별자치도 제주시 추자면 영흥리 77-3 잡', 33.9552624, 126.2966728, 'TRAIL', 4, '추자 10경의 하나로 상추자도 전경이 조망되는 곳', '추자 10경의 하나로 상추자도 전경이 조망되는 곳', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/d46383be-0c6f-4d4c-b13f-2842c2fde69d.webp'),
(255, '동암사', '제주특별자치도 서귀포시 성산읍 일출로 284-10', 33.4617167, 126.9359293, 'HISTORY', 1, '제주에 위치한 불교 사찰로 불교 신앙과 수행이 이루어지는 종교 공간입니다.', '제주에 위치한 불교 사찰로 불교 신앙과 수행이 이루어지는 종교 공간입니다. 조용한 사찰 분위기 속에서 제주 지역의 불교 문화를 접할 수 있습니다. 잠시 머물며 차분하게 주변을 둘러보기 좋습니다.', 'https://mblogthumb-phinf.pstatic.net/MjAxNzAxMjlfMiAg/MDAxNDg1NjcwODc2MzM4.Fw7s4uqrtCVP6Yvj_xUin7pqxlDWRqZgFir4SfHE8xEg.QK88nT04XzUxgPzZ4L-L75solE4XfmpN39g8-lu_lCIg.JPEG.scpark1214/20170128_170818.JPG?type=w800'),
(256, '동홍교회', '제주특별자치도 서귀포시 동홍로109번길 48', 33.2595945, 126.5640992, 'HISTORY', 3, '서귀포 동홍 지역에 자리한 기독교 교회로 예배와 지역 공동체 활동이 이루어지는 곳입니다.', '서귀포 동홍 지역에 자리한 기독교 교회로 예배와 지역 공동체 활동이 이루어지는 곳입니다. 지역 주민들의 신앙생활과 교류를 위한 공간으로 이용됩니다. 제주 지역의 기독교 문화를 살펴볼 수 있는 종교 시설입니다.', 'https://image.kmib.co.kr/online_image/2021/0810/2021080920420998805_1628509329_0924204189.jpg'),
(257, '다이나믹메이즈', '제주특별자치도 서귀포시 표선면 성읍리 2381 대', 33.3991343, 126.7852649, 'THEME', 1, '다이나믹메이즈는 날씨에 구애받지 않고 즐기는 실내 액티비티다.', '다이나믹메이즈는 날씨에 구애받지 않고 즐기는 실내 액티비티다. 요즘 인기인 ‘방탈출’과 비슷한 콘셉트로 미로를 빠져나오기 위해 여러 가지 미션을 수행해야 한다. 가족이나 친구, 연인과 한 팀이 되어 서로 머리를 맞대 문제를 풀고 장애물을 뛰어넘으며 탈출구를 향해 달리는 색다른 재미를 느낄 수 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202410/17/aafd977f-9e35-4dec-8de6-83b23a34e3ef.webp'),
(258, '탐라신화공원', '제주특별자치도 제주시 조천읍 선흘리 1818-7 잡', 33.4637422, 126.7094860, 'NATURE', 1, '제주에 전해 내려오는 신화와 이야기를 주제로 조성된 공간입니다.', '제주에 전해 내려오는 신화와 이야기를 주제로 조성된 공간입니다. 제주 고유의 설화와 문화적 상징을 보다 친근하게 접할 수 있습니다. 지역의 신화와 전통문화에 관심 있는 방문객이 둘러보기 좋은 곳입니다.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSuDjpjSpO1gEOkH23GIJhF67kXHmjqpDZSDN47qeNdvA&s'),
(259, '대비공원', '제주특별자치도 제주시 구좌읍 송당리 산 274임', 33.4319298, 126.7481621, 'NATURE', 1, '지역 주민과 방문객들이 가볍게 산책하고 휴식을 취할 수 있도록 조성된 공원입니다.', '지역 주민과 방문객들이 가볍게 산책하고 휴식을 취할 수 있도록 조성된 공원입니다. 녹지와 휴식 공간을 중심으로 편안하게 머물기 좋습니다. 주변 일정 중 잠시 쉬어가기 좋은 생활형 공원입니다.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQEYc35bc25FIHLVdSD6rWegAp9x52nNAIn1gfw5xzi-WGM47hqE5pHAJMU&s=10'),
(260, '신사수포구', '제주특별자치도 제주시 도두이동 836-7잡', 33.5097929, 126.4789798, 'NATURE', 4, '제주 해안에 자리한 작은 포구로 어선과 바다가 어우러진 제주다운 풍경을 볼 수 있습니다.', '제주 해안에 자리한 작은 포구로 어선과 바다가 어우러진 제주다운 풍경을 볼 수 있습니다. 관광지화된 해변과는 다른 소박한 어촌 분위기를 느낄 수 있습니다. 바닷가 산책이나 사진 촬영을 즐기기 좋은 장소입니다.', 'https://blog.kakaocdn.net/dn/bBxUtl/btsJe5XLrj9/F321p9Fp08jdscwLTjj5U0/img.jpg'),
(261, '아르떼뮤지엄 제주', '제주특별자치도 제주시 애월읍 어림비로 478', 33.3967005, 126.3450106, 'CULTURE', 2, '아르떼뮤지엄은 몰입형 미디어아트를 체험할 수 있는 장소다.', '아르떼뮤지엄은 몰입형 미디어아트를 체험할 수 있는 장소다. 스피커 제조공장이었던 건물을 리모델링하여 면적 1,400평, 높이 10m의 벽을 스크린으로, 최신 기술을 활용한 미디어아트의 세계가 펼쳐진다.빛과 소리가 만드는 영원한 자연을 테마로 해변, 파도, 폭포, 꽃, 달, 숲 등의 작품을 관람할 수 있다. 시각적 강렬함, 감각적 사운드, 품격 있는 향기와 함께 완벽한 몰입 경험을 제공한다. 모든 감각의 긴장을 잠시 내려놓고 아르떼뮤지엄 제주가 선사하는 영원한 자연의 공간 속으로 향해보자.', 'https://cdn.imweb.me/thumbnail/20251218/f7a51c10466ad.png'),
(262, '한림바다체험마을', '제주특별자치도 제주시 한림읍 한림해안로 200', 33.4197436, 126.2627828, 'EXPERIENCE', 2, '대나무 낚시를 이용한 제주 전통 테우낚시체험과 조간대체험을 할 수 있는 아이들을 위한 최적의 바다체험 교육.', '대나무 낚시를 이용한 제주 전통 테우낚시체험과 조간대체험을 할 수 있는 아이들을 위한 최적의 바다체험 교육.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201808/20/23b8b3bd-b129-49a9-915a-25c04bc3cc31.webp'),
(263, '기후변화홍보관', '제주특별자치도 서귀포시 안덕면 사계남로216번길 24-34', 33.2333299, 126.3130961, 'NATURE', 2, '기후변화와 환경 문제에 관한 정보를 알기 쉽게 소개하는 전시·교육 공간입니다.', '기후변화와 환경 문제에 관한 정보를 알기 쉽게 소개하는 전시·교육 공간입니다. 기후변화의 원인과 영향, 환경 보호의 필요성 등을 다양한 자료를 통해 살펴볼 수 있습니다. 어린이와 가족 단위의 환경 교육 장소로 활용하기 좋습니다.', 'https://cdn.jejusori.net/news/photo/201210/121681_135631_440.jpg'),
(264, '제주힐링명상센터', '제주특별자치도 제주시 애월읍 어음13길 196', 33.3955055, 126.3612400, 'THEME', 2, '제주시 애월읍 중산간 400고지에 자리한 제주힐링명상센터는 드넓은 들판, 그리고 한림해변과 비양도를 품은 바다가 한눈에 내려다보이는 전경을 통…', '제주시 애월읍 중산간 400고지에 자리한 제주힐링명상센터는 드넓은 들판, 그리고 한림해변과 비양도를 품은 바다가 한눈에 내려다보이는 전경을 통해 첫인사를 전해온다. 제주힐링명상센터는 한국고유의 호흡법과 명상, 氣문화 전파를 통해 건강하고 행복한 삶을 추구하는 공간으로, 바쁜 일상을 살아가는 현대인들의 몸과 마음에 쌓인 스트레스를 해소하고 온전한 휴식과 힐링을 선사한다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/098a0440-10ad-4cce-99b4-133e3905f979.webp'),
(265, '메리아일랜드', '제주특별자치도 제주시 한림읍 금능길 80', 33.3888545, 126.2314909, 'COMMERCIAL', 2, '제주향기를 머금은 아담한 소품 가게', '제주향기를 머금은 아담한 소품 가게', 'https://api.cdn.visitjeju.net/photomng/imgpath/202306/13/06a98384-4e3f-40b6-870c-96879340958b.webp'),
(266, '대정향교', '제주특별자치도 서귀포시 안덕면 향교로 165-17', 33.2394202, 126.2884768, 'HISTORY', 2, '서귀포시 안덕면 사계리에 있는 조선시대의 향교', '서귀포시 안덕면 사계리에 있는 조선시대의 향교', 'https://api.cdn.visitjeju.net/photomng/imgpath/202112/20/255bbc57-b713-4b54-9143-4ed92e9d7961.webp'),
(267, '수산봉', '제주특별자치도 제주시 애월읍 수산리 산 1-1임', 33.4730139, 126.3845556, 'NATURE', 2, '애월읍 수산리에 있는 수산봉은 소화산체이다.', '애월읍 수산리에 있는 수산봉은 소화산체이다. 동그란 형태의 분화구를 지니고 정상에 물이 고인 작은 연못이 있어 물메오름 혹은 정상에 봉수가 있어 수산봉이라고 불린다. 제주 올레 16코스에 포함되어 올레길을 따라가다 보면 수산봉 근처에 있는 수산저수지와 곰솔을 지나 수산봉 정상에 오르게 된다. 수산봉은 계단과 길이 잘 다듬어져 있어 어린 자녀와 함께 오르는 가족단위 여행객도 많다. 수산봉의 산행시간은 약 20분 정도 소요되며 주변을 둘러보며 올라갈 계획이라면 40분 정도 계획을 하고 가면 된다.', 'https://tong.visitkorea.or.kr/cms/resource/26/3527226_image2_1.jpg'),
(268, '도두봉', '제주특별자치도 제주시 도두일동 산 2임', 33.5079861, 126.4683500, 'NATURE', 4, '도두봉은 제주공항 북쪽 도두동 해안가에 있는 오름으로 경사가 완만하며 오르기 쉬운편에 속한다.', '도두봉은 제주공항 북쪽 도두동 해안가에 있는 오름으로 경사가 완만하며 오르기 쉬운편에 속한다. 남사면은 풀밭을 이루면서 듬성듬성 해송이 있고, 북사면은 삼나무와 낙엽수 등이 어우러져 숲을 이룬다. 봉우리는 두 개이며, 동쪽 봉우리가 높다. 주변에는 국수나무, 팥배나무, 덜꿩나무, 예덕나무 외에 여러 종류의 새우란, 바람꽃 등의 자생식물이 자라고 있다. 오르는 길과 정상에서 제주 국제공항에 비행기가 뜨고 내리는 것도 볼 수 있는데 바다 전망과 어우러져 장관을 이룬다. 규모가 작은 오름이지만, 멋진 풍경을 보여준다.', 'https://cdn.visitkorea.or.kr/img/call?cmd=VIEW&id=0f8f9451-9d50-4860-996c-43bdabadee72'),
(269, '동광해바른작은도서관', '제주특별자치도 서귀포시 안덕면 동광리 1590잡', 33.3049839, 126.3382545, 'CULTURE', 2, '서귀포시 안덕면 동광리에 위치한 마을 단위의 작은도서관입니다.', '서귀포시 안덕면 동광리에 위치한 마을 단위의 작은도서관입니다.
대형 공공도서관보다 작은 규모로 지역 주민들이 가까운 곳에서 책과 문화 프로그램을 접할 수 있는 공간입니다.
관광시설보다는 동광리 주민을 위한 생활밀착형 문화·교육시설입니다.', 'https://cdn.seogwipo.co.kr/news/photo/201010/63956_39462_751.jpg'),
(270, '조은승마장', '제주특별자치도 서귀포시 안덕면 동광로 265-14', 33.3182965, 126.3451270, 'EXPERIENCE', 2, '전통이 깊은 승마장', '전통이 깊은 승마장', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/960ce628-6127-4983-aa84-bac4d97fbd89.webp'),
(271, '팜스테이낙천의자공원', '제주특별자치도 제주시 한경면 낙수로 97', 33.3280221, 126.2268878, 'NATURE', 2, '천 개의 의자가 있는 낙천아홉굿 의자공원은 올레 13코스를 지나는 곳에 위치하고있어 사람들의 발길이 머무는 곳이다.', '천 개의 의자가 있는 낙천아홉굿 의자공원은 올레 13코스를 지나는 곳에 위치하고있어 사람들의 발길이 머무는 곳이다. 엘리베이터가 있는 전망대까지 오픈을 하여 시원한 풍경을 감상할 수 있게 되었다. 9개의 샘이 있어 아홉굿마을이라 불리는 낙천리의 의자공원을 소개한다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202110/19/8ee50143-f00c-4991-bfee-0c10a0d0f37e.webp'),
(272, '어영공원', '제주특별자치도 제주시 서해안로 451', 33.5182975, 126.4874973, 'NATURE', 4, '용담이호해안도로에 조성된 공원이자 쉼터', '용담이호해안도로에 조성된 공원이자 쉼터', 'https://api.cdn.visitjeju.net/photomng/imgpath/201812/19/9dc37ee4-cfd0-4f06-b344-664d79670147.webp'),
(273, '제주불빛정원', '제주특별자치도 제주시 애월읍 평화로 2346', 33.4219248, 126.4096169, 'THEME', 2, '제주불빛정원은 2017년 개장한 이래 제주관광공사에서 선정한 제주야간관광 10선에 선정되는 등 아름다운 제주도의 밤을 가족과 친구들과 보낼 수…', '제주불빛정원은 2017년 개장한 이래 제주관광공사에서 선정한 제주야간관광 10선에 선정되는 등 아름다운 제주도의 밤을 가족과 친구들과 보낼 수 있는 야간 축제 관광지로써 발전해 왔다. LED조명과 아름다운 조형물을 기획하고 설치하는 기술을 토대로 아름다운 추억과 감성을 느낄 수 있도록 끊임없이 연구하고 있다. 제주도의 야간관광을 활성화하여 제주도를 방문하는 관광객들에게 더욱 알찬 관광의 기회를 제공하고 지역사회에 기여하고 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202002/24/6eea78e0-ce91-410b-8bda-1945e5254fe4.webp'),
(274, '서귀포치유의숲', '제주특별자치도 서귀포시 산록남로 2271', 33.2919394, 126.5279042, 'NATURE', 3, '편백나무와 삼나무숲길을 걸으며 치유의 순간을 만나다.', '편백나무와 삼나무숲길을 걸으며 치유의 순간을 만나다. 
2019, 2020 정부 문화체육관광부가 지정한 ''열린관광지''에도 지정되어 있다!', 'https://api.cdn.visitjeju.net/photomng/imgpath/202508/20/d6c59631-c71a-4a66-8394-dea0147ea7b2.webp'),
(275, '에코힐글램핑장', '제주특별자치도 제주시 애월읍 광령평화8길 22', 33.4496707, 126.4408316, 'NATURE', 2, '에코힐글램핑은 제주특별자치도 제주시 애월읍에 위치한 글램핑장으로, 한라산과 제주시 전경을 바라보며 자연 속에서 여유로운 휴식을 즐길 수 있는…', '에코힐글램핑은 제주특별자치도 제주시 애월읍에 위치한 글램핑장으로, 한라산과 제주시 전경을 바라보며 자연 속에서 여유로운 휴식을 즐길 수 있는 곳이다. 도심과 가까우면서도 한적한 분위기를 갖추고 있어 가족, 연인, 친구와 함께 머물기 좋다. 글램핑장은 쾌적한 시설과 넓은 주차장을 갖추고 있어 편리하게 이용할 수 있으며, 계절에 따라 다양한 즐길 거리도 마련되어 있다. 오월부터 구월까지는 수영장을 운영해 시원한 물놀이를 즐길 수 있으며, 저녁에는 캠프파이어를 통해 제주 자연 속에서 낭만적인 시간을 보낼 수 있다. 한라산과 주변 풍경이 어우러진 자연 속에서 편안한 휴식을 즐길 수 있는 곳으로, 제주 여행의 특별한 추억을 만들기에 좋은 글램핑장이다.', 'https://tong.visitkorea.or.kr/cms/resource/66/4095966_image2_1.jpg'),
(276, '제주컨트리클럽', '제주특별자치도 제주시 영평동 2258-29 체', 33.4275854, 126.5762010, 'LEISURE', 4, '제주시 지역에 위치한 골프장으로 제주 자연 속에서 라운드를 즐길 수 있는 레저 공간입니다.', '제주시 지역에 위치한 골프장으로 제주 자연 속에서 라운드를 즐길 수 있는 레저 공간입니다. 넓은 코스와 주변 녹지 풍경을 함께 경험할 수 있습니다. 제주에서 골프와 휴양을 함께 즐기려는 방문객에게 적합한 장소입니다.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSP8-OzZY3hZ79wdCk4UtfQDVY0GcObrFIpjhcZnw9NXg&s=10'),
(277, '한라산국립공원', '제주특별자치도 제주시 조천읍 516로 1865', 33.3849696, 126.6191542, 'NATURE', 1, '성판악은 한라산 국립공원의 성판악 등산로 주변에 위치하는 오름으로 한라산 동쪽 산록에서 가장 규모가 큰 단성화산이다.', '성판악은 한라산 국립공원의 성판악 등산로 주변에 위치하는 오름으로 한라산 동쪽 산록에서 가장 규모가 큰 단성화산이다. 단성화산은 일회의 분화 활동을 통해 형성되는 소형 화산체로서 제주에서는 오름으로 불린다. 성판악이라는 명칭은 산 중턱에 암벽이 널 모양으로 둘려 있는 것이 성벽처럼 보여 성널오름 또는 한자어로 성판악이라고 하게 됐다. 성판악은 전체가 삼림으로 덮여있으며 주변으로 성널계곡 등 크고 깊은 계곡이 발달해 있다. 제주시와 서귀포시를 잇는 5·16 도로의 중간 지점 가장 높은 곳에 성판악 휴게소가 있는데, 이곳은 한라산으로 오르는 등산로 중이 하나로 성판악이 시작되는 곳이다. 한라산 동쪽 코스인 성판악탐방로는 관음사탐방로와 더불어 한라산 정상인 백록담을 오를 수 있는 탐방로이며 한라산탐방로 중 가장 긴 코스이다. 정상까지 대체로 완만한 경사를 이루지만 왕복 9시간 정도 소요되기 때문에 체력 안배에 신경을 써야 한다. 성판악탐방로는 한라산탐방로 예약시스템에서 사전예약을 해야 탐방이 가능하다.', 'https://tong.visitkorea.or.kr/cms/resource/04/3077604_image2_1.jpg'),
(278, '부영컨트리클럽', '제주특별자치도 서귀포시 남원읍 수망리 1117-2 목', 33.3659208, 126.7059874, 'LEISURE', 3, '서귀포시 남원읍에 위치한 제주 지역의 골프장입니다.', '서귀포시 남원읍에 위치한 제주 지역의 골프장입니다.
원앙·사랑·우정 코스 등 여러 골프 코스를 갖추고 제주 자연 속에서 라운딩을 즐길 수 있는 시설입니다.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQqvj_GWsXwYMlkM7kKH7ZfeDaFjT2QW8dJ2mD_QPHzs2Pg0VIKoek9PWw&s=10'),
(279, '중문오프로드체험장', '제주특별자치도 서귀포시 상예로 349', 33.2758463, 126.3968639, 'EXPERIENCE', 3, '중문 숲속을 거닐며 즐기는 승마체험', '중문 숲속을 거닐며 즐기는 승마체험', 'https://api.cdn.visitjeju.net/photomng/imgpath/202306/20/6a03454d-84a8-4503-810c-bcf9ee04968c.webp'),
(280, '연화차', '제주특별자치도 제주시 조천읍 선교로 46', 33.4875769, 126.7147714, 'EXPERIENCE', 1, '차와 함께 조용한 휴식을 즐길 수 있는 제주식 티 공간입니다.', '차와 함께 조용한 휴식을 즐길 수 있는 제주식 티 공간입니다. 차분한 분위기 속에서 다양한 차를 맛보며 여유롭게 시간을 보내기 좋습니다. 여행 중 잠시 쉬어가며 제주 감성을 느끼기 좋은 곳입니다.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQYc2YCggHVLrv6jEzv_qEZ_-XD0AAgQe8bqGiLF62bxfh3PyJGivQaQBet&s=10'),
(281, '중문대포주상절리대', '제주특별자치도 서귀포시 이어도로 36-30', 33.2379940, 126.4260174, 'NATURE', 3, '자연의 신비가 주는 웅장함에 압도되다', '자연의 신비가 주는 웅장함에 압도되다', 'https://api.cdn.visitjeju.net/photomng/imgpath/202410/21/3d9d8a40-9986-4870-9818-dd98456c44e1.webp'),
(282, '김녕항수산문화센터', '제주특별자치도 제주시 구좌읍 김녕항1길 50-11', 33.5582014, 126.7404223, 'CULTURE', 1, '요트를 타고 푸른 제주 바다의 물살을 가르며 달리다', '요트를 타고 푸른 제주 바다의 물살을 가르며 달리다', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/0c0ca26a-95bd-49c8-96de-7ac8c2ddb2d2.webp'),
(283, '따라비오름', '제주특별자치도 서귀포시 표선면 가시리 산 62', 33.3891560, 126.7532500, 'NATURE', 1, '완만한 능선과 여러 굼부리가 이어지는 표선면 오름', '완만한 능선과 여러 굼부리가 이어지는 표선면 오름', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/01/2807b2be-5aa2-4e3e-bd91-23a92d2985a6.webp'),
(284, '한라산컨트리클럽', '제주특별자치도 제주시 선돌목동길 56-46', 33.4441298, 126.5458375, 'LEISURE', 4, '한라산 C.C에는 은하수에 닿을 만큼 높은 한라산의 푸른 기상과 600년 넘게 한결같이 제주를 지켜온 산천단 곰솔의 굳은 의지가 담겨 있다.', '한라산 C.C에는 은하수에 닿을 만큼 높은 한라산의 푸른 기상과 600년 넘게 한결같이 제주를 지켜온 산천단 곰솔의 굳은 의지가 담겨 있다. 600년 넘게 지켜온 곰솔의 푸르름과 곧은 기상이 살아있는 한라산 중턱 해발 400m 고지, 제주를 가장 잘 아는 제주 토박이의 한 사람으로서 아껴두고 싶고 또한 자랑하고 싶은 곳에 한라산 컨트리클럽을 지었다. 뒤로는 한라산의 절경이 든든하고 앞으로는 푸른 남해의 수평선이 시원하게 펼쳐진 이곳에 한겨울에도 기온과 바람 걱정이 없는 골프장을 만들기 위해 10여 년 연구와 노력을 아끼지 않았다. 하늘을 받치듯 곧게 뻗은 곰솔과 다정스레 모여 앉은 돌무지 하나까지 제주의 참모습을 그대로 살린 자연주의 골프클럽 한라산 컨트리클럽은 살아 숨 쉬는 대자연의 한가운데에 생동감 넘치는 그린을 더한 최고의 골프클럽임을 자부한다. 세계 100대 골프장으로 선정된 나인브릿지C.C의 설계 디자이너 데이비드 데일과 역시 세계 100대 골프장으로 선정된 핀크스 골프클럽의 건설사 부건 종합건설(주)가 만나 최고의 기술과 노하우로 탄생하였다.', 'https://tong.visitkorea.or.kr/cms/resource/50/1950650_image2_1.jpg'),
(285, '비체올린', '제주특별자치도 제주시 한경면 판조로 253-6', 33.3494639, 126.2184496, 'LEISURE', 2, '자연 위에 조성했다는 의미의 ‘햇빛에 올려 놓은’ 이란 뜻인 비체올린은 제주시 서쪽 중산간에 위치한 가족 놀이공원이다.', '자연 위에 조성했다는 의미의 ‘햇빛에 올려 놓은’ 이란 뜻인 비체올린은 제주시 서쪽 중산간에 위치한 가족 놀이공원이다. 카약 뿐만 아니라 전국 최초의 드리프트 전용 카트를 체험할 수 있는 ‘트라익 파크’ 뿐만 아니라 5월에서 7월 사이에는 능소화, 수국, 버베나로 대표되는 여름꽃&능소화 축제가 열리고 겨울에는 애기동백과 홍매화가 시선을 강탈한다. 소소한 재미가 있는 미로 공원 및 곶자왈 숲속 산책 등 여유로움과 액티비티를 동시에 즐길 수 있는 복합적인 테마공원이다.
비체올린의 또 다른 자랑인 공원은 1㎞에 이르는 넉넉한 능소화 정원을 자랑하며 초여름에는 능소화 축제와 함께 수국, 버베나 등 다양한 꽃들이 아름다운 풍경을 연출한다. 여름 꽃들이 제공하는 아름다움은 말로 표현하기 어려울 정도이다. 바다나 계곡이 아닌 제주의 자연에서 느낄 수 있는 힐링 체험은 동행자와 함께 정글을 걷다 강을 건넌 듯한 기분을 느낄 수 있으며 공원 산책은 더욱 특별한 경험을 선사한다. 항상 새로움을 추구하는 비체올린은 자주 변화를 주기 때문에 방문객들은 매년 이곳을 찾아 기대와 궁금증을 가지며 새로운 경험을 누릴 수 있다.

(출처 : 비짓제주)', 'https://api.cdn.visitjeju.net/photomng/imgpath/202410/11/d7bb30d2-cd31-4a37-bca5-fe5755b75b5a.webp'),
(286, '신라면세점제주점', '제주특별자치도 제주시 노연로 69', 33.4862606, 126.4875449, 'COMMERCIAL', 4, '럭셔리 브랜드와 제주 문화가 어우러진 면세쇼핑 1번지, 신라면세점 제주점', '럭셔리 브랜드와 제주 문화가 어우러진 면세쇼핑 1번지, 신라면세점 제주점', 'https://api.cdn.visitjeju.net/photomng/imgpath/202304/20/bf2c4ebd-73d2-4742-914a-fe54e6df0705.webp'),
(287, '신양섭지해수욕장', '제주특별자치도 제주시 조천읍', 33.5517018, 126.6487986, 'NATURE', 1, '나만 알고 싶은 프라이빗 해수욕장을 찾는다면 제주 동쪽 조천읍에 있는 신흥해수욕장을 추천한다.', '나만 알고 싶은 프라이빗 해수욕장을 찾는다면 제주 동쪽 조천읍에 있는 신흥해수욕장을 추천한다. 제주 올레길 19코스에 있으며 ‘민만 아는 작은 해변이지만 있을 건 다 있다. 돌벽으로 지어진 탈의실과 샤워 시설은 신축하여 시설이 모두 깨끗하다. 널리 알려지지 않은 곳이라 주로 숙소 사장님에게 추천받아 오는 관광객들만 찾아 성수기에도 북적이지 않는 해변이다. 주변에 주차하기도 편리하고 여름철에는 안전요원도 배치되어 안심하고 이용할 수 있다. 멀리 서우봉이 보이며 바로 옆에 카페가 있어 더욱 편리하다. 조용한 곳에서 물놀이 휴가를 즐기고 싶다면 방문해 보길 권한다.', 'https://tong.visitkorea.or.kr/cms/resource/79/4001879_image2_1.jpg'),
(288, '삼양감수탕', '제주특별자치도 제주시 감수북길 41', 33.5256675, 126.5839207, 'NATURE', 4, '제주 삼양 지역의 용천수를 활용한 전통적인 물 문화와 관련된 장소입니다.', '제주 삼양 지역의 용천수를 활용한 전통적인 물 문화와 관련된 장소입니다. 제주 사람들의 생활과 자연환경이 연결된 모습을 엿볼 수 있습니다. 삼양 해안 일대와 함께 둘러보며 지역의 옛 생활문화를 접하기 좋습니다.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRKhSRqCrX2WwHmTqa3vwKfIwlJC7Ipfnwuq-WprbfElg&s=10'),
(289, '행원환해장성', '제주특별자치도 제주시 구좌읍 행원리 80-5', 33.5581134, 126.8261478, 'HISTORY', 1, '아름다운 동쪽 해안길을 걸으며 역사를 되짚어보다', '아름다운 동쪽 해안길을 걸으며 역사를 되짚어보다', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/d7c81e3b-977d-4c95-bcf6-9f5c0bd19575.webp'),
(290, '서귀포매일올레시장', '제주특별자치도 서귀포시 중앙로62번길 18', 33.2501501, 126.5632316, 'COMMERCIAL', 3, '서귀포 올레시장은 서귀포시에서 가장 큰 시장이며 1960년대 초반 자연발생적으로 생긴 재래시장으로 60여 년 전통으로 서귀포 경제에 큰 밑받침…', '서귀포 올레시장은 서귀포시에서 가장 큰 시장이며 1960년대 초반 자연발생적으로 생긴 재래시장으로 60여 년 전통으로 서귀포 경제에 큰 밑받침이 되고 있는 시장이다. 2001년 120m를 시작으로 현재 총 620m에 달하는 아케이드상가를 설치하여 서귀포서민경제에 중추적인 역할을 담당하고 있다. 이곳 주차장은 1시간 무료주차시스템을 도입하여 고객에 최대한 편의를 제공하고 있으며, 시장에서 물건을 구입한 고객의 편의를 위해서 무료로 원하는 장소로 배달하는 택배시스템을 갖추고 있다. 또한 미래의 잠재고객인 청소년들을 위한 야외 공연장 및 분수대가 있는 공원을 갖추고 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202410/18/50513f94-f837-4521-a924-e8f77ea333ab.webp'),
(291, '번개과학체험관GAME', '제주특별자치도 서귀포시 토평공단로 78-27', 33.2895183, 126.5888282, 'LEISURE', 3, '서귀포시 토평동에 위치한 과학 원리를 놀이와 체험을 통해 접할 수 있도록 구성된 체험형 박물관입니다.', '서귀포시 토평동에 위치한 과학 원리를 놀이와 체험을 통해 접할 수 있도록 구성된 체험형 박물관입니다.
전기와 번개 등 과학적 현상을 활용한 전시와 체험 콘텐츠를 중심으로 한 실내 관광시설입니다. 어린이를 동반한 가족이나 교육 목적의 방문객이 이용하기 좋은 과학 체험공간입니다.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRQDCrpoqhh4T6-6_r72l0uA_GNFEIUMvj-iHlZJu-ChdAz2eE0sBxXaMs&s=10'),
(292, '법화사대웅전', '제주특별자치도 서귀포시 하원북로35번길 15-28', 33.2653367, 126.4576033, 'HISTORY', 3, '통일신라시대 장보고가 창건한 것으로 전해지는 천년고찰이자 제주 불교 성지인 법화사지의 금당 터 위에 복원된 중심 법당입니다', '통일신라시대 장보고가 창건한 것으로 전해지는 천년고찰이자 제주 불교 성지인 법화사지의 금당 터 위에 복원된 중심 법당입니다', 'https://api.cdn.visitjeju.net/photomng/imgpath/201908/23/81c8387b-fc20-4776-887e-781b33e67f05.webp'),
(293, '북수구광장', '제주특별자치도 제주시 일도일동 1231-1 공', 33.5144994, 126.5278897, 'FESTIVAL', 4, '제주시 일도일동 칠성로 일대에 자리한 제주 원도심의 공공광장입니다.', '제주시 일도일동 칠성로 일대에 자리한 제주 원도심의 공공광장입니다.
도심을 걷는 시민과 관광객이 잠시 머물거나 이동할 수 있는 개방형 도시 공간입니다.
독립적인 대형 관광지보다는 칠성로와 제주 원도심 관광 동선에 포함되는 소규모 광장입니다.', 'https://www.headlinejeju.co.kr/news/photo/202406/546419_437284_517.jpg'),
(294, '남제주강병대교회', '제주특별자치도 서귀포시 대정읍 상모리 3846종', 33.2267086, 126.2576949, 'TRAIL', 2, '우리나라에서 가장 오래된 군인 교회', '우리나라에서 가장 오래된 군인 교회', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/ee642f9e-b7a6-4a80-97c5-6b7c9e6d8014.webp'),
(295, '제주통일관', '제주특별자치도 제주시 삼성로 46', 33.5067130, 126.5307708, 'CULTURE', 4, '제주시 탐라자유회관 내에 소재해 있는 제주 통일관은 1993년에 개관되어 지상 2층, 지하 1층 건물로 건립되었다.', '제주시 탐라자유회관 내에 소재해 있는 제주 통일관은 1993년에 개관되어 지상 2층, 지하 1층 건물로 건립되었다. 남북 교류 협력 시대에 대비하여 오늘의 북한 실상을 올바로 이해시키고, 민족 동질성 회복을 위한 실증적인 ‘통일교육장’으로 활용하기 위하여 설치하였다. 남북 관계 개선뿐만 아니라 한반도의 역사를 다시 한번 볼 수 있는 곳이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201812/20/df6da46c-00be-4d57-a4d6-ba0a0fc56e0b.webp'),
(296, '재주901', '제주특별자치도 제주시 1100로 2977-10', 33.4529269, 126.4863521, 'EXPERIENCE', 4, '제주 901 운동힐링센터는 명상을 통해 몸과 마음에 휴식을 선물할 수 있는 공간이다.', '제주 901 운동힐링센터는 명상을 통해 몸과 마음에 휴식을 선물할 수 있는 공간이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202307/26/6db27e8c-d961-4237-911b-491d6d1282ac.webp'),
(297, '법화사', '제주특별자치도 서귀포시 하원북로35번길 15-28', 33.2650038, 126.4576715, 'HISTORY', 3, '법화사는 수정사와 함께 제주의 비보사찰(裨補寺刹)로써, 대한불교조계종 제23교구 본사 관음사의 말사이다.', '법화사는 수정사와 함께 제주의 비보사찰(裨補寺刹)로써, 대한불교조계종 제23교구 본사 관음사의 말사이다. 건립 시기에 대해서는 고려 시대, 길게는 통일신라 시대까지도 올라간다는 주장이 있다. 고려 후기 몽골의 제주 지배기에 법화사는 더 중시되었다. 
제주대학교 박물관 주도로 1992년부터 이루어진 발굴 조사에서 발굴된 기와에는 법화사가 원의지원 6년(1269년)에 처음 중창을 시작해 16년(1279년)에 중창을 마쳤다는 것을 확인할 수 있었다. 충혜왕 때 제주로 유배된 승려 혜일이 법화사를 들러 시를 지었으며 조선 초기까지 법화사에 배속된 노비가 280명이었을 정도로 큰 절이었으나 조선 후기 이후 법화사는 폐사되었다. 
법화사는 천년 사찰의 역사적 가치와 더불어 사찰 경내가 아름다워 제주 도민들에게서 입소문이 나면서 타지에서 온 관광객들도 사찰 내의 구품연지에 우아한 연꽃과 더불어 배롱나무의 아름다운 자태와 더불어 부석사 무량수전 양식의 구화루가 이루어 내는 풍경은 불자가 아니라도 절집의 아름다움에 동의한다니 제주에서 이색 체험지로 추천한다. 법화사는 제주특별자치도 기념물로 지정 보호되고 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/2ef3e208-ddb0-4042-b60c-de40d9790e4a.webp'),
(298, '조랑말체험공원(따라비승마장)', '제주특별자치도 서귀포시 표선면 가시리 산 41-3 임', 33.3835244, 126.7368318, 'HISTORY', 1, '제주의 말 문화를 쉽고 재밌게 이해하고 체험할 수 있는 조랑말체험공원은 조선시대 최고의 말을 사육했던 갑마장이 있었던 가시리 마을 그 자리에…', '제주의 말 문화를 쉽고 재밌게 이해하고 체험할 수 있는 조랑말체험공원은 조선시대 최고의 말을 사육했던 갑마장이 있었던 가시리 마을 그 자리에 600년 목축문화의 역사를 고스란히 간직하고 있다. 농림부가 지원하는 ‘신문화공간 조성사업’의 일환으로 조성된 조랑말 박물관에 마을회의 노력으로 따라비 승마장, 마음 카페, 아트숍, 체험장, 축제공간 등이 어우러진 복합 문화공간으로 확대 조성되었다. 마을에서 설립한 국내 최초의 리립 박물관이자, 마을의 역사와 문화를 주제로 한 문화공간으로 새로운 형식의 커뮤니티 비즈니스 모델로서도 큰 의미가 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202407/11/4e9bba51-e6d3-465c-8071-27c33bf778dc.webp'),
(299, '최영장군사당(제주특별자치도기념물제11호)', '제주특별자치도 제주시 추자면 대서리 368도', 33.9651393, 126.2954312, 'HISTORY', 4, '추자도 사람들이 최영 장군의 은덕을 기리면서 한 해의 풍어를 기원하는 장소', '추자도 사람들이 최영 장군의 은덕을 기리면서 한 해의 풍어를 기원하는 장소', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/ea6ce092-63a8-417e-943e-43ed542d01b9.webp'),
(300, '스타빌글램핑장', '제주특별자치도 서귀포시 안덕면 광평로 34-154', 33.3388060, 126.3957080, 'EXPERIENCE', 2, '중산간에서 경험하는 다채로운 액티비티', '중산간에서 경험하는 다채로운 액티비티', 'https://api.cdn.visitjeju.net/photomng/imgpath/202211/14/e31beef5-eb48-4318-8551-2117aa642eda.webp');

INSERT INTO `POI` (`poi_id`, `poi_name`, `address`, `latitude`, `longitude`, `category_code`, `region_id`, `description`, `detail_description`, `image_url`) VALUES
(301, '바굼지오름', '제주특별자치도 제주시 애월읍 상귀리 332임', 33.4785722, 126.4128417, 'TRAIL', 2, '바굼지오름이라는 이름은 서귀포 안덕면의 단산과 제주시 애월읍 하귀리의 파군봉에 모두 사용되는 명칭입니다.', '바굼지오름이라는 이름은 서귀포 안덕면의 단산과 제주시 애월읍 하귀리의 파군봉에 모두 사용되는 명칭입니다.
안덕면의 바굼지오름은 세 봉우리가 거대한 박쥐가 날개를 편 듯한 독특한 암릉 경관을 가진 오름입니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/4f0001e0-8313-46db-a64e-4371694f703e.webp'),
(302, '제주애향묘지', '제주특별자치도 제주시 연동 2489-28묘', 33.4191719, 126.4956223, 'NATURE', 4, '제주시 노형동에 위치한 공설묘지입니다.', '제주시 노형동에 위치한 공설묘지입니다.
제주 출신 재외동포와 이북5도민 등을 위해 조성된 묘역이라는 특징이 있는 장소입니다.', 'https://kr.object.ncloudstorage.com/samgo/memorial-facility-images/cemetery/%EC%95%A0%ED%96%A5%EB%AC%98%EC%A7%80/1778300590315_0_MwbQ2_mGYW.webp'),
(303, '뽀로로앤타요테마파크 제주', '제주특별자치도 서귀포시 안덕면 병악로 269', 33.3004182, 126.3708220, 'THEME', 2, '서귀포시 안덕면에 위치한 뽀로로와 타요 캐릭터를 테마로 한 대형 키즈 테마파크입니다.', '서귀포시 안덕면에 위치한 뽀로로와 타요 캐릭터를 테마로 한 대형 키즈 테마파크입니다.
놀이기구와 캐릭터 공간, 디지털 체험 및 공연 등을 함께 즐길 수 있는 가족형 관광시설입니다.
유아와 어린이를 동반한 가족 관광객이 실내외에서 다양한 체험을 즐기기 좋은 장소입니다.', 'https://thumb.tidesquare.com/tour/public/product/PRV3000000026/PRD3000001055/origin/20220617085437032_5xeY9.jpg?quality=80&w=750&h=500'),
(304, '한라도서관', '제주특별자치도 제주시 오남로 221', 33.4762014, 126.5162735, 'CULTURE', 4, '제주시 오라이동에 위치한 제주특별자치도의 공공도서관입니다.', '제주시 오라이동에 위치한 제주특별자치도의 공공도서관입니다.
도서 열람과 학습, 독서 및 문화활동을 지원하는 지역의 대표적인 지식·문화시설입니다.
일반적인 관광지보다는 제주도민의 독서와 문화생활을 위한 공공시설 성격이 강한 곳입니다.', 'https://upload.wikimedia.org/wikipedia/commons/1/13/Halla_Library.jpeg?utm_source=ko.wikipedia.org&utm_campaign=index&utm_content=original'),
(305, '블루제주솝', '제주특별자치도 제주시 우정로15길 48', 33.4889641, 126.4328548, 'EXPERIENCE', 4, '제주에서 비누·화장품 관련 제품을 다루는 소규모 업체로 등록되어 있는 장소입니다.', '제주에서 비누·화장품 관련 제품을 다루는 소규모 업체로 등록되어 있는 장소입니다.
제주 관광명소라기보다는 비누 및 관련 제품을 제작·판매하는 공방·사업체 성격에 가까운 곳입니다.', 'https://mblogthumb-phinf.pstatic.net/MjAyMjExMDNfNjQg/MDAxNjY3NDA4MjQ2NTYw.x1eLYblqcOCMyen57ypeFVN8VnraMcOjUP3DiZ5vCnEg.3yVWJVsrjwo374PHBIMKnR6L_4MJf0HEE7fSec_mtGkg.JPEG.doong_i_200123/%EC%A0%9C%EC%A3%BC%EB%8F%84%EA%B8%B0%EB%85%90%ED%92%88_(4).jpg?type=w800'),
(306, '서귀포시모구리야영장', '제주특별자치도 서귀포시 성산읍 서성일로 260', 33.4064441, 126.8221569, 'EXPERIENCE', 1, '성산읍에 위치하고 있는 모구리야영장은 서귀포시에서 관리·운영하고 있는 캠핑장으로 산방산영지, 일출봉영지, 가족영지, 한라산영지로 나누어져 있다.', '성산읍에 위치하고 있는 모구리야영장은 서귀포시에서 관리·운영하고 있는 캠핑장으로 산방산영지, 일출봉영지, 가족영지, 한라산영지로 나누어져 있다. 야영장에 도착하여 제일 먼저 보이는 것은 손수레인데 캠핑 장비와 물건을 자리로 이동할 때 손수레를 이용할 수 있고, 관리실 입구에 재활용품 분리수거와 일반 쓰레기장이 있으며 음식물 쓰레기는 T-money 교통카드를 이용해 버리면 된다. 주차장, 운동장, 놀이터, 체력단련장, 화장실, 취사장, 샤워장, 산책로 등이 있다. 모구리야영장의 장점은 사이트 옆마다 배전함이 있어 전기를 편리하게 사용할 수 있다. 또한 무료 와이파이가 가능하며 이곳의 물은 지하수여서 그냥 먹어도 좋다고 하고 화장실도 깨끗하고 온수가 나오는 샤워장이 갖춰져 있는 아주 저렴한 야영장이어서 이용객들의 만족도가 아주 높다.
봄에는 벚꽃이 피고, 겨울에는 동백꽃이 피어 더욱 아름다운 캠핑장이 되며, 아이들과 함께 온 가족들은 부모가 텐트를 치는 동안 아이들이 놀이터에서 신나게 뛰어노는 시간을 보낼 수도 있다. 또 하나의 재미는 야영장에서 조금만 올라가면 모구리오름을 볼 수 있다는 것이다. 모구리오름은 바로 옆에 알과 비슷한 형태의 작은 오름이 있어서 마치 어미 오름이 품고 있는 모습과 같다고 한다. 그래서 한자 어미 모자를 따서 모구리오름이라 불리고 있다. 왕복 30분 정도의 아이들도 걸을 수 있는 쉬운 산책로이다. 날씨가 좋으면 오름 정상에서는 다랑쉬오름, 용눈이오름까지 보인다. 모구리오름 탐방로를 따라가다 보면 편백나무숲에서 싱그런 향기를 맡으며 힐링하는 시간을 즐겨 볼 수 있다. 관광지 성읍민속마을 바로 위쪽에 있고 백양이오름, 다랑쉬 오름이 있어 이곳에서 야영하면서 동쪽으로 여행하면 좋다.', 'https://tong.visitkorea.or.kr/cms/resource/50/3031150_image2_1.jpg'),
(307, '펀테마파크', '제주특별자치도 제주시 조천읍 선흘리 2019-3 원', 33.4791965, 126.7009773, 'THEME', 1, '모션인식 게임과 로봇하키, 튜브썰매, 사격 등 다양한 놀이를 체험하도록 구성된 테마시설입니다.', '모션인식 게임과 로봇하키, 튜브썰매, 사격 등 다양한 놀이를 체험하도록 구성된 테마시설입니다.
숲속바이크 등 야외 레저 프로그램과 결합된 체험형 관광시설로 소개된 곳입니다.', 'https://mblogthumb-phinf.pstatic.net/20140415_18/jangbugon_1397528525863SyfJF_JPEG/%C6%DD_%C5%D7%B8%B6%C6%C4%C5%A91.jpg?type=w420'),
(308, '제주시생활체육공원', '제주특별자치도 제주시 와흘전1길 32', 33.4722728, 126.6365949, 'LEISURE', 4, '제주시 회천동에 조성된 시민 대상 공공 생활체육시설입니다.', '제주시 회천동에 조성된 시민 대상 공공 생활체육시설입니다.
인조잔디 축구장과 테니스장 등을 중심으로 생활체육 활동을 할 수 있도록 조성된 공간입니다. 최근에는 회천파크골프장 관련 행사도 운영되는 등 관광지보다는 주민 체육시설 성격이 강한 곳입니다.', 'https://cdn.parkgolftoday.kr/news/photo/202601/167_305_3451.jpg'),
(309, '서우봉 산책로', '제주특별자치도 제주시 조천읍 함덕리 169-3임', 33.5458417, 126.6775861, 'LEISURE', 1, '푸른 바다와 예쁜 유채꽃밭이 어우러진 멋진 풍경이 있는 곳', '푸른 바다와 예쁜 유채꽃밭이 어우러진 멋진 풍경이 있는 곳', 'https://api.cdn.visitjeju.net/photomng/imgpath/201807/09/bccbe406-82e1-4858-b5d5-05743df44d9c.webp'),
(310, '어나더 우드 스토어', '제주특별자치도 제주시 조천읍 함덕로 32', 33.5420716, 126.6719419, 'EXPERIENCE', 1, '우드카빙 클래스도 즐기고 소품도 구매할 수 있는 곳', '우드카빙 클래스도 즐기고 소품도 구매할 수 있는 곳', 'https://api.cdn.visitjeju.net/photomng/imgpath/202306/13/6d8d4c46-185e-4c99-ab67-98ab5ca76d7a.webp'),
(311, '선덕사범종각', '제주특별자치도 서귀포시 516로771번길 64', 33.3201683, 126.5940379, 'HISTORY', 3, '서귀포시의 선덕사 경내에 조성된 범종을 보관하고 타종하는 전각입니다.', '서귀포시의 선덕사 경내에 조성된 범종을 보관하고 타종하는 전각입니다.
선덕사의 전통 목조건축과 불교문화 공간을 구성하는 여러 전각 중 하나입니다.
독립적인 관광지라기보다는 선덕사 사찰 관람 과정에서 함께 볼 수 있는 종교시설입니다.', 'https://t1.daumcdn.net/brunch/service/user/7EWq/image/d5iiqpisLY-Dsjtp7C9rzQ5A270'),
(312, '제주별빛누리공원', '제주특별자치도 제주시 오등동 10-34 대', 33.4444634, 126.5484824, 'NATURE', 4, '제주별빛누리공원은 천체탐구와 천문학습의 장으로 활용되고 있는 최첨단천문우주 과학시설이다.', '제주별빛누리공원은 천체탐구와 천문학습의 장으로 활용되고 있는 최첨단천문우주 과학시설이다. 21세기의 주역인 청소년들에게 무한한 꿈과 희망을 심어줄 과학문화 공간이다. 내부에는 삼차원 입체영상을 모션시뮬레이터에 탑승하여 현실감 있게 관람할 수 있는 4D영상관, 반구모양의 돔 스크린으로 우주에 대한 영상물과 사계절 별자리를 감상할 수 있는 천체투영실, 태양계 전시물, 행성 체중계, 디지털 망원경, 우주쓰레기 제거 게임, 포토존 등 다양한 볼거리와 체험이 있는 전시실 등이 있다. 또한, 구름 없이 맑은 날, 야간에만 운영하는 관측실은 주관측실과 보조관측실로 나뉘어 있다. 주관측실에서는 600㎜ 리치크리티앙 반사망원경을 통하여 희미한 천체를 더 밝게 접할 수 있으며, 보조관측실에서는 천체 망원경을 이용하여 다양한 천체를 관측할 수 있다. 이 외에 야외광장에는 태양계 광장과 해시계가 조성되어 있어 관람객들이 다양한 체험을 할 수 있는 공간으로 만들어졌다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202606/22/4afa9b49-0577-4188-9072-4afeb94fb2f5.jpeg'),
(313, '제동목장', '제주특별자치도 제주시 조천읍 교래7길 218', 33.4198975, 126.6964214, 'TRAIL', 1, '제동목장은 한진그룹에서 운영하는 제주도 목장으로 한국마사회에서 운영하는 렛츠런팜 목장 인근에 자리 잡고 있다.', '제동목장은 한진그룹에서 운영하는 제주도 목장으로 한국마사회에서 운영하는 렛츠런팜 목장 인근에 자리 잡고 있다. 제동목장은 사유지이기 때문에 목장 출입은 불가능 하나, 최근 제동목장 진입도로가 제주도 결혼사진 촬영 명소로 널리 알려지면서 관광객들이 많이 찾는 인생사진 명당이 됐다. 제동목장 입구에는 거대한 삼나무가 도로 양쪽으로 빽빽하게 있어 드라이브 코스로 제격이고, 이국적인 풍경을 연출한다. 특히, 비 오는 날에도 이곳만의 특별한 분위기에서 기억에 남는 사진을 찍을 수 있다. 제동목장 입구는 주차 공간이 없기 때문에 삼다수숲길 공영주차장에 주차하고 걸어서 이동하는 것을 권장한다.', 'https://tong.visitkorea.or.kr/cms/resource/70/3056070_image2_1.jpg'),
(314, '서프로와', '제주특별자치도 제주시 테우해안로 132', 33.4977582, 126.4479768, 'LEISURE', 4, '제주시 해안가에서 서핑 교육과 체험을 제공하는 서핑 전문 시설입니다.', '제주시 해안가에서 서핑 교육과 체험을 제공하는 서핑 전문 시설입니다.
초보자도 제주 바다에서 서핑을 배우고 즐길 수 있는 해양레저형 장소입니다.
관람형 관광지보다는 직접 활동에 참여하는 스포츠·체험시설 성격이 강한 곳입니다.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcQQ5oW8fjwXdcpozLX2-oGS4YsGB-RBUUDwEM-itc-X2g&s'),
(315, '제주도서관', '제주특별자치도 제주시 연삼로 489', 33.5006253, 126.5412805, 'EXPERIENCE', 4, '통일에 대한 다양한 정보와 유물 등이 있는 전시관.', '통일에 대한 다양한 정보와 유물 등이 있는 전시관.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201812/20/df6da46c-00be-4d57-a4d6-ba0a0fc56e0b.webp'),
(316, '모슬포교회', '제주특별자치도 서귀포시 대정읍 하모이삼로15번길 25', 33.2243229, 126.2484749, 'HISTORY', 2, '서귀포시 대정읍 하모리에 위치한 항', '서귀포시 대정읍 하모리에 위치한 항', 'https://api.cdn.visitjeju.net/photomng/imgpath/201908/06/866edac6-7704-4b8e-a131-62b0c125d78a.webp'),
(317, '스누피가든', '제주특별자치도 제주시 구좌읍 금백조로 930', 33.4441034, 126.7783321, 'THEME', 1, '스누피가든은 개성적인 모습을 자랑하는 피넛츠 캐릭터들을 만나 그들과 상호관계를 통해 공감과 힐링의 메시지를 얻을 수 있는 특별한 장소이다.', '스누피가든은 개성적인 모습을 자랑하는 피넛츠 캐릭터들을 만나 그들과 상호관계를 통해 공감과 힐링의 메시지를 얻을 수 있는 특별한 장소이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202012/16/79a19069-d0c9-40f1-860b-b2fd53a84d36.webp'),
(318, '쇠소깍관광지', '제주특별자치도 서귀포시 하효동 1459천', 33.2583992, 126.6238831, 'TRAIL', 3, '쇠소깍은 한라산에서 흘러 온 물줄기가 제주도 남쪽으로 흐르는 효돈천의 끝자락에 위치하고 있다.', '쇠소깍은 한라산에서 흘러 온 물줄기가 제주도 남쪽으로 흐르는 효돈천의 끝자락에 위치하고 있다. 효돈천의 담수와 해수가 만나 생긴 깊은 웅덩이가 바로 쇠소깍이다. ''쇠소''는 ''소가 누워 있는 모습의 연못''을, ''깍''은 ''마지막 끝''을 의미한다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202410/16/a8784094-08b6-4e9e-acf2-d86ab445dda5.webp'),
(319, '캔디원', '제주특별자치도 제주시 조천읍 선교로 384', 33.4712945, 126.7077518, 'EXPERIENCE', 1, '국내 최대 수제 캔디 브랜드로 꼽히는 캔디원은 사탕이 생겨난 유래와 종류, 제작 과정 등을 알아보고 직접 만들어 보는 색다른 체험을 하는 곳이…', '국내 최대 수제 캔디 브랜드로 꼽히는 캔디원은 사탕이 생겨난 유래와 종류, 제작 과정 등을 알아보고 직접 만들어 보는 색다른 체험을 하는 곳이다. 물론 제품 구입도 가능하다. 사탕을 좋아하는 사람에게 캔디원은 참새 방앗간이나 다름없다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202002/24/4c9c7117-f23f-45ca-baad-eb25af7578f4.webp'),
(320, '선운정사', '제주특별자치도 제주시 애월읍 구몰동길 65', 33.4293394, 126.3072863, 'HISTORY', 2, '제주의 정겨운 마을과 운치 있는 농촌 길을 걷다 보면 아름다운 모습을 한 선운정사를 마주할 수 있다.', '제주의 정겨운 마을과 운치 있는 농촌 길을 걷다 보면 아름다운 모습을 한 선운정사를 마주할 수 있다. 이 사찰은 제주올레 15코스에 포함된 사찰이다. 불교문화의 전승뿐만 아니라 제주의 문화를 함께 보존하기 위해 노력하는 공간으로, 설문대할망과 오백장군 전각, 소원을 이루어주는 소원석 등 다양한 조형물을 볼 수 있다. 무엇보다 유명한 것은 바로 야경이다. 절터를 은은하게 수놓는 연꽃등과 멋진 야경을 무료로 즐길 수 있어 인기다. 해가 떨어지는 7시쯤부터 경내에 불이 하나 둘 들어오기 시작한다. 수백 개의 LED 연꽃등과 탑, 전각 등을 밝히는 조명이 경내를 채우는 차분한 경전 소리와 어우러진다. 또한 사찰 내에 제주특별자치도 문화유산자료로 지정된 ‘선운정사 석조약사여래좌상’이 있다. 선운정사 석조여래좌상은 조선시대 이래 유행한 약기인의 약사불상의 도상을 정확하게 보여주고 있으며, 통일신라시대부터 조선시대까지 시대의 복합상을 갖춘 불상이다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/04/8f4809b8-bd20-41b8-850a-2711c9e8aa68.webp'),
(321, '앵무새체험농장', '제주특별자치도 제주시 미리내길 92', 33.4575937, 126.4792535, 'EXPERIENCE', 4, '다양한 앵무새를 가까이에서 관찰하고 교감할 수 있는 동물 체험형 공간입니다.', '다양한 앵무새를 가까이에서 관찰하고 교감할 수 있는 동물 체험형 공간입니다.
앵무새 관찰과 먹이주기 등 어린이나 가족 단위 방문객을 위한 체험이 중심인 장소입니다.
자연경관을 감상하는 관광지보다는 동물과 직접 교감하는 체험 관광지 성격이 강한 곳입니다.', 'https://lh3.googleusercontent.com/gps-cs-s/ANWiy9T1CKXfbtvbnKJ_HBz4BOGpus_bHt9DXX7wllk9EluV3TXwWexF7zXIwTyX9sQ5UVnDzMJXNohfCzJFpoGmG9Z13rXltfLBofIovtgk1cd7172mzMRNGYA_bf378pGyI60YBtcb=s1360-w1360-h1020-rw'),
(322, '양지공원', '제주특별자치도 제주시 516로 2810-31', 33.4401931, 126.5793437, 'NATURE', 4, '제주시 영평동에 위치한 제주특별자치도의 공설 장사시설입니다.', '제주시 영평동에 위치한 제주특별자치도의 공설 장사시설입니다.
화장시설과 추모의집인 봉안당, 제례실 및 유족 편의시설 등을 갖춘 공간입니다.
이름은 공원이지만 일반적인 휴식·관광 공원이 아니라 장례와 추모를 위한 시설입니다.', 'https://cdn.jejusori.net/news/photo/202508/439021_468866_462.jpeg'),
(323, '고근산', '제주특별자치도 서귀포시 서호동 1286-1임', 33.2667917, 126.5128722, 'TRAIL', 3, '고근산은 서귀포 신시가지를 감싸고 있는 기생화산으로 정상에 깊지 않은 원형 분화구를 가지고 있다.', '고근산은 서귀포 신시가지를 감싸고 있는 기생화산으로 정상에 깊지 않은 원형 분화구를 가지고 있다. 그리 높은 곳에 자리 잡고 있지는 않지만 탁 트인 곳에 있기 때문에 산봉우리에 서면 멀리는 마라도에서부터 지귀도까지 제주 바다와 서귀포시의 풍광을 한눈에 조망할 수 있다. 특히 밤바다와 함께 어우러진 서귀포 칠십리 야경을 감상하기 좋은 장소로 알려져 있으며 남동사면 중턱의 머흔저리라고 하는 곳은 예전에 국상을 당했을 때 곡을 하던 곡배단이 있고, 남서사면 숲 비탈에는 꿩사냥 하던 강생이(강아지)가 떨어져 죽었다고 전해지는 강생이궤(수직동굴)가 있다. 오름 중턱에 삼나무, 편백나무, 해송, 상수리나무, 밤나무 등이 조림되어 있고, 정상 부근에는 자연석과 어우러져 사스레피나무, 예덕나무, 산철쭉이 군락을 이루고 있으나 예전에는 드물게 해송이 있는 풀밭 오름이었다고 한다. 전설상의 거신 설문대 할망이 심심할 때면 한라산 정상부를 베개 삼고 고근산 굼부리에는 궁둥이를 얹고 앞바다 범섬에 다리를 걸치고 누워서 물장구를 쳤다는 재미있는 전설이 전해오고 있다. 최근 산책과 운동을 위하여 방문객이 늘면서 새로운 운동 휴양명소로 떠오르고 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/4f77f379-2304-44d1-b319-8cd86241cd93.webp'),
(324, '제주항일기념관', '제주특별자치도 제주시 조천읍 신북로 303', 33.5416203, 126.6426749, 'HISTORY', 1, '기미년 3·1독립만세운동은 제주지역까지 이어져 1919년 3월 21일부터 3월 24일까지 제주 제주시 조천읍 소재 미밋동산(현 만세동산)에서…', '기미년 3·1독립만세운동은 제주지역까지 이어져 1919년 3월 21일부터 3월 24일까지 제주 제주시 조천읍 소재 미밋동산(현 만세동산)에서 거행되었다. 이러한 선열들의 뜻을 기리기 위하여 조천만세동산 성역화 사업이 추진되었으며, 1997년 8월 15일 제주항일기념관을 개관하였다. 제주항일기념관은 조천만세운동을 비롯하여 제주에서 일어난 항일독립운동의 역사를 한눈에 볼 수 있는 곳이다. 전체 58,582㎡인 부지의 기념관 및 애국선열추모탑, 창열사(위패봉안실), 3·1독립운동기념탑 등 시설을 갖추고 만세공원을 조성하고 있으며, 선열들의 숭고한 희생정신과 자주독립정신을 계승·발전시키고 자라나는 후세들에게 올바른 역사의식과 애국정신을 함양하게 하기 위한 교육의 장 역할을 하고 있다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/8b7dc4da-409b-4205-9d11-38fc371da2fc.webp'),
(325, '서귀포축구공원', '제주특별자치도 서귀포시 효돈순환로 311-29', 33.2583497, 126.6105095, 'NATURE', 3, '서귀포시 신효동에 조성된 축구 중심의 공공 체육시설입니다.', '서귀포시 신효동에 조성된 축구 중심의 공공 체육시설입니다.
인조잔디 축구장과 관람석, 야간 조명시설 등을 갖추고 있는 스포츠 공간입니다.
관광지라기보다는 축구 경기·훈련과 생활체육을 목적으로 이용하는 시설입니다. PSF', 'https://mblogthumb-phinf.pstatic.net/MjAxODAyMjNfMjgz/MDAxNTE5MzY5NzMyNjgx.nlWQnYCeUsj8tf14kOV59y2vRQtYHc6Bpys5SmkxbgYg.b74Xy6_Ata-Aw0GEfKxigmBUyOfhpinbblyztH4N8iwg.JPEG.bdh0796/IMG_6061.jpg?type=w800'),
(326, '사려니숲길 붉은오름 입구', '제주특별자치도 서귀포시 표선면 가시리 산 158임', 33.3998583, 126.6795389, 'NATURE', 1, '오름 전체가 붉은송이로 형성되어 있는 곳', '오름 전체가 붉은송이로 형성되어 있는 곳', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/7edfaee5-46b6-47b3-b311-ede7a5ab2181.webp'),
(327, '효명사', '제주특별자치도 서귀포시 남원읍 516로 815-41', 33.3232974, 126.5941584, 'HISTORY', 3, '효명사는 서귀포시 남원읍에 위치한 울창한 숲 속에 아담한 집처럼 보이는 소박한 법당이다.', '효명사는 서귀포시 남원읍에 위치한 울창한 숲 속에 아담한 집처럼 보이는 소박한 법당이다. 산신각을 통과하면 보이는 효명사는 여느 절과 달리 조그마한 건물 서너 채만 있어서 생경한 느낌을 준다. 법당 입구에서 극락, 천국, 이끼문이라고 적힌 이정표를 발견할 수 있는데 모두 한 곳이다. 조금 내려가다 보면 돌계단이 보이고 이끼로 뒤덮인 자그마한 아치형의 돌문이 하나 보이는데 이것이 바로 사람들에게 효명사를 알리게 해 준 천국의 문이다. 이 문을 지나면 아직은 때묻지 않은 제주 자연 그대로의 계곡을 만날 수 있고 바로 근처에 별이폭포와 이끼폭포가 있으며 곳곳에 각자의 소원들을 빌며 쌓은 작은 돌탑들도 볼 수 있다. 근처의 산책로는 이끼들로 뒤덮혀있어 바닥과 돌들로 인해 미끄럽기 때문에 조심해서 걸어야 한다. 주변에 있는 선덕사, 선돌, 원앙폭포도 함께 서귀포 여행 일정에 포함시켜 방문하는 것을 추천한다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201808/17/b81d8629-9d1a-4191-9d4d-1dfb48a914c3.webp'),
(328, '한라산국립공원 영실탐방로', '제주특별자치도 제주시 한림읍 한림로 555', 33.4075104, 126.2566905, 'EXPERIENCE', 2, '한라산은 능히 은하수를 잡아당길 만큼 높은 산이라는 뜻을 가졌다.', '한라산은 능히 은하수를 잡아당길 만큼 높은 산이라는 뜻을 가졌다. 예부터 신선들이 산다고 해서 영주산(瀛州山)이라 불리기도 했고 금강산(金剛山), 지리산(智異山)과 더불어 우리나라 삼신산(三神山)의 하나로 여겨져 왔다. 또 다양한 식생(植生) 분포를 이루어 학술적 가치가 매우 높은 동·식물의 보고로써 1966년 10월 천연기념물로 지정, 보호되고 있다. 한편 신생대 4기의 젊은 화산섬인 제주도의 중심부에 위치한 한라산은 지금으로부터 2만 5천 년 전까지 화산 분화 활동을 하였으며, 한라산 주변에는 기생 화산인 오름이 분포되어 있어 특이한 경관을 창출하고 있다. 한라산이 품고 있는 비경으로는 눈 덮인 백록담, 왕관능의 위엄, 계곡 깊숙이 숨겨진 폭포들, 설문대 할머니와 오백장군의 전설이 깃든 영실기암 등이 있으며 1970년 3월에 국립공원으로 지정되었다. 한라산은 북태평양의 고도(孤島)에 솟아있는 지리적 요인과 해발고도에 따른 영향으로 온대에서 한대 기후대까지 식물의 수직분포를 보이고 있고, 다양한 종의 식물과 동물이 서식하는 생태계의 보고라고 할 수 있다.', 'https://tong.visitkorea.or.kr/cms/resource_photo/41/3460441_image2_1.jpg'),
(329, '제주아리온승마장', '제주특별자치도 서귀포시 안덕면 동광리 1391 체', 33.3109934, 126.3339971, 'LEISURE', 2, '어린이도 쉽게 탈 수 있는 승마체험', '어린이도 쉽게 탈 수 있는 승마체험', 'https://api.cdn.visitjeju.net/photomng/imgpath/202306/19/f8363c40-625f-45a3-b192-70e0c10a1269.webp'),
(330, '동광녹색농촌체험마을방문자센터', '제주특별자치도 서귀포시 안덕면 동광로 107', 33.3064900, 126.3375981, 'HISTORY', 2, '동광리농촌체험마을은 안덕면 동광리에서 운영하는 녹색 농촌 체험 마을이다.', '동광리농촌체험마을은 안덕면 동광리에서 운영하는 녹색 농촌 체험 마을이다. 동광마을은 해발 200m~400m에 위치하며 한라산 남서 사면의 완만한 용암 평원에 입지한 중산간 내륙의 산촌으로 크고 작은 오름과 숲으로 둘러싸여 있다. 제주 4·3 사건의 아픔을 겪었던 마을로 잃어버린 마을과 표석비, 주민들의 피난처였던 큰넓궤, 한 묘, 돌다리 등 4·3 유적지가 남아있다. 체험마을은 폐교된 동광 분교를 리모델링했으며 관광객 및 제주도민들을 위한 농촌 체험 프로그램이 항상 준비되어 있다. 프로그램으로는 눈썰매 타기 및 연날리기 체험, 한우 사육 및 조랑말 체험 활동, 고사리 꺾기와 야생화 관찰, 돌담 쌓기와 젖소 체험 활동, 오름 탐사 및 동식물 탐사 체험, 4·3유적지 탐사, 민속놀이 체험, 감자범벅 만들기와 맷돌 갈기, 대나무 활쏘기 및 대나무 물총 만들기, 핸드폰과 열쇠고리 만들기 등이 있다. 이 밖에 방문자 센터, 숙박 시설, 천연잔디구장을 비롯한 체육시설 등을 마련해 다양한 프로그램의 장으로 활용하고 있다. 또한 북오름 생태공원 산책로를 방문자 센터와 연결해 방문객들이 오름을 등반하며 아름다운 자연 생태를 직접 느끼도록 조성했다. 북오름과 거린오름, 곶자왈이 가까이 있고 마라도를 볼 수 있는 아름다운 풍광도 갖고 있다. 2016년에 농림축산식품부와 한국농어촌공사가 추천하는 농촌관광코스 10선에 선정되기도 했다.', 'https://tong.visitkorea.or.kr/cms/resource/15/3024315_image2_1.jpg'),
(331, '돌하르방박물관', '제주특별자치도 제주시 조천읍 북촌서1길 70', 33.5389838, 126.6886802, 'CULTURE', 1, '보통 제주에서 돌하르방박물관이라고 부르는 곳은 조천읍 북촌리에 있는 북촌돌하르방미술관을 말한다.', '보통 제주에서 돌하르방박물관이라고 부르는 곳은 조천읍 북촌리에 있는 북촌돌하르방미술관을 말한다. 제주 곳곳에 있는 전통 돌하르방을 재현해 전시하고, 현대적으로 재해석한 돌하르방과 여러 조형물도 함께 볼 수 있는 야외 미술관·문화공원이다.', 'https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcS9htFCViPwM4eu1EukA8aQL26910LsXQAZrDxBuoI4eexiM8nXa8hfxVA&s=10'),
(332, '메이즈랜드', '제주특별자치도 제주시 구좌읍 비자림로 2134-47', 33.4890306, 126.8011034, 'THEME', 1, '현무암으로 조성된 세계 최장 석축 미로공원, 메이즈랜드', '현무암으로 조성된 세계 최장 석축 미로공원, 메이즈랜드', 'https://api.cdn.visitjeju.net/photomng/imgpath/202407/08/01090aef-03ad-472b-a054-75636fc88679.webp'),
(333, '장안사', '제주특별자치도 제주시 서해안로 195', 33.5062184, 126.4684575, 'HISTORY', 4, '제주시 도두동 해안도로 인근에 위치한 불교 사찰입니다.', '제주시 도두동 해안도로 인근에 위치한 불교 사찰입니다.
대규모 관광 사찰보다는 조용하게 참배하고 머무르는 지역 종교시설 성격이 강한 곳입니다.
도두봉과 제주 해안 일정을 함께 둘러보기 좋은 비교적 한적한 장소입니다.', 'https://mblogthumb-phinf.pstatic.net/MjAxNzA1MjNfNTUg/MDAxNDk1NDkzODIwMjc0.3epi92Sb1GO2oM5hRGv7WykLN534VjjvFGxs6LMy_fUg.2SguMCcJrQzUeHLFcytWZuDqDBTPepiMKt7xzveW6_kg.JPEG.seosanpark/DSC_4375.JPG?type=w800'),
(334, 'MUSEUMARARIO', '제주특별자치도 제주시 산지로 37-5', 33.5135631, 126.5284367, 'CULTURE', 4, '이곳은 국내 최고 미술품 수집가 중 한 명으로 꼽히는 김창일 회장이 제주도 탑동 인근 옛 도심에 위치한 버려진 영화관 건물을 개조하여 설립한…', '이곳은 국내 최고 미술품 수집가 중 한 명으로 꼽히는 김창일 회장이 제주도 탑동 인근 옛 도심에 위치한 버려진 영화관 건물을 개조하여 설립한 현대미술관입니다. 건물을 대대적으로 개보수하는 대신 과거의 흔적을 그대로 보존함으로써, 방문객들은 현대미술뿐 아니라 옛 도심의 정취까지 느낄 수 있습니다. 세계적으로 유명한 작가들의 작품을 비롯해 다양한 명작들을 만나볼 수 있는 곳입니다.…', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/8c7338f9-3d9b-4128-a6b1-a2ac1ce4408c.webp'),
(335, '새미오름', '제주특별자치도 제주시 구좌읍 송당리 산 145임', 33.4502222, 126.7601306, 'NATURE', 1, '솟아난 물이 바다쪽으로 흐르지 않고 한라산쪽으로 거슬러 흐른다는 뜻의 오름', '솟아난 물이 바다쪽으로 흐르지 않고 한라산쪽으로 거슬러 흐른다는 뜻의 오름', 'https://api.cdn.visitjeju.net/photomng/imgpath/201804/30/7748715d-18cb-4e32-bee9-f8ff0b4dcbd9.webp'),
(336, '제주현대미술관', '제주특별자치도 제주시 한경면 저지14길 35', 33.3396445, 126.2655849, 'CULTURE', 2, '저지문화에술이마을에 자리한 현대미술관', '저지문화에술이마을에 자리한 현대미술관', 'https://api.cdn.visitjeju.net/photomng/imgpath/202111/11/0122a955-3f3e-4f56-b3b9-907c11ba5a46.webp'),
(337, '제주조각공원', '제주특별자치도 서귀포시 안덕면 일주서로 1836', 33.2516367, 126.3216697, 'THEME', 2, '제주조각공원은 각박한 현실을 사는 모두의 정신 재충전을 목표로 제주 고유의 원시림 13만평에 한국 조각계의 중추적인 현역작가들이 총망라되어 주…', '제주조각공원은 각박한 현실을 사는 모두의 정신 재충전을 목표로 제주 고유의 원시림 13만평에 한국 조각계의 중추적인 현역작가들이 총망라되어 주옥같은 작품 190여점이 조화롭게 전시되어 있는 국내 유일 최대의 본격적인 조각공원입니다.', 'https://cdn.visitkorea.or.kr/img/call?cmd=VIEW&id=c45f218b-47a3-4e0f-8394-bd31f3adac8b'),
(338, '성읍승마장', '제주특별자치도 서귀포시 표선면 성읍리 2055임', 33.3978144, 126.7864945, 'EXPERIENCE', 1, '성읍 승마장은 30년 전통의 전문 승마 체험장이다.', '성읍 승마장은 30년 전통의 전문 승마 체험장이다. 제주도 최초의 승마장이기도 한 이곳은, 제주도 내 최대 길이를 자랑하는 장거리 외승코스를 보유하고 있다. 조끼, 부츠, 승마모자, 헬멧 등의 승마 장비는 무료로 대여할 수 있으며, 목장 안을 도는 기본체험코스와 목장 밖으로 멀리 나가는 고급 승마코스 중 하나를 선택할 수 있는데, 1시간 이상의 외승코스 이용 시에는 꼭 예약을 해야 한다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201907/29/e6d91250-4fe2-4569-a3f9-aadea646f0f0.webp'),
(339, '법정사', '제주특별자치도 서귀포시 1100로 740-168', 33.3098908, 126.4743592, 'TRAIL', 3, '1911년 9월 [봉려관] 스님이 창건한 사찰로, [제주 최초이자 최대 규모의 무장 항일 운동]인 무오법정사 항일운동의 발상지입니다.', '1911년 9월 [봉려관] 스님이 창건한 사찰로, [제주 최초이자 최대 규모의 무장 항일 운동]인 무오법정사 항일운동의 발상지입니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201810/19/9dc8d52e-60ff-4793-a696-de5f9891f4a9.webp'),
(340, '국립제주박물관', '제주특별자치도 제주시 일주동로 17', 33.5130309, 126.5487288, 'HISTORY', 4, '국립제주박물관은 제주의 선사 시대부터 조선 시대까지의 역사와 독특한 문화를 보여주는 국립제주박물관입니다.', '국립제주박물관은 제주의 선사 시대부터 조선 시대까지의 역사와 독특한 문화를 보여주는 국립제주박물관입니다.', 'https://api.cdn.visitjeju.net/photomng/imgpath/201806/28/a9a2562a-6f36-4223-b185-9d250af3306a.webp'),
(341, '용마마을', '제주특별자치도 제주시 용담삼동', 33.5147124, 126.5076553, 'TRAIL', 4, '용마마을은 제주시 용담3동, 제주공항 근처 서해안로에 있는 비행기 포토스팟으로, 머리 위로 낮게 지나가는 비행기를 배경으로 사진을 남기기 좋은…', '용마마을은 제주시 용담3동, 제주공항 근처 서해안로에 있는 비행기 포토스팟으로, 머리 위로 낮게 지나가는 비행기를 배경으로 사진을 남기기 좋은 장소이다.', 'https://blog.kakaocdn.net/dna/qmzGo/btsIx5ecLTk/AAAAAAAAAAAAAAAAAAAAACJhjtO9URe7PirO3TsSFY5SXEsJ4pM6-Q3B5d9vy_Di/img.jpg?credential=yqXZFxpELC7KVnFOS48ylbz2pIh7yKj8&expires=1790780399&allow_ip=&allow_referer=&signature=xT7uzkAnHYsVLHMl4rNq95djROQ%3D'),
